INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C1','math',5,2,'u3',2,'도형의 이동과 포개어 보기 — 밀기·뒤집기·돌리기를 해도 자리와 방향만 바뀔 뿐 변의 길이·각의 크기·모양·크기는 그대로임을 되짚고, 두 도형이 꼭 같은지는 눈으로가 아니라 포개어 보거나 재어 보아 확인하기',ARRAY['6수03-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C2','math',5,2,'u3',2,'도형의 합동 — 모양과 크기가 같아 포개었을 때 완전히 겹치는 두 도형을 서로 합동이라 하고, 밀거나 뒤집거나 돌려서 겹쳐도 합동이지만 크기가 다르거나 넓이만 같은 도형은 합동이 아님을 알기',ARRAY['6수03-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C3','math',5,2,'u3',3,'대응점·대응변·대응각 — 합동인 두 도형을 포개었을 때 겹치는 점·변·각을 이름 차례가 아니라 겹치는 자리로 찾고, 대응변의 길이와 대응각의 크기가 같음을 이용해 재지 않고 길이·각도·둘레를 구하기',ARRAY['6수03-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C4','math',5,2,'u3',4,'선대칭도형과 대칭축 — 한 직선을 따라 접었을 때 완전히 겹치는 도형과 그 직선(대칭축)을 알고, 대칭축이 도형마다 여러 개일 수 있으며 넓이를 반으로 나누는 선이 모두 대칭축은 아님을 알기',ARRAY['6수03-05']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C5','math',5,2,'u3',5,'선대칭도형의 성질 — 대칭축으로 접어 겹치는 대응점·대응변·대응각을 찾고, 대응변의 길이와 대응각의 크기가 같으며 대칭축은 대응점을 이은 선분을 수직으로 이등분함을 알기',ARRAY['6수03-05']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C6','math',5,2,'u3',6,'선대칭도형 그리기 — 각 꼭짓점에서 대칭축까지의 거리를 재어 대칭축과 수직인 방향으로 반대쪽에 같은 거리만큼 대응점을 찍고(대칭축 위의 점은 그대로) 차례대로 이은 뒤 접어서 확인하기',ARRAY['6수03-05']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C7','math',5,2,'u3',7,'점대칭도형과 대칭의 중심 — 한 점을 중심으로 반 바퀴(180°) 돌렸을 때 완전히 겹치는 도형과 그 점(대칭의 중심, 언제나 하나)을 알고, 가운데에 점이 있다고 점대칭도형인 것은 아니며 접기와 돌리기를 모두 해 보아야 도형을 가를 수 있음을 알기',ARRAY['6수03-05']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C8','math',5,2,'u3',8,'점대칭도형의 성질 — 반 바퀴 돌려 겹치는 대응점·대응변·대응각을 찾고, 대응변의 길이와 대응각의 크기가 같으며 대응점을 이은 선분은 모두 대칭의 중심을 지나고 중심이 그 선분을 이등분함(수직은 아님)을 알기',ARRAY['6수03-05']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C9','math',5,2,'u3',9,'점대칭도형 그리기 — 꼭짓점에서 대칭의 중심까지 간 만큼(가로·세로 칸 수)을 세어 중심을 지나 반대쪽으로 같은 만큼 더 간 자리에 대응점을 찍고 차례대로 이은 뒤 반 바퀴 돌려 확인하기',ARRAY['6수03-05']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u3-C10','math',5,2,'u3',10,'문제 해결 — 땅을 합동인 도형 몇 개로 나눌 때 나눗셈으로 한 조각의 칸 수를 먼저 정하고, 조각들이 서로 합동인지와 조건(나무가 한 그루씩)을 모두 확인하며 「똑같이 나눈다」는 넓이가 같은 것이 아니라 합동이라는 뜻임을 알기',ARRAY['6수03-03']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X01','math',5,'u3',ARRAY['M5-2-u3-C1','M5-2-u3-C2']::text[],'도형을 밀거나 뒤집거나 돌리면 변의 길이·각의 크기·넓이가 달라진다고 여긴다','움직여도 모양과 크기는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X02','math',5,'u3',ARRAY['M5-2-u3-C1','M5-2-u3-C2','M5-2-u3-C10']::text[],'포개거나 재어 보지 않고 겉보기(색·자리·대강의 모양)로 같은 도형인지 판단한다','포개어 보거나 재어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X03','math',5,'u3',ARRAY['M5-2-u3-C2','M5-2-u3-C3']::text[],'모양만 같으면 크기가 달라도 합동이라고 여긴다','크기까지 같아야 합동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X04','math',5,'u3',ARRAY['M5-2-u3-C2']::text[],'뒤집거나 돌려야 겹치는 두 도형은 합동이 아니라고 여긴다','뒤집거나 돌려서 겹쳐도 합동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X05','math',5,'u3',ARRAY['M5-2-u3-C2','M5-2-u3-C10']::text[],'넓이나 둘레가 같으면 합동이라고 여긴다','넓이가 같아도 겹치지 않으면 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X06','math',5,'u3',ARRAY['M5-2-u3-C3','M5-2-u3-C5','M5-2-u3-C8']::text[],'대응점을 겹치는 자리가 아니라 이름 차례나 놓인 자리(왼쪽·위쪽)로 짝짓는다','겹치는 자리끼리 짝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X07','math',5,'u3',ARRAY['M5-2-u3-C3','M5-2-u3-C5','M5-2-u3-C8']::text[],'대응변·대응각을 이웃한 다른 변·각과 헷갈리거나, 대응각의 크기가 다르다고 여긴다','대응변·대응각은 크기가 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X08','math',5,'u3',ARRAY['M5-2-u3-C4']::text[],'대칭축의 개수를 잘못 센다(대각선 대칭축을 빠뜨리거나 대칭축이 아닌 선까지 센다)','접어서 겹치는 선만 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X09','math',5,'u3',ARRAY['M5-2-u3-C4','M5-2-u3-C7']::text[],'도형을 넓이가 같은 둘로 나누는 선은 모두 대칭축이라고 여긴다(직사각형의 대각선 등)','반으로 나누기 ≠ 접어서 겹치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X10','math',5,'u3',ARRAY['M5-2-u3-C5','M5-2-u3-C6','M5-2-u3-C8','M5-2-u3-C9']::text[],'대칭축·대칭의 중심까지의 거리와 대응점 사이의 거리를 헷갈린다(두 배와 절반을 바꾼다)','한쪽 거리 × 2 = 대응점 사이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X11','math',5,'u3',ARRAY['M5-2-u3-C5','M5-2-u3-C6']::text[],'대칭축이 대응점을 이은 선분과 수직으로 만나 똑같이 둘로 나누는 것을 모른다','대칭축은 수직이등분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X12','math',5,'u3',ARRAY['M5-2-u3-C6']::text[],'선대칭도형을 그릴 때 대칭축과 수직인 방향이 아닌 쪽으로 가거나 칸 수를 잘못 세고, 대칭축 위의 점을 옮긴다','수직으로 같은 칸 수만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X13','math',5,'u3',ARRAY['M5-2-u3-C9']::text[],'점대칭도형을 그릴 때 중심까지만 가거나 중심을 지나지 않는 방향으로 대응점을 찍는다','중심을 지나 같은 만큼 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X14','math',5,'u3',ARRAY['M5-2-u3-C7']::text[],'가운데에 점이 있으면 점대칭도형이라고 여기거나, 반 바퀴가 아닌 만큼 돌려서 판단한다','반 바퀴 돌려 겹치는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X15','math',5,'u3',ARRAY['M5-2-u3-C4','M5-2-u3-C5','M5-2-u3-C7','M5-2-u3-C8','M5-2-u3-C9']::text[],'선대칭과 점대칭을 섞는다 — 접기와 돌리기, 대칭축과 대칭의 중심, 수직이등분과 이등분을 바꿔 말한다','선대칭은 접기, 점대칭은 돌리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X16','math',5,'u3',ARRAY['M5-2-u3-C10']::text[],'문제 해결에서 조건 하나만 보고(칸 수만, 나무 자리는 빼고) 나누거나 나눗셈으로 한 조각의 칸 수를 구하지 못한다','칸 수 정하기 → 두 조건 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u3-X17','math',5,'u3',ARRAY['M5-2-u3-C1','M5-2-u3-C2','M5-2-u3-C3','M5-2-u3-C4','M5-2-u3-C5','M5-2-u3-C6','M5-2-u3-C7','M5-2-u3-C8','M5-2-u3-C9','M5-2-u3-C10']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 아닌↔인, 틀린↔알맞은, 대응점↔대응변','물음의 「아닌·틀린」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_basic#1','math',5,2,'u3','L02','g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C1',1,'mc','auto','도형을 오른쪽으로 5칸 밀었을 때 달라지는 것은 어느 것인가요?',ARRAY['M5-2-u3-X01']::text[],true,'{"seq":1,"concept":"M5-2-u3-C1","difficulty":1,"kind":"mc","stem":"도형을 오른쪽으로 5칸 밀었을 때 달라지는 것은 어느 것인가요?","options":[{"t":"도형이 놓인 자리","correct":true},{"t":"변의 길이","mis":"M5-2-u3-X01"},{"t":"각의 크기","mis":"M5-2-u3-X01"},{"t":"변의 개수","mis":"M5-2-u3-X01"}],"explanation":["밀기는 도형을 움직이는 방법이에요.","움직여도 변의 길이·각의 크기·변의 개수는 그대로예요.","바뀌는 것은 도형이 놓인 자리뿐이에요."],"variant_rule":{"alt":[{"stem":"도형을 왼쪽으로 뒤집었을 때 달라지는 것은 어느 것인가요?","options":[{"t":"도형이 놓인 방향","correct":true},{"t":"변의 길이","mis":"M5-2-u3-X01"},{"t":"각의 크기","mis":"M5-2-u3-X01"},{"t":"변의 개수","mis":"M5-2-u3-X01"}],"explanation":["뒤집기는 도형을 움직이는 방법이에요.","움직여도 변의 길이·각의 크기·변의 개수는 그대로예요.","바뀌는 것은 도형이 놓인 방향뿐이에요."]},{"stem":"도형을 시계 방향으로 반 바퀴 돌렸을 때 달라지는 것은 어느 것인가요?","options":[{"t":"도형이 놓인 방향","correct":true},{"t":"변의 길이","mis":"M5-2-u3-X01"},{"t":"각의 크기","mis":"M5-2-u3-X01"},{"t":"변의 개수","mis":"M5-2-u3-X01"}],"explanation":["돌리기는 도형을 움직이는 방법이에요.","움직여도 변의 길이·각의 크기·변의 개수는 그대로예요.","바뀌는 것은 도형이 놓인 방향뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_basic#2','math',5,2,'u3','L02','g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C1',1,'sa','auto','한 변이 5 cm인 정사각형을 시계 방향으로 반 바퀴 돌렸을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C1","difficulty":1,"kind":"sa","stem":"한 변이 5 cm인 정사각형을 시계 방향으로 반 바퀴 돌렸을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["돌리기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 5 cm예요."],"mis":"M5-2-u3-X01","variant_rule":{"alt":[{"stem":"가로 6 cm, 세로 3 cm인 직사각형을 왼쪽으로 뒤집었을 때, 움직인 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["뒤집기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 3 cm예요."]},{"stem":"한 변이 7 cm인 정사각형을 오른쪽으로 5칸 밀었을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["밀기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_basic#3','math',5,2,'u3','L02','g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C1',1,'mc','auto','두 도형이 꼭 같은지 가장 확실하게 알아보는 방법은 어느 것인가요?',ARRAY['M5-2-u3-X02']::text[],true,'{"seq":3,"concept":"M5-2-u3-C1","difficulty":1,"kind":"mc","stem":"두 도형이 꼭 같은지 가장 확실하게 알아보는 방법은 어느 것인가요?","options":[{"t":"한쪽을 오려 다른 쪽 위에 포개어 본다","correct":true},{"t":"색이 같은지 본다","mis":"M5-2-u3-X02"},{"t":"멀리서 바라본다","mis":"M5-2-u3-X02"},{"t":"변의 개수만 센다","mis":"M5-2-u3-X02"}],"explanation":["비슷해 보인다고 꼭 같은 것은 아니에요.","포개어 보면 조금만 달라도 삐져나와 알 수 있어요.","그래서 포개어 보거나 재어 보아야 해요."],"variant_rule":{"alt":[{"stem":"두 딱지의 모양과 크기가 같은지 알아보는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 딱지를 겹쳐서 꼭 맞는지 본다","correct":true},{"t":"딱지의 색깔을 견준다","mis":"M5-2-u3-X02"},{"t":"딱지가 놓인 자리를 견준다","mis":"M5-2-u3-X02"},{"t":"꼭짓점의 개수만 센다","mis":"M5-2-u3-X02"}],"explanation":["비슷해 보인다고 꼭 같은 것은 아니에요.","포개어 보면 조금만 달라도 삐져나와 알 수 있어요.","그래서 포개어 보거나 재어 보아야 해요."]},{"stem":"한 변이 1 mm만 달라도 눈으로는 알아채기 어려워요. 두 도형이 같은지 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"포개어 보거나 변의 길이와 각의 크기를 재어 본다","correct":true},{"t":"눈으로 얼른 보아 비슷하면 같다고 한다","mis":"M5-2-u3-X02"},{"t":"둘레를 대강 어림해 본다","mis":"M5-2-u3-X05"},{"t":"도형이 놓인 방향만 견준다","mis":"M5-2-u3-X02"}],"explanation":["비슷해 보인다고 꼭 같은 것은 아니에요.","포개어 보면 조금만 달라도 삐져나와 알 수 있어요.","그래서 포개어 보거나 재어 보아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_basic#4','math',5,2,'u3','L02','g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',1,'mc','auto','두 도형이 서로 합동이라는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X02','M5-2-u3-X03','M5-2-u3-X05']::text[],true,'{"seq":4,"concept":"M5-2-u3-C2","difficulty":1,"kind":"mc","stem":"두 도형이 서로 합동이라는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"모양과 크기가 같아 포개었을 때 완전히 겹친다","correct":true},{"t":"두 도형의 색이 같다","mis":"M5-2-u3-X02"},{"t":"변의 개수만 같다","mis":"M5-2-u3-X03"},{"t":"넓이만 같다","mis":"M5-2-u3-X05"}],"explanation":["모양과 크기가 같아 포개었을 때 완전히 겹치는 두 도형을 서로 합동이라고 해요.","색·자리·방향은 상관없어요.","넓이만 같아서는 겹치지 않을 수 있어요."],"variant_rule":{"alt":[{"stem":"모양과 크기가 같아서 포개었을 때 완전히 겹치는 두 도형을 무엇이라고 하나요?","options":[{"t":"서로 합동인 도형","correct":true},{"t":"선대칭도형","mis":"M5-2-u3-X15"},{"t":"점대칭도형","mis":"M5-2-u3-X15"},{"t":"넓이가 같은 도형","mis":"M5-2-u3-X05"}],"explanation":["모양과 크기가 같아 포개었을 때 완전히 겹치는 두 도형을 서로 합동이라고 해요.","색·자리·방향은 상관없어요.","넓이만 같아서는 겹치지 않을 수 있어요."]},{"stem":"두 도형이 서로 합동인지 정하는 기준은 어느 것인가요?","options":[{"t":"포개었을 때 완전히 겹치는가","correct":true},{"t":"같은 쪽을 보고 있는가","mis":"M5-2-u3-X04"},{"t":"넓이가 같은가","mis":"M5-2-u3-X05"},{"t":"색이 같은가","mis":"M5-2-u3-X02"}],"explanation":["모양과 크기가 같아 포개었을 때 완전히 겹치는 두 도형을 서로 합동이라고 해요.","색·자리·방향은 상관없어요.","넓이만 같아서는 겹치지 않을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_basic#5','math',5,2,'u3','L02','g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C1',2,'sa','auto','한 변이 5 cm인 정사각형 모양 딱지를 반 바퀴 돌렸어요. 돌린 딱지의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u3-C1","difficulty":2,"kind":"sa","stem":"한 변이 5 cm인 정사각형 모양 딱지를 반 바퀴 돌렸어요. 돌린 딱지의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["돌리거나 뒤집어도 변의 길이는 그대로예요.","그래서 움직이기 전 도형의 둘레를 구하면 돼요.","정사각형의 둘레는 5 × 4 = 20(cm)예요."],"mis":"M5-2-u3-X01","variant_rule":{"alt":[{"stem":"가로 6 cm, 세로 3 cm인 직사각형 모양 색종이를 뒤집었어요. 뒤집은 색종이의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["돌리거나 뒤집어도 변의 길이는 그대로예요.","그래서 움직이기 전 도형의 둘레를 구하면 돼요.","직사각형의 둘레는 (6 + 3) × 2 = 18(cm)예요."]},{"stem":"한 변이 8 cm인 정사각형 모양 딱지를 반 바퀴 돌렸어요. 돌린 딱지의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["돌리거나 뒤집어도 변의 길이는 그대로예요.","그래서 움직이기 전 도형의 둘레를 구하면 돼요.","정사각형의 둘레는 8 × 4 = 32(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_basic#6','math',5,2,'u3','L02','g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',2,'mc','auto','한 도형을 뒤집어야 다른 도형과 완전히 겹친다면 두 도형은 어떤가요?',ARRAY['M5-2-u3-X04','M5-2-u3-X01']::text[],true,'{"seq":6,"concept":"M5-2-u3-C2","difficulty":2,"kind":"mc","stem":"한 도형을 뒤집어야 다른 도형과 완전히 겹친다면 두 도형은 어떤가요?","options":[{"t":"서로 합동이다","correct":true},{"t":"합동이 아니다","mis":"M5-2-u3-X04"},{"t":"크기가 달라진 것이다","mis":"M5-2-u3-X01"},{"t":"각의 크기가 달라진 것이다","mis":"M5-2-u3-X01"}],"explanation":["뒤집기는 자리나 방향만 바꾸고 길이와 각을 건드리지 않아요.","그렇게 해서 완전히 겹치면 모양과 크기가 같은 거예요.","그래서 서로 합동이에요."],"variant_rule":{"alt":[{"stem":"한 도형을 돌려야 다른 도형과 완전히 겹친다면 두 도형은 어떤가요?","options":[{"t":"서로 합동이다","correct":true},{"t":"합동이 아니다","mis":"M5-2-u3-X04"},{"t":"크기가 달라진 것이다","mis":"M5-2-u3-X01"},{"t":"각의 크기가 달라진 것이다","mis":"M5-2-u3-X01"}],"explanation":["돌리기는 자리나 방향만 바꾸고 길이와 각을 건드리지 않아요.","그렇게 해서 완전히 겹치면 모양과 크기가 같은 거예요.","그래서 서로 합동이에요."]},{"stem":"한 도형을 밀어야 다른 도형과 완전히 겹친다면 두 도형은 어떤가요?","options":[{"t":"서로 합동이다","correct":true},{"t":"합동이 아니다","mis":"M5-2-u3-X04"},{"t":"크기가 달라진 것이다","mis":"M5-2-u3-X01"},{"t":"각의 크기가 달라진 것이다","mis":"M5-2-u3-X01"}],"explanation":["밀기는 자리나 방향만 바꾸고 길이와 각을 건드리지 않아요.","그렇게 해서 완전히 겹치면 모양과 크기가 같은 거예요.","그래서 서로 합동이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_basic#7','math',5,2,'u3','L02','g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',2,'mc','auto','모양은 같지만 크기가 다른 두 정사각형에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X03']::text[],true,'{"seq":7,"concept":"M5-2-u3-C2","difficulty":2,"kind":"mc","stem":"모양은 같지만 크기가 다른 두 정사각형에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"합동이 아니다","correct":true},{"t":"합동이다","mis":"M5-2-u3-X03"},{"t":"돌리면 합동이 된다","mis":"M5-2-u3-X03"},{"t":"뒤집으면 합동이 된다","mis":"M5-2-u3-X03"}],"explanation":["합동은 모양과 크기가 모두 같아야 해요.","크기가 다르면 아무리 밀고 뒤집고 돌려도 완전히 겹치지 않아요.","그래서 합동이 아니에요."],"variant_rule":{"alt":[{"stem":"모양은 같지만 크기가 다른 두 정삼각형에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"합동이 아니다","correct":true},{"t":"합동이다","mis":"M5-2-u3-X03"},{"t":"돌리면 합동이 된다","mis":"M5-2-u3-X03"},{"t":"뒤집으면 합동이 된다","mis":"M5-2-u3-X03"}],"explanation":["합동은 모양과 크기가 모두 같아야 해요.","크기가 다르면 아무리 밀고 뒤집고 돌려도 완전히 겹치지 않아요.","그래서 합동이 아니에요."]},{"stem":"모양은 같지만 크기가 다른 두 원에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"합동이 아니다","correct":true},{"t":"합동이다","mis":"M5-2-u3-X03"},{"t":"돌리면 합동이 된다","mis":"M5-2-u3-X03"},{"t":"뒤집으면 합동이 된다","mis":"M5-2-u3-X03"}],"explanation":["합동은 모양과 크기가 모두 같아야 해요.","크기가 다르면 아무리 밀고 뒤집고 돌려도 완전히 겹치지 않아요.","그래서 합동이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_basic#8','math',5,2,'u3','L02','g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',2,'ox','auto','뒤집어야 겹치는 두 도형은 서로 합동이 아니에요.',ARRAY['M5-2-u3-X04']::text[],true,'{"seq":8,"concept":"M5-2-u3-C2","difficulty":2,"kind":"ox","stem":"뒤집어야 겹치는 두 도형은 서로 합동이 아니에요.","answer":"X","reason_options":[{"t":"뒤집어서라도 완전히 겹치면 합동이므로","correct":true},{"t":"같은 쪽을 보고 있어야 합동이므로","mis":"M5-2-u3-X04"}],"mis":"M5-2-u3-X04","explanation":["뒤집기는 길이와 각을 바꾸지 않아요.","뒤집어 완전히 겹치면 모양과 크기가 같아요.","그래서 서로 합동이에요 — 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"크기가 다른 두 정사각형은 서로 합동이 아니에요.","answer":"O","reason_options":[{"t":"크기가 다르면 어떻게 해도 완전히 겹치지 않으므로","correct":true},{"t":"정사각형끼리는 언제나 합동이므로","mis":"M5-2-u3-X03"}],"explanation":["합동은 모양과 크기가 모두 같아야 해요.","크기가 다르면 한쪽이 삐져나와요.","그래서 맞는 말이에요."]},{"stem":"돌려서 완전히 겹치는 두 도형은 서로 합동이에요.","answer":"O","reason_options":[{"t":"돌리기는 크기를 바꾸지 않고 완전히 겹치기만 하면 합동이므로","correct":true},{"t":"처음 놓인 그대로 겹쳐야 합동이므로","mis":"M5-2-u3-X04"}],"explanation":["돌리기는 방향만 바꿔요.","돌려서 완전히 겹쳤다면 모양과 크기가 같아요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
