INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_basic#10','math',5,2,'u3','L02','g5_2_math_u3_L02_basic','lesson_basic','M5-2-u3-C2',3,'mc','auto','모눈 위의 도형 가운데 ㉮와 넓이는 같지만 합동이 아닌 도형은 어느 것인가요?',ARRAY['M5-2-u3-X03','M5-2-u3-X04','M5-2-u3-X17']::text[],true,'{"seq":10,"concept":"M5-2-u3-C2","difficulty":3,"kind":"mc","stem":"모눈 위의 도형 가운데 ㉮와 넓이는 같지만 합동이 아닌 도형은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉯","mis":"M5-2-u3-X03"},{"t":"㉰","mis":"M5-2-u3-X04"},{"t":"㉮","mis":"M5-2-u3-X17"}],"explanation":["㉱는 ㉮와 칸 수가 같아 넓이가 같아요.","그런데 모양이 달라 포개도 겹치지 않아요.","넓이가 같다고 합동인 것은 아니에요."],"asset":{"type":"geo","items":[{"w":80,"h":80,"poly":[[[20,20],[60,20],[60,40],[40,40],[40,60],[20,60]]],"grid":20},{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,60],[60,60],[60,100],[20,100]]],"grid":20},{"w":80,"h":80,"poly":[[[20,20],[40,20],[40,40],[60,40],[60,60],[20,60]]],"grid":20},{"w":100,"h":60,"poly":[[[20,20],[80,20],[80,40],[20,40]]],"grid":20}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 위의 도형 가운데 ㉮와 넓이는 같지만 합동이 아닌 도형은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉰","mis":"M5-2-u3-X03"},{"t":"㉱","mis":"M5-2-u3-X04"},{"t":"㉮","mis":"M5-2-u3-X17"}],"explanation":["㉯는 ㉮와 칸 수가 같아 넓이가 같아요.","그런데 모양이 달라 포개도 겹치지 않아요.","넓이가 같다고 합동인 것은 아니에요."],"asset":{"type":"geo","items":[{"w":100,"h":80,"poly":[[[20,20],[80,20],[80,40],[60,40],[60,60],[40,60],[40,40],[20,40]]],"grid":20},{"w":80,"h":80,"poly":[[[20,20],[60,20],[60,60],[20,60]]],"grid":20},{"w":160,"h":120,"poly":[[[20,20],[140,20],[140,60],[100,60],[100,100],[60,100],[60,60],[20,60]]],"grid":20},{"w":100,"h":80,"poly":[[[40,20],[60,20],[60,40],[80,40],[80,60],[20,60],[20,40],[40,40]]],"grid":20}]}},{"stem":"이번에는 다른 보기예요. 모눈 위의 도형 가운데 ㉮와 넓이는 같지만 합동이 아닌 도형은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉱","mis":"M5-2-u3-X03"},{"t":"㉯","mis":"M5-2-u3-X04"},{"t":"㉮","mis":"M5-2-u3-X17"}],"explanation":["㉰는 ㉮와 칸 수가 같아 넓이가 같아요.","그런데 모양이 달라 포개도 겹치지 않아요.","넓이가 같다고 합동인 것은 아니에요."],"asset":{"type":"geo","items":[{"w":100,"h":80,"poly":[[[20,20],[60,20],[60,40],[80,40],[80,60],[40,60],[40,40],[20,40]]],"grid":20},{"w":100,"h":80,"poly":[[[40,20],[80,20],[80,40],[60,40],[60,60],[20,60],[20,40],[40,40]]],"grid":20},{"w":120,"h":60,"poly":[[[20,20],[100,20],[100,40],[20,40]]],"grid":20},{"w":160,"h":120,"poly":[[[20,20],[100,20],[100,60],[140,60],[140,100],[60,100],[60,60],[20,60]]],"grid":20}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_challenge#1','math',5,2,'u3','L02','g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C1',2,'sa','auto','한 변이 4 cm인 정사각형 모양 딱지 2장을 겹치지 않게 늘어놓았어요. 딱지들의 둘레를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C1","difficulty":2,"kind":"sa","stem":"한 변이 4 cm인 정사각형 모양 딱지 2장을 겹치지 않게 늘어놓았어요. 딱지들의 둘레를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["딱지 한 장의 둘레는 4 × 4 = 16(cm)예요.","늘어놓기만 했으니 한 장 한 장의 둘레는 그대로예요.","16 × 2 = 32(cm)예요."],"mis":"M5-2-u3-X01","variant_rule":{"alt":[{"stem":"한 변이 3 cm인 정사각형 모양 딱지 5장을 겹치지 않게 늘어놓았어요. 딱지들의 둘레를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["딱지 한 장의 둘레는 3 × 4 = 12(cm)예요.","늘어놓기만 했으니 한 장 한 장의 둘레는 그대로예요.","12 × 5 = 60(cm)예요."]},{"stem":"한 변이 6 cm인 정사각형 모양 딱지 3장을 겹치지 않게 늘어놓았어요. 딱지들의 둘레를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["딱지 한 장의 둘레는 6 × 4 = 24(cm)예요.","늘어놓기만 했으니 한 장 한 장의 둘레는 그대로예요.","24 × 3 = 72(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_challenge#2','math',5,2,'u3','L02','g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',2,'sa','auto','두 삼각형은 서로 합동이에요. 한 삼각형의 밑변이 4 cm일 때, 다른 삼각형에서 그 변과 겹치는 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C2","difficulty":2,"kind":"sa","stem":"두 삼각형은 서로 합동이에요. 한 삼각형의 밑변이 4 cm일 때, 다른 삼각형에서 그 변과 겹치는 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["합동인 두 도형은 포개면 완전히 겹쳐요.","겹치는 변끼리는 길이가 같아요.","그래서 4 cm예요."],"mis":"M5-2-u3-X01","variant_rule":{"alt":[{"stem":"두 사다리꼴은 서로 합동이에요. 한 사다리꼴의 가장 긴 변이 7 cm일 때, 다른 사다리꼴에서 그 변과 겹치는 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["합동인 두 도형은 포개면 완전히 겹쳐요.","겹치는 변끼리는 길이가 같아요.","그래서 7 cm예요."]},{"stem":"두 평행사변형은 서로 합동이에요. 한 평행사변형의 긴 변이 9 cm일 때, 다른 평행사변형에서 그 변과 겹치는 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["합동인 두 도형은 포개면 완전히 겹쳐요.","겹치는 변끼리는 길이가 같아요.","그래서 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_challenge#3','math',5,2,'u3','L02','g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',3,'mc','auto','두 도형이 서로 합동인지 알아볼 때 확인하지 않아도 되는 것은 어느 것인가요?',ARRAY['M5-2-u3-X17']::text[],true,'{"seq":3,"concept":"M5-2-u3-C2","difficulty":3,"kind":"mc","stem":"두 도형이 서로 합동인지 알아볼 때 확인하지 않아도 되는 것은 어느 것인가요?","options":[{"t":"도형의 색","correct":true},{"t":"변의 길이","mis":"M5-2-u3-X17"},{"t":"각의 크기","mis":"M5-2-u3-X17"},{"t":"포개었을 때 완전히 겹치는지","mis":"M5-2-u3-X17"}],"explanation":["합동은 모양과 크기가 같아 완전히 겹치는 것이에요.","그래서 변의 길이·각의 크기·겹치는지를 봐요.","도형의 색은 합동과 상관없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 도형이 서로 합동인지 알아볼 때 확인하지 않아도 되는 것은 어느 것인가요?","options":[{"t":"도형이 놓인 자리","correct":true},{"t":"변의 길이","mis":"M5-2-u3-X17"},{"t":"각의 크기","mis":"M5-2-u3-X17"},{"t":"포개었을 때 완전히 겹치는지","mis":"M5-2-u3-X17"}],"explanation":["합동은 모양과 크기가 같아 완전히 겹치는 것이에요.","그래서 변의 길이·각의 크기·겹치는지를 봐요.","도형이 놓인 자리는 합동과 상관없어요."]},{"stem":"이번에는 다른 보기예요. 두 도형이 서로 합동인지 알아볼 때 확인하지 않아도 되는 것은 어느 것인가요?","options":[{"t":"도형이 놓인 방향","correct":true},{"t":"변의 길이","mis":"M5-2-u3-X17"},{"t":"각의 크기","mis":"M5-2-u3-X17"},{"t":"포개었을 때 완전히 겹치는지","mis":"M5-2-u3-X17"}],"explanation":["합동은 모양과 크기가 같아 완전히 겹치는 것이에요.","그래서 변의 길이·각의 크기·겹치는지를 봐요.","도형이 놓인 방향은 합동과 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_challenge#4','math',5,2,'u3','L02','g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',3,'error','auto','친구들이 합동에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u3-X05','M5-2-u3-X04','M5-2-u3-X03']::text[],true,'{"seq":4,"concept":"M5-2-u3-C2","difficulty":3,"kind":"error","stem":"친구들이 합동에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「넓이가 같으니까 두 도형은 합동이야.」","correct":true,"mis_target":"M5-2-u3-X05"},{"t":"도윤 — 「뒤집어서 겹치니까 합동이야.」","mis":"M5-2-u3-X04"},{"t":"하린 — 「크기가 다르니까 합동이 아니야.」","mis":"M5-2-u3-X03"}],"explanation":["합동은 포개었을 때 완전히 겹치는 것이에요.","밀기·뒤집기·돌리기로 겹쳐도 합동이고, 크기가 다르거나 모양이 다르면 아니에요.","수아의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 합동에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「뒤집어야 겹치니까 합동이 아니야.」","correct":true,"mis_target":"M5-2-u3-X04"},{"t":"서연 — 「돌려서 겹치니까 합동이야.」","mis":"M5-2-u3-X04"},{"t":"지호 — 「모양이 같아도 크기가 다르면 합동이 아니야.」","mis":"M5-2-u3-X03"}],"explanation":["합동은 포개었을 때 완전히 겹치는 것이에요.","밀기·뒤집기·돌리기로 겹쳐도 합동이고, 크기가 다르거나 모양이 다르면 아니에요.","민준의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 합동에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「모양이 같으니까 크기가 달라도 합동이야.」","correct":true,"mis_target":"M5-2-u3-X03"},{"t":"나린 — 「포개어 완전히 겹치니까 합동이야.」","mis":"M5-2-u3-X02"},{"t":"유진 — 「넓이가 같아도 모양이 다르면 합동이 아니야.」","mis":"M5-2-u3-X05"}],"explanation":["합동은 포개었을 때 완전히 겹치는 것이에요.","밀기·뒤집기·돌리기로 겹쳐도 합동이고, 크기가 다르거나 모양이 다르면 아니에요.","가온의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_challenge#5','math',5,2,'u3','L02','g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C1',3,'ox','auto','도형을 오른쪽으로 밀면 변의 길이가 길어져요.',ARRAY['M5-2-u3-X01']::text[],true,'{"seq":5,"concept":"M5-2-u3-C1","difficulty":3,"kind":"ox","stem":"도형을 오른쪽으로 밀면 변의 길이가 길어져요.","answer":"X","reason_options":[{"t":"밀기는 자리만 옮길 뿐 길이를 바꾸지 않으므로","correct":true},{"t":"움직인 만큼 변이 늘어나므로","mis":"M5-2-u3-X01"}],"mis":"M5-2-u3-X01","explanation":["밀기는 도형의 자리만 옮겨요.","변의 길이와 각의 크기는 그대로예요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"도형을 반 바퀴 돌리면 각의 크기가 반으로 줄어요.","answer":"X","reason_options":[{"t":"돌리기는 방향만 바꾸고 각의 크기는 그대로이므로","correct":true},{"t":"반 바퀴는 반이라서 각도 반이 되므로","mis":"M5-2-u3-X01"}],"explanation":["돌리기는 놓인 방향을 바꿔요.","각이 벌어진 정도는 그대로예요.","그래서 틀린 말이에요."]},{"stem":"비슷해 보이는 두 도형은 포개어 보지 않아도 꼭 같다고 할 수 있어요.","answer":"X","reason_options":[{"t":"조금만 달라도 눈으로는 알기 어려워 포개어 보아야 하므로","correct":true},{"t":"비슷하면 언제나 같은 도형이므로","mis":"M5-2-u3-X02"}],"explanation":["한 변이 1 mm만 길어도 눈으로는 알아채기 어려워요.","포개어 보거나 재어 보아야 알 수 있어요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_challenge#6','math',5,2,'u3','L02','g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',3,'mc','auto','색종이 두 장을 겹쳐서 한 번에 오렸어요. 나온 두 조각에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X03','M5-2-u3-X02','M5-2-u3-X07']::text[],true,'{"seq":6,"concept":"M5-2-u3-C2","difficulty":3,"kind":"mc","stem":"색종이 두 장을 겹쳐서 한 번에 오렸어요. 나온 두 조각에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로 합동이다","correct":true},{"t":"한 장이 더 크다","mis":"M5-2-u3-X03"},{"t":"모양이 서로 다르다","mis":"M5-2-u3-X02"},{"t":"각의 크기가 서로 다르다","mis":"M5-2-u3-X07"}],"explanation":["같은 것을 그대로 본떠 만든 도형은 모양과 크기가 같아요.","포개면 완전히 겹쳐요.","그래서 서로 합동이에요."],"variant_rule":{"alt":[{"stem":"달곰이가 같은 본을 대고 색종이 세 장을 오렸어요. 나온 세 조각에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"세 조각은 서로 합동이다","correct":true},{"t":"먼저 오린 조각이 더 크다","mis":"M5-2-u3-X03"},{"t":"색이 다르면 합동이 아니다","mis":"M5-2-u3-X02"},{"t":"넓이만 같고 모양은 다르다","mis":"M5-2-u3-X05"}],"explanation":["같은 것을 그대로 본떠 만든 도형은 모양과 크기가 같아요.","포개면 완전히 겹쳐요.","그래서 서로 합동이에요."]},{"stem":"도장으로 같은 모양을 두 번 찍었더니 하나는 거꾸로 찍혔어요. 두 모양에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"돌리면 겹치므로 서로 합동이다","correct":true},{"t":"거꾸로 찍혀서 합동이 아니다","mis":"M5-2-u3-X04"},{"t":"거꾸로 찍힌 것이 더 작다","mis":"M5-2-u3-X01"},{"t":"두 모양의 넓이가 다르다","mis":"M5-2-u3-X01"}],"explanation":["같은 것을 그대로 본떠 만든 도형은 모양과 크기가 같아요.","포개면 완전히 겹쳐요.","그래서 서로 합동이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_challenge#7','math',5,2,'u3','L02','g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',3,'sa','auto','한 변이 4 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u3-C2","difficulty":3,"kind":"sa","stem":"한 변이 4 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 4 cm예요.","둘레는 4 × 4 = 16(cm)예요."],"mis":"M5-2-u3-X03","variant_rule":{"alt":[{"stem":"한 변이 7 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 7 cm예요.","둘레는 7 × 4 = 28(cm)예요."]},{"stem":"한 변이 9 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 9 cm예요.","둘레는 9 × 4 = 36(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_challenge#8','math',5,2,'u3','L02','g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',4,'ox','auto','넓이가 같은 두 도형은 언제나 서로 합동이에요.',ARRAY['M5-2-u3-X05']::text[],true,'{"seq":8,"concept":"M5-2-u3-C2","difficulty":4,"kind":"ox","stem":"넓이가 같은 두 도형은 언제나 서로 합동이에요.","answer":"X","reason_options":[{"t":"넓이가 같아도 모양이 다르면 겹치지 않으므로","correct":true},{"t":"넓이가 같으면 크기가 같으므로","mis":"M5-2-u3-X05"}],"mis":"M5-2-u3-X05","explanation":["정사각형 3개로 된 일자 모양과 ㄱ자 모양은 넓이가 같아요.","그런데 포개면 겹치지 않아요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"서로 합동인 두 도형은 둘레의 길이도 같아요.","answer":"O","reason_options":[{"t":"포개면 변끼리 완전히 겹쳐 변의 길이가 모두 같으므로","correct":true},{"t":"합동은 모양만 같으면 되므로","mis":"M5-2-u3-X03"}],"explanation":["합동인 두 도형은 겹치는 변의 길이가 같아요.","변의 길이가 모두 같으니 둘레도 같아요.","그래서 맞는 말이에요."]},{"stem":"색이 다른 두 도형은 서로 합동이 될 수 없어요.","answer":"X","reason_options":[{"t":"합동은 모양과 크기로만 정하고 색과는 상관없으므로","correct":true},{"t":"색까지 같아야 완전히 겹치므로","mis":"M5-2-u3-X02"}],"explanation":["합동은 포개었을 때 완전히 겹치는가로 정해요.","색은 겹치는 것과 상관없어요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_challenge#9','math',5,2,'u3','L02','g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',4,'sa','auto','모눈 위의 ㉯·㉰·㉱·㉲ 가운데 ㉮와 서로 합동인 도형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C2","difficulty":4,"kind":"sa","stem":"모눈 위의 ㉯·㉰·㉱·㉲ 가운데 ㉮와 서로 합동인 도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["㉯와 ㉱는 ㉮를 돌리거나 뒤집으면 완전히 겹쳐요.","크기가 다른 도형과 넓이만 같은 도형은 겹치지 않아요.","그래서 2개예요."],"mis":"M5-2-u3-X04","asset":{"type":"geo","items":[{"w":80,"h":80,"poly":[[[20,20],[60,20],[60,40],[40,40],[40,60],[20,60]]],"grid":20},{"w":80,"h":80,"poly":[[[20,20],[40,20],[40,40],[60,40],[60,60],[20,60]]],"grid":20},{"w":120,"h":120,"poly":[[[20,20],[100,20],[100,60],[60,60],[60,100],[20,100]]],"grid":20},{"w":80,"h":80,"poly":[[[20,60],[40,60],[40,40],[60,40],[60,20],[20,20]]],"grid":20},{"w":100,"h":60,"poly":[[[20,20],[80,20],[80,40],[20,40]]],"grid":20}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 위의 ㉯·㉰·㉱·㉲ 가운데 ㉮와 서로 합동인 도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["㉲와 ㉰는 ㉮를 돌리거나 뒤집으면 완전히 겹쳐요.","크기가 다른 도형과 넓이만 같은 도형은 겹치지 않아요.","그래서 2개예요."],"asset":{"type":"geo","items":[{"w":100,"h":80,"poly":[[[20,20],[80,20],[80,40],[60,40],[60,60],[40,60],[40,40],[20,40]]],"grid":20},{"w":160,"h":120,"poly":[[[20,20],[140,20],[140,60],[100,60],[100,100],[60,100],[60,60],[20,60]]],"grid":20},{"w":100,"h":80,"poly":[[[40,60],[60,60],[60,40],[80,40],[80,20],[20,20],[20,40],[40,40]]],"grid":20},{"w":80,"h":80,"poly":[[[20,20],[60,20],[60,60],[20,60]]],"grid":20},{"w":100,"h":80,"poly":[[[40,20],[60,20],[60,40],[80,40],[80,60],[20,60],[20,40],[40,40]]],"grid":20}]}},{"stem":"이번에는 다른 보기예요. 모눈 위의 ㉯·㉰·㉱·㉲ 가운데 ㉮와 서로 합동인 도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["㉱와 ㉯는 ㉮를 돌리거나 뒤집으면 완전히 겹쳐요.","크기가 다른 도형과 넓이만 같은 도형은 겹치지 않아요.","그래서 2개예요."],"asset":{"type":"geo","items":[{"w":100,"h":80,"poly":[[[20,20],[60,20],[60,40],[80,40],[80,60],[40,60],[40,40],[20,40]]],"grid":20},{"w":100,"h":80,"poly":[[[40,60],[80,60],[80,40],[60,40],[60,20],[20,20],[20,40],[40,40]]],"grid":20},{"w":120,"h":60,"poly":[[[20,20],[100,20],[100,40],[20,40]]],"grid":20},{"w":100,"h":80,"poly":[[[40,20],[80,20],[80,40],[60,40],[60,60],[20,60],[20,40],[40,40]]],"grid":20},{"w":160,"h":120,"poly":[[[20,20],[100,20],[100,60],[140,60],[140,100],[60,100],[60,60],[20,60]]],"grid":20}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L02_challenge#10','math',5,2,'u3','L02','g5_2_math_u3_L02_challenge','lesson_challenge','M5-2-u3-C2',4,'essay','teacher','정사각형 3개가 붙은 일자 모양과 ㄱ자 모양이 있어요. 두 도형의 넓이를 견주고, 두 도형이 서로 합동인지 까닭과 함께 쓰세요. 또 ㄱ자 모양을 뒤집어 놓은 도형은 원래 ㄱ자 모양과 합동인지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C2","difficulty":4,"kind":"essay","stem":"정사각형 3개가 붙은 일자 모양과 ㄱ자 모양이 있어요. 두 도형의 넓이를 견주고, 두 도형이 서로 합동인지 까닭과 함께 쓰세요. 또 ㄱ자 모양을 뒤집어 놓은 도형은 원래 ㄱ자 모양과 합동인지도 쓰세요.","answer_guide":{"answer":"예: 두 도형은 모두 정사각형 3개로 되어 있어 넓이가 같다. 그러나 포개어 보면 모양이 달라 완전히 겹치지 않으므로 서로 합동이 아니다. ㄱ자 모양을 뒤집어 놓은 도형은 다시 뒤집으면 원래 모양과 완전히 겹치므로 서로 합동이다. 합동은 넓이가 아니라 완전히 겹치는가로 정한다.","scoring_points":["두 도형의 넓이가 같다고 썼는가","모양이 달라 겹치지 않으므로 합동이 아니라고 썼는가","뒤집은 도형도 겹치므로 합동이라고 썼는가"]},"explanation":["두 도형 모두 정사각형 3개 — 넓이가 같아요.","포개면 겹치지 않아 합동이 아니에요.","뒤집어 겹치면 합동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_basic#1','math',5,2,'u3','L03','g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',1,'mc','auto','서로 합동인 두 도형을 포개었을 때 겹치는 변을 무엇이라고 하나요?',ARRAY['M5-2-u3-X17','M5-2-u3-X15']::text[],true,'{"seq":1,"concept":"M5-2-u3-C3","difficulty":1,"kind":"mc","stem":"서로 합동인 두 도형을 포개었을 때 겹치는 변을 무엇이라고 하나요?","options":[{"t":"대응변","correct":true},{"t":"대응점","mis":"M5-2-u3-X17"},{"t":"대응각","mis":"M5-2-u3-X17"},{"t":"대칭축","mis":"M5-2-u3-X15"}],"explanation":["겹치는 점은 대응점, 겹치는 변은 대응변, 겹치는 각은 대응각이에요.","모두 포개어 겹치는 자리끼리 짝지은 것이에요.","그래서 대응변이에요."],"variant_rule":{"alt":[{"stem":"서로 합동인 두 도형을 포개었을 때 겹치는 점을 무엇이라고 하나요?","options":[{"t":"대응점","correct":true},{"t":"대응변","mis":"M5-2-u3-X17"},{"t":"대응각","mis":"M5-2-u3-X17"},{"t":"대칭축","mis":"M5-2-u3-X15"}],"explanation":["겹치는 점은 대응점, 겹치는 변은 대응변, 겹치는 각은 대응각이에요.","모두 포개어 겹치는 자리끼리 짝지은 것이에요.","그래서 대응점이에요."]},{"stem":"서로 합동인 두 도형을 포개었을 때 겹치는 각을 무엇이라고 하나요?","options":[{"t":"대응각","correct":true},{"t":"대응점","mis":"M5-2-u3-X17"},{"t":"대응변","mis":"M5-2-u3-X17"},{"t":"대칭축","mis":"M5-2-u3-X15"}],"explanation":["겹치는 점은 대응점, 겹치는 변은 대응변, 겹치는 각은 대응각이에요.","모두 포개어 겹치는 자리끼리 짝지은 것이에요.","그래서 대응각이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_basic#2','math',5,2,'u3','L03','g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',1,'mc','auto','대응점을 정하는 올바른 방법은 어느 것인가요?',ARRAY['M5-2-u3-X06']::text[],true,'{"seq":2,"concept":"M5-2-u3-C3","difficulty":1,"kind":"mc","stem":"대응점을 정하는 올바른 방법은 어느 것인가요?","options":[{"t":"포개었을 때 겹치는 점끼리 짝을 짓는다","correct":true},{"t":"이름 차례대로 짝을 짓는다","mis":"M5-2-u3-X06"},{"t":"왼쪽에 있는 점끼리 짝을 짓는다","mis":"M5-2-u3-X06"},{"t":"위쪽에 있는 점끼리 짝을 짓는다","mis":"M5-2-u3-X06"}],"explanation":["합동인 두 도형은 포개면 완전히 겹쳐요.","겹치는 자리끼리가 짝이에요 — 이름 차례나 놓인 자리가 아니에요.","겹치므로 대응변의 길이와 대응각의 크기가 같아요."],"variant_rule":{"alt":[{"stem":"합동인 두 도형에서 대응변을 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"대응점을 먼저 찾아 대응점끼리 이은 변을 찾는다","correct":true},{"t":"가장 아래에 있는 변끼리 짝짓는다","mis":"M5-2-u3-X06"},{"t":"이름의 첫 글자가 같은 변끼리 짝짓는다","mis":"M5-2-u3-X06"},{"t":"길이를 재지 않고 아무 변이나 짝짓는다","mis":"M5-2-u3-X07"}],"explanation":["합동인 두 도형은 포개면 완전히 겹쳐요.","겹치는 자리끼리가 짝이에요 — 이름 차례나 놓인 자리가 아니에요.","겹치므로 대응변의 길이와 대응각의 크기가 같아요."]},{"stem":"합동인 두 도형에서 재어 보지 않고도 대응변의 길이를 알 수 있는 까닭은 어느 것인가요?","options":[{"t":"포개면 완전히 겹쳐 대응변의 길이가 같기 때문에","correct":true},{"t":"대응변은 언제나 가장 긴 변이기 때문에","mis":"M5-2-u3-X07"},{"t":"두 도형이 같은 쪽을 보기 때문에","mis":"M5-2-u3-X04"},{"t":"대응변은 이름 차례가 같기 때문에","mis":"M5-2-u3-X06"}],"explanation":["합동인 두 도형은 포개면 완전히 겹쳐요.","겹치는 자리끼리가 짝이에요 — 이름 차례나 놓인 자리가 아니에요.","겹치므로 대응변의 길이와 대응각의 크기가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_basic#3','math',5,2,'u3','L03','g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',1,'sa','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄱ이 90°일 때 각 ㅁ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u3-C3","difficulty":1,"kind":"sa","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄱ이 90°일 때 각 ㅁ은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["점 ㄱ의 대응점은 점 ㅁ이에요.","각 ㄱ과 각 ㅁ은 대응각이에요.","대응각의 크기는 같으므로 90°예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄷ이 45°일 때 각 ㅅ은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["점 ㄷ의 대응점은 점 ㅅ이에요.","각 ㄷ과 각 ㅅ은 대응각이에요.","대응각의 크기는 같으므로 45°예요."]},{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄹ이 75°일 때 각 ㅇ은 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["점 ㄹ의 대응점은 점 ㅇ이에요.","각 ㄹ과 각 ㅇ은 대응각이에요.","대응각의 크기는 같으므로 75°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_basic#4','math',5,2,'u3','L03','g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',1,'sa','auto','서로 합동인 두 직사각형이 있어요. 한 직사각형의 짧은 변이 3 cm, 긴 변이 7 cm일 때, 다른 직사각형의 짧은 변과 긴 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C3","difficulty":1,"kind":"sa","stem":"서로 합동인 두 직사각형이 있어요. 한 직사각형의 짧은 변이 3 cm, 긴 변이 7 cm일 때, 다른 직사각형의 짧은 변과 긴 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["합동인 두 직사각형은 대응변의 길이가 같아요.","다른 직사각형도 짧은 변 3 cm, 긴 변 7 cm예요.","3 + 7 = 10(cm)예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"서로 합동인 두 직사각형이 있어요. 한 직사각형의 짧은 변이 4 cm, 긴 변이 9 cm일 때, 다른 직사각형의 짧은 변과 긴 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["합동인 두 직사각형은 대응변의 길이가 같아요.","다른 직사각형도 짧은 변 4 cm, 긴 변 9 cm예요.","4 + 9 = 13(cm)예요."]},{"stem":"서로 합동인 두 직사각형이 있어요. 한 직사각형의 짧은 변이 5 cm, 긴 변이 8 cm일 때, 다른 직사각형의 짧은 변과 긴 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["합동인 두 직사각형은 대응변의 길이가 같아요.","다른 직사각형도 짧은 변 5 cm, 긴 변 8 cm예요.","5 + 8 = 13(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_basic#5','math',5,2,'u3','L03','g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',2,'mc','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 점 ㄱ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X07']::text[],true,'{"seq":5,"concept":"M5-2-u3-C3","difficulty":2,"kind":"mc","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 점 ㄱ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅅ","correct":true},{"t":"점 ㅁ","mis":"M5-2-u3-X06"},{"t":"점 ㅂ","mis":"M5-2-u3-X07"},{"t":"점 ㅇ","mis":"M5-2-u3-X07"}],"explanation":["대응점은 두 도형을 포개었을 때 겹치는 점이에요.","그림에서 오른쪽 도형을 반 바퀴 돌려 왼쪽 도형에 포개면 점 ㄱ과 점 ㅅ이 겹쳐요.","이름 차례(ㄱ ↔ ㅁ)로 짝짓지 않아요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅅ":[300,80,"se"],"ㅇ":[240,80,"s"],"ㅁ":[180,0,"nw"],"ㅂ":[300,0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅅ","ㅇ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 점 ㄴ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㅂ","mis":"M5-2-u3-X06"},{"t":"점 ㅅ","mis":"M5-2-u3-X07"},{"t":"점 ㅇ","mis":"M5-2-u3-X07"}],"explanation":["대응점은 두 도형을 포개었을 때 겹치는 점이에요.","그림에서 오른쪽 도형을 뒤집어 왼쪽 도형에 포개면 점 ㄴ과 점 ㅁ이 겹쳐요.","이름 차례(ㄴ ↔ ㅂ)로 짝짓지 않아요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅂ":[300,0,"ne"],"ㅁ":[240,0,"n"],"ㅇ":[180,80,"sw"],"ㅅ":[300,80,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅂ","ㅁ","ㅇ","ㅅ"]]}],"tag":false}},{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 점 ㄷ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅂ","correct":true},{"t":"점 ㅅ","mis":"M5-2-u3-X06"},{"t":"점 ㅁ","mis":"M5-2-u3-X07"},{"t":"점 ㅇ","mis":"M5-2-u3-X07"}],"explanation":["대응점은 두 도형을 포개었을 때 겹치는 점이에요.","그림에서 오른쪽 도형을 반 바퀴 돌려 왼쪽 도형에 포개면 점 ㄷ과 점 ㅂ이 겹쳐요.","이름 차례(ㄷ ↔ ㅅ)로 짝짓지 않아요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[300,80,"se"],"ㅁ":[240,80,"s"],"ㅂ":[180,0,"nw"],"ㅅ":[300,0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅇ","ㅁ","ㅂ","ㅅ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_basic#6','math',5,2,'u3','L03','g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',2,'sa','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 변 ㄷㄹ이 6 cm일 때, 그 대응변인 변 ㅁㅂ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C3","difficulty":2,"kind":"sa","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 변 ㄷㄹ이 6 cm일 때, 그 대응변인 변 ㅁㅂ은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["점 ㄷ의 대응점은 점 ㅁ, 점 ㄹ의 대응점은 점 ㅂ이에요.","그래서 변 ㄷㄹ의 대응변은 변 ㅁㅂ이에요.","대응변의 길이는 같으므로 6 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅅ":[300,80,"se"],"ㅇ":[240,80,"s"],"ㅁ":[180,0,"nw"],"ㅂ":[300,0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅅ","ㅇ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 변 ㄴㄷ이 5 cm일 때, 그 대응변인 변 ㅁㅇ은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["점 ㄴ의 대응점은 점 ㅁ, 점 ㄷ의 대응점은 점 ㅇ이에요.","그래서 변 ㄴㄷ의 대응변은 변 ㅁㅇ이에요.","대응변의 길이는 같으므로 5 cm예요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅂ":[300,0,"ne"],"ㅁ":[240,0,"n"],"ㅇ":[180,80,"sw"],"ㅅ":[300,80,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅂ","ㅁ","ㅇ","ㅅ"]]}],"tag":false}},{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 변 ㄹㄱ이 4 cm일 때, 그 대응변인 변 ㅅㅇ은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["점 ㄹ의 대응점은 점 ㅅ, 점 ㄱ의 대응점은 점 ㅇ이에요.","그래서 변 ㄹㄱ의 대응변은 변 ㅅㅇ이에요.","대응변의 길이는 같으므로 4 cm예요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[300,80,"se"],"ㅁ":[240,80,"s"],"ㅂ":[180,0,"nw"],"ㅅ":[300,0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅇ","ㅁ","ㅂ","ㅅ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, gradi