80,"sw"],"ㅂ":[300,80,"se"],"ㅅ":[240,80,"s"],"ㅇ":[180,0,"nw"],"ㅁ":[300,0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅂ","ㅅ","ㅇ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_basic#8','math',5,2,'u3','L03','g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',2,'ox','auto','합동인 두 도형에서 대응각의 크기는 서로 같아요.',ARRAY['M5-2-u3-X07']::text[],true,'{"seq":8,"concept":"M5-2-u3-C3","difficulty":2,"kind":"ox","stem":"합동인 두 도형에서 대응각의 크기는 서로 같아요.","answer":"O","reason_options":[{"t":"포개면 벌어진 정도까지 그대로 겹치므로","correct":true},{"t":"대응각은 대응변보다 늘 크므로","mis":"M5-2-u3-X07"}],"mis":"M5-2-u3-X07","explanation":["대응각은 포개었을 때 겹치는 각이에요.","겹치려면 크기가 같아야 해요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"대응점은 두 도형의 이름을 차례대로 읽어 짝지으면 돼요.","answer":"X","reason_options":[{"t":"대응점은 포개었을 때 겹치는 점이므로","correct":true},{"t":"이름 차례가 같으면 언제나 겹치므로","mis":"M5-2-u3-X06"}],"explanation":["도형을 돌리거나 뒤집어 놓으면 이름 차례와 겹치는 자리가 달라요.","대응점은 포개어 겹치는 자리로 정해요.","그래서 틀린 말이에요."]},{"stem":"합동인 두 도형에서 한 도형의 변의 길이를 알면 대응변의 길이는 재지 않아도 알 수 있어요.","answer":"O","reason_options":[{"t":"대응변의 길이는 서로 같으므로","correct":true},{"t":"대응변은 길이가 두 배이므로","mis":"M5-2-u3-X07"}],"explanation":["합동인 두 도형은 포개면 완전히 겹쳐요.","겹치는 대응변의 길이는 같아요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_basic#9','math',5,2,'u3','L03','g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',2,'mc','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄷ이 125°일 때 각 ㅅ은 몇 도인가요?',ARRAY['M5-2-u3-X07']::text[],true,'{"seq":9,"concept":"M5-2-u3-C3","difficulty":2,"kind":"mc","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄷ이 125°일 때 각 ㅅ은 몇 도인가요?","options":[{"t":"125°","correct":true},{"t":"55°","mis":"M5-2-u3-X07"},{"t":"170°","mis":"M5-2-u3-X07"},{"t":"90°","mis":"M5-2-u3-X07"}],"explanation":["점 ㄷ의 대응점은 점 ㅅ이에요.","그래서 각 ㄷ의 대응각은 각 ㅅ이에요.","대응각의 크기는 같으므로 125°예요."],"variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄴ이 110°일 때 각 ㅂ은 몇 도인가요?","options":[{"t":"110°","correct":true},{"t":"70°","mis":"M5-2-u3-X07"},{"t":"155°","mis":"M5-2-u3-X07"},{"t":"75°","mis":"M5-2-u3-X07"}],"explanation":["점 ㄴ의 대응점은 점 ㅂ이에요.","그래서 각 ㄴ의 대응각은 각 ㅂ이에요.","대응각의 크기는 같으므로 110°예요."]},{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄹ이 135°일 때 각 ㅇ은 몇 도인가요?","options":[{"t":"135°","correct":true},{"t":"45°","mis":"M5-2-u3-X07"},{"t":"180°","mis":"M5-2-u3-X07"},{"t":"100°","mis":"M5-2-u3-X07"}],"explanation":["점 ㄹ의 대응점은 점 ㅇ이에요.","그래서 각 ㄹ의 대응각은 각 ㅇ이에요.","대응각의 크기는 같으므로 135°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_basic#10','math',5,2,'u3','L03','g5_2_math_u3_L03_basic','lesson_basic','M5-2-u3-C3',3,'sa','auto','삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 90°, 각 ㄴ이 45°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u3-C3","difficulty":3,"kind":"sa","stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 90°, 각 ㄴ이 45°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 90 − 45 = 45(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 45°예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 60°, 각 ㄴ이 50°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 60 − 50 = 70(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 70°예요."]},{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 70°, 각 ㄴ이 40°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 70 − 40 = 70(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 70°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_challenge#1','math',5,2,'u3','L03','g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',2,'mc','auto','삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이에요. 점 ㄱ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X07']::text[],true,'{"seq":1,"concept":"M5-2-u3-C3","difficulty":2,"kind":"mc","stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이에요. 점 ㄱ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X06"},{"t":"점 ㅂ","mis":"M5-2-u3-X07"},{"t":"변 ㄹㅂ","mis":"M5-2-u3-X07"}],"explanation":["대응점은 두 도형을 포개었을 때 겹치는 점이에요.","그림에서 오른쪽 도형을 반 바퀴 돌려 왼쪽 도형에 포개면 점 ㄱ과 점 ㅁ이 겹쳐요.","이름 차례(ㄱ ↔ ㄹ)로 짝짓지 않아요."],"asset":{"type":"geo","items":[{"w":220,"h":60,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[80,0,"e"],"ㄷ":[0,60,"sw"],"ㅁ":[220,60,"se"],"ㅂ":[140,60,"w"],"ㄹ":[220,0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이에요. 점 ㄴ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X06"},{"t":"점 ㅂ","mis":"M5-2-u3-X07"},{"t":"변 ㄹㅂ","mis":"M5-2-u3-X07"}],"explanation":["대응점은 두 도형을 포개었을 때 겹치는 점이에요.","그림에서 오른쪽 도형을 뒤집어 왼쪽 도형에 포개면 점 ㄴ과 점 ㅁ이 겹쳐요.","이름 차례가 아니라 겹치는 자리로 짝지어요."],"asset":{"type":"geo","items":[{"w":220,"h":60,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[80,0,"e"],"ㄷ":[0,60,"sw"],"ㅂ":[220,0,"ne"],"ㅁ":[140,0,"w"],"ㄹ":[220,60,"se"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅂ","ㅁ","ㄹ"]]}],"tag":false}},{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이에요. 점 ㄷ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅂ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X06"},{"t":"점 ㅁ","mis":"M5-2-u3-X07"},{"t":"변 ㄹㅁ","mis":"M5-2-u3-X07"}],"explanation":["대응점은 두 도형을 포개었을 때 겹치는 점이에요.","그림에서 오른쪽 도형을 위아래로 뒤집어 왼쪽 도형에 포개면 점 ㄷ과 점 ㅂ이 겹쳐요.","이름 차례가 아니라 겹치는 자리로 짝지어요."],"asset":{"type":"geo","items":[{"w":220,"h":60,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[80,0,"e"],"ㄷ":[0,60,"sw"],"ㅁ":[140,60,"sw"],"ㄹ":[220,60,"e"],"ㅂ":[140,0,"nw"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㄹ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_challenge#2','math',5,2,'u3','L03','g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',2,'sa','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 사각형 ㄱㄴㄷㄹ의 변은 변 ㄱㄴ 3 cm, 변 ㄴㄷ 5 cm, 변 ㄷㄹ 6 cm, 변 ㄹㄱ 4 cm예요. 사각형 ㅁㅂㅅㅇ의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C3","difficulty":2,"kind":"sa","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 사각형 ㄱㄴㄷㄹ의 변은 변 ㄱㄴ 3 cm, 변 ㄴㄷ 5 cm, 변 ㄷㄹ 6 cm, 변 ㄹㄱ 4 cm예요. 사각형 ㅁㅂㅅㅇ의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["합동인 두 도형은 대응변의 길이가 모두 같아요.","그래서 두 도형의 둘레도 같아요.","3 + 5 + 6 + 4 = 18(cm)예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅅ":[300,80,"se"],"ㅇ":[240,80,"s"],"ㅁ":[180,0,"nw"],"ㅂ":[300,0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅅ","ㅇ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이에요. 삼각형 ㄱㄴㄷ의 변은 변 ㄱㄴ 4 cm, 변 ㄴㄷ 5 cm, 변 ㄷㄱ 3 cm예요. 삼각형 ㄹㅁㅂ의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["합동인 두 도형은 대응변의 길이가 모두 같아요.","그래서 두 도형의 둘레도 같아요.","4 + 5 + 3 = 12(cm)예요."],"asset":{"type":"geo","items":[{"w":220,"h":60,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[80,0,"e"],"ㄷ":[0,60,"sw"],"ㅁ":[220,0,"ne"],"ㄹ":[140,0,"w"],"ㅂ":[220,60,"se"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㄹ","ㅂ"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 사각형 ㄱㄴㄷㄹ의 변은 변 ㄱㄴ 3 cm, 변 ㄴㄷ 5 cm, 변 ㄷㄹ 6 cm, 변 ㄹㄱ 4 cm예요. 사각형 ㅁㅂㅅㅇ의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["합동인 두 도형은 대응변의 길이가 모두 같아요.","그래서 두 도형의 둘레도 같아요.","3 + 5 + 6 + 4 = 18(cm)예요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[180,80,"sw"],"ㅅ":[240,80,"s"],"ㅂ":[300,0,"ne"],"ㅁ":[180,0,"nw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅇ","ㅅ","ㅂ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON C