INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_challenge#4','math',5,2,'u3','L03','g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',3,'error','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 대응점을 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X17']::text[],true,'{"seq":4,"concept":"M5-2-u3-C3","difficulty":3,"kind":"error","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 대응점을 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「점 ㄱ의 대응점은 점 ㅁ이에요.」","correct":true,"mis_target":"M5-2-u3-X06"},{"t":"도윤 — 「점 ㄱ의 대응점은 점 ㅅ이에요.」","mis":"M5-2-u3-X17"},{"t":"하린 — 「점 ㄴ의 대응점은 점 ㅇ이에요.」","mis":"M5-2-u3-X17"}],"explanation":["대응점은 포개었을 때 겹치는 점이에요.","점 ㄱ과 겹치는 점은 점 ㅅ이에요.","수아는 이름 차례로 짝지어 틀렸어요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅅ":[300,80,"se"],"ㅇ":[240,80,"s"],"ㅁ":[180,0,"nw"],"ㅂ":[300,0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅅ","ㅇ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 대응점을 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「점 ㄴ의 대응점은 점 ㅂ이에요.」","correct":true,"mis_target":"M5-2-u3-X06"},{"t":"서연 — 「점 ㄴ의 대응점은 점 ㅁ이에요.」","mis":"M5-2-u3-X17"},{"t":"지호 — 「점 ㄱ의 대응점은 점 ㅂ이에요.」","mis":"M5-2-u3-X17"}],"explanation":["대응점은 포개었을 때 겹치는 점이에요.","점 ㄴ과 겹치는 점은 점 ㅁ이에요.","민준은 이름 차례로 짝지어 틀렸어요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅂ":[300,0,"ne"],"ㅁ":[240,0,"n"],"ㅇ":[180,80,"sw"],"ㅅ":[300,80,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅂ","ㅁ","ㅇ","ㅅ"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 대응점을 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「점 ㄷ의 대응점은 점 ㅅ이에요.」","correct":true,"mis_target":"M5-2-u3-X06"},{"t":"나린 — 「점 ㄷ의 대응점은 점 ㅂ이에요.」","mis":"M5-2-u3-X17"},{"t":"유진 — 「점 ㄱ의 대응점은 점 ㅇ이에요.」","mis":"M5-2-u3-X17"}],"explanation":["대응점은 포개었을 때 겹치는 점이에요.","점 ㄷ과 겹치는 점은 점 ㅂ이에요.","가온은 이름 차례로 짝지어 틀렸어요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[300,80,"se"],"ㅁ":[240,80,"s"],"ㅂ":[180,0,"nw"],"ㅅ":[300,0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅇ","ㅁ","ㅂ","ㅅ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_challenge#5','math',5,2,'u3','L03','g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',3,'mc','auto','합동인 두 도형에 대한 설명으로 틀린 것은 어느 것인가요?',ARRAY['M5-2-u3-X17']::text[],true,'{"seq":5,"concept":"M5-2-u3-C3","difficulty":3,"kind":"mc","stem":"합동인 두 도형에 대한 설명으로 틀린 것은 어느 것인가요?","options":[{"t":"두 도형이 놓인 방향은 언제나 같다","correct":true},{"t":"대응변의 길이가 같다","mis":"M5-2-u3-X17"},{"t":"대응각의 크기가 같다","mis":"M5-2-u3-X17"},{"t":"둘레의 길이가 같다","mis":"M5-2-u3-X17"}],"explanation":["합동인 두 도형은 대응변의 길이와 대응각의 크기가 같아요.","그래서 둘레와 넓이도 같아요.","놓인 방향이나 이름 차례는 다를 수 있어요 — 「두 도형이 놓인 방향은 언제나 같다」가 틀렸어요."],"variant_rule":{"alt":[{"stem":"합동인 두 삼각형에 대한 설명으로 틀린 것은 어느 것인가요?","options":[{"t":"대응점은 언제나 이름 차례가 같다","correct":true},{"t":"대응각의 크기가 같다","mis":"M5-2-u3-X17"},{"t":"넓이가 같다","mis":"M5-2-u3-X17"},{"t":"대응변의 길이가 같다","mis":"M5-2-u3-X17"}],"explanation":["합동인 두 도형은 대응변의 길이와 대응각의 크기가 같아요.","그래서 둘레와 넓이도 같아요.","놓인 방향이나 이름 차례는 다를 수 있어요 — 「대응점은 언제나 이름 차례가 같다」가 틀렸어요."]},{"stem":"합동인 두 사각형에 대한 설명으로 틀린 것은 어느 것인가요?","options":[{"t":"한 사각형의 각이 다른 사각형의 대응각보다 클 수 있다","correct":true},{"t":"네 대응변의 길이가 각각 같다","mis":"M5-2-u3-X17"},{"t":"둘레의 길이가 같다","mis":"M5-2-u3-X17"},{"t":"포개면 완전히 겹친다","mis":"M5-2-u3-X17"}],"explanation":["합동인 두 도형은 대응변의 길이와 대응각의 크기가 같아요.","그래서 둘레와 넓이도 같아요.","놓인 방향이나 이름 차례는 다를 수 있어요 — 「한 사각형의 각이 다른 사각형의 대응각보다 클 수 있다」가 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_challenge#6','math',5,2,'u3','L03','g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',3,'sa','auto','삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이에요. 변 ㄱㄴ이 4 cm일 때, 그 대응변인 변 ㅁㅂ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C3","difficulty":3,"kind":"sa","stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이에요. 변 ㄱㄴ이 4 cm일 때, 그 대응변인 변 ㅁㅂ은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["점 ㄱ의 대응점은 점 ㅁ, 점 ㄴ의 대응점은 점 ㅂ이에요.","그래서 변 ㄱㄴ의 대응변은 변 ㅁㅂ이에요.","대응변의 길이는 같으므로 4 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":220,"h":60,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[80,0,"e"],"ㄷ":[0,60,"sw"],"ㅁ":[220,60,"se"],"ㅂ":[140,60,"w"],"ㄹ":[220,0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㅂ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이에요. 변 ㄴㄷ이 5 cm일 때, 그 대응변인 변 ㅁㄹ은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["점 ㄴ의 대응점은 점 ㅁ, 점 ㄷ의 대응점은 점 ㄹ이에요.","그래서 변 ㄴㄷ의 대응변은 변 ㅁㄹ이에요.","대응변의 길이는 같으므로 5 cm예요."],"asset":{"type":"geo","items":[{"w":220,"h":60,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[80,0,"e"],"ㄷ":[0,60,"sw"],"ㅂ":[220,0,"ne"],"ㅁ":[140,0,"w"],"ㄹ":[220,60,"se"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅂ","ㅁ","ㄹ"]]}],"tag":false}},{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이에요. 변 ㄷㄱ이 3 cm일 때, 그 대응변인 변 ㅂㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㄷ의 대응점은 점 ㅂ, 점 ㄱ의 대응점은 점 ㅁ이에요.","그래서 변 ㄷㄱ의 대응변은 변 ㅂㅁ이에요.","대응변의 길이는 같으므로 3 cm예요."],"asset":{"type":"geo","items":[{"w":220,"h":60,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[80,0,"e"],"ㄷ":[0,60,"sw"],"ㅁ":[140,60,"sw"],"ㄹ":[220,60,"e"],"ㅂ":[140,0,"nw"]},"poly":[["ㄱ","ㄴ","ㄷ"],["ㅁ","ㄹ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_challenge#7','math',5,2,'u3','L03','g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',3,'ox','auto','합동인 두 도형은 넓이는 같지만 둘레는 다를 수 있어요.',ARRAY['M5-2-u3-X07']::text[],true,'{"seq":7,"concept":"M5-2-u3-C3","difficulty":3,"kind":"ox","stem":"합동인 두 도형은 넓이는 같지만 둘레는 다를 수 있어요.","answer":"X","reason_options":[{"t":"대응변의 길이가 모두 같아 둘레도 같으므로","correct":true},{"t":"놓인 방향에 따라 둘레가 바뀌므로","mis":"M5-2-u3-X07"}],"mis":"M5-2-u3-X07","explanation":["합동인 두 도형은 대응변의 길이가 모두 같아요.","그래서 둘레도 같아요.","틀린 말이에요."],"variant_rule":{"alt":[{"stem":"합동인 두 삼각형에서 한 삼각형의 두 각을 알면 다른 삼각형의 세 각을 모두 알 수 있어요.","answer":"O","reason_options":[{"t":"나머지 한 각은 180°에서 빼서 구하고 대응각은 크기가 같으므로","correct":true},{"t":"두 삼각형의 각은 서로 다르므로","mis":"M5-2-u3-X07"}],"explanation":["삼각형의 세 각의 합은 180°라서 나머지 한 각을 구할 수 있어요.","대응각은 크기가 같아요.","그래서 맞는 말이에요."]},{"stem":"대응점은 두 도형의 이름을 차례대로 읽어 짝지으면 돼요.","answer":"X","reason_options":[{"t":"대응점은 포개었을 때 겹치는 점이므로","correct":true},{"t":"이름 차례가 같으면 언제나 겹치므로","mis":"M5-2-u3-X06"}],"explanation":["도형을 돌리거나 뒤집어 놓으면 이름 차례와 겹치는 자리가 달라요.","대응점은 포개어 겹치는 자리로 정해요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_challenge#8','math',5,2,'u3','L03','g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',4,'sa','auto','삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 35°, 각 ㄴ이 85°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C3","difficulty":4,"kind":"sa","stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 35°, 각 ㄴ이 85°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 35 − 85 = 60(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 60°예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 80°, 각 ㄴ이 25°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 80 − 25 = 75(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 75°예요."]},{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 95°, 각 ㄴ이 30°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 95 − 30 = 55(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 55°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_challenge#9','math',5,2,'u3','L03','g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',4,'mc','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 변 ㄹㄱ의 대응변은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X07']::text[],true,'{"seq":9,"concept":"M5-2-u3-C3","difficulty":4,"kind":"mc","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 변 ㄹㄱ의 대응변은 어느 것인가요?","options":[{"t":"변 ㅇㅅ","correct":true},{"t":"변 ㅇㅁ","mis":"M5-2-u3-X06"},{"t":"변 ㅅㅂ","mis":"M5-2-u3-X07"},{"t":"변 ㅂㅁ","mis":"M5-2-u3-X07"}],"explanation":["먼저 대응점을 찾아요 — 점 ㄹ ↔ 점 ㅇ, 점 ㄱ ↔ 점 ㅅ.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㄹㄱ의 대응변은 변 ㅇㅅ이에요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅅ":[180,80,"sw"],"ㅂ":[240,80,"s"],"ㅁ":[300,0,"ne"],"ㅇ":[180,0,"nw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅅ","ㅂ","ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 변 ㄱㄴ의 대응변은 어느 것인가요?","options":[{"t":"변 ㅅㅂ","correct":true},{"t":"변 ㅁㅂ","mis":"M5-2-u3-X06"},{"t":"변 ㅁㅇ","mis":"M5-2-u3-X07"},{"t":"변 ㅇㅅ","mis":"M5-2-u3-X07"}],"explanation":["먼저 대응점을 찾아요 — 점 ㄱ ↔ 점 ㅅ, 점 ㄴ ↔ 점 ㅂ.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㄱㄴ의 대응변은 변 ㅅㅂ이에요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅅ":[300,0,"ne"],"ㅂ":[240,0,"n"],"ㅁ":[180,80,"sw"],"ㅇ":[300,80,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅅ","ㅂ","ㅁ","ㅇ"]]}],"tag":false}},{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 변 ㄴㄷ의 대응변은 어느 것인가요?","options":[{"t":"변 ㅅㅂ","correct":true},{"t":"변 ㅇㅅ","mis":"M5-2-u3-X07"},{"t":"변 ㅂㅁ","mis":"M5-2-u3-X07"},{"t":"변 ㅁㅇ","mis":"M5-2-u3-X07"}],"explanation":["먼저 대응점을 찾아요 — 점 ㄴ ↔ 점 ㅅ, 점 ㄷ ↔ 점 ㅂ.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㄴㄷ의 대응변은 변 ㅅㅂ이에요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[180,80,"sw"],"ㅅ":[240,80,"s"],"ㅂ":[300,0,"ne"],"ㅁ":[180,0,"nw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅇ","ㅅ","ㅂ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L03_challenge#10','math',5,2,'u3','L03','g5_2_math_u3_L03_challenge','lesson_challenge','M5-2-u3-C3',4,'essay','teacher','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 포개어 보니 점 ㄱ은 점 ㅅ과, 점 ㄴ은 점 ㅇ과 겹쳤어요. 어떤 친구는 「이름 차례대로 점 ㄱ의 대응점은 점 ㅁ」이라고 했어요. 친구의 말이 맞는지 쓰고, 각 ㄱ이 110°일 때 크기가 110°인 각을 사각형 ㅁㅂㅅㅇ에서 찾아 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C3","difficulty":4,"kind":"essay","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 포개어 보니 점 ㄱ은 점 ㅅ과, 점 ㄴ은 점 ㅇ과 겹쳤어요. 어떤 친구는 「이름 차례대로 점 ㄱ의 대응점은 점 ㅁ」이라고 했어요. 친구의 말이 맞는지 쓰고, 각 ㄱ이 110°일 때 크기가 110°인 각을 사각형 ㅁㅂㅅㅇ에서 찾아 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 친구의 말은 틀렸다. 대응점은 이름 차례가 아니라 포개었을 때 겹치는 점이므로 점 ㄱ의 대응점은 점 ㅅ이다. 각 ㄱ의 대응각은 각 ㅅ이고, 합동인 두 도형에서 대응각의 크기는 같으므로 각 ㅅ이 110°이다.","scoring_points":["친구의 말이 틀렸다고 썼는가","대응점은 겹치는 점이라 점 ㅅ이라고 썼는가","대응각인 각 ㅅ이 110°라고 까닭과 함께 썼는가"]},"explanation":["대응점은 겹치는 점 — 점 ㄱ ↔ 점 ㅅ이에요.","각 ㄱ의 대응각은 각 ㅅ이에요.","대응각은 크기가 같아 110°예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_basic#1','math',5,2,'u3','L04','g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',1,'mc','auto','한 직선을 따라 접었을 때 완전히 겹치는 도형을 무엇이라고 하나요?',ARRAY['M5-2-u3-X15','M5-2-u3-X17','M5-2-u3-X02']::text[],true,'{"seq":1,"concept":"M5-2-u3-C4","difficulty":1,"kind":"mc","stem":"한 직선을 따라 접었을 때 완전히 겹치는 도형을 무엇이라고 하나요?","options":[{"t":"선대칭도형","correct":true},{"t":"점대칭도형","mis":"M5-2-u3-X15"},{"t":"합동인 도형","mis":"M5-2-u3-X17"},{"t":"직사각형","mis":"M5-2-u3-X02"}],"explanation":["한 직선을 따라 접었을 때 완전히 겹치는 도형을 선대칭도형이라고 해요.","그 직선을 대칭축이라고 해요.","접어서 겹치는지 직접 해 보아야 알 수 있어요."],"variant_rule":{"alt":[{"stem":"선대칭도형을 접었을 때 완전히 겹치게 하는 그 직선을 무엇이라고 하나요?","options":[{"t":"대칭축","correct":true},{"t":"대칭의 중심","mis":"M5-2-u3-X15"},{"t":"대응변","mis":"M5-2-u3-X17"},{"t":"대각선","mis":"M5-2-u3-X09"}],"explanation":["한 직선을 따라 접었을 때 완전히 겹치는 도형을 선대칭도형이라고 해요.","그 직선을 대칭축이라고 해요.","접어서 겹치는지 직접 해 보아야 알 수 있어요."]},{"stem":"어떤 도형이 선대칭도형인지 알아보는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 직선을 따라 접어 완전히 겹치는지 본다","correct":true},{"t":"가운데에 점을 찍어 본다","mis":"M5-2-u3-X14"},{"t":"넓이를 반으로 나누는 선이 있는지 본다","mis":"M5-2-u3-X09"},{"t":"반 바퀴 돌려 겹치는지 본다","mis":"M5-2-u3-X15"}],"explanation":["한 직선을 따라 접었을 때 완전히 겹치는 도형을 선대칭도형이라고 해요.","그 직선을 대칭축이라고 해요.","접어서 겹치는지 직접 해 보아야 알 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_basic#2','math',5,2,'u3','L04','g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',1,'sa','auto','직사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C4","difficulty":1,"kind":"sa","stem":"직사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","세로로, 가로로 접으면 겹쳐요 — 대각선으로는 겹치지 않아요.","그래서 직사각형의 대칭축은 2개예요."],"mis":"M5-2-u3-X08","asset":{"type":"geo","items":[{"w":100,"h":60,"poly":[[[0,0],[100,0],[100,60],[0,60]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","세로·가로·두 대각선으로 접으면 겹쳐요.","그래서 정사각형의 대칭축은 4개예요."],"asset":{"type":"geo","items":[{"w":80,"h":80,"poly":[[[0,0],[80,0],[80,80],[0,80]]]}],"tag":false}},{"stem":"이등변삼각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","꼭짓점에서 밑변 가운데로 내린 선으로만 접혀요.","그래서 이등변삼각형의 대칭축은 1개예요."],"asset":{"type":"geo","items":[{"w":80,"h":80,"poly":[[[0,80],[40,0],[80,80]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_basic#3','math',5,2,'u3','L04','g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',1,'mc','auto','선대칭도형은 어느 것인가요?',ARRAY['M5-2-u3-X08']::text[],true,'{"seq":3,"concept":"M5-2-u3-C4","difficulty":1,"kind":"mc","stem":"선대칭도형은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-2-u3-X08"},{"t":"㉰","mis":"M5-2-u3-X08"},{"t":"㉱","mis":"M5-2-u3-X08"}],"explanation":["㉯는 이등변삼각형이에요","이등변삼각형은 대칭축이 있어 접으면 겹쳐요.","나머지는 어떤 직선으로 접어도 겹치지 않아요."],"asset":{"type":"geo","items":[{"w":110.0,"h":60,"poly":[[[30.0,0],[110.0,0],[80,60],[0,60]]]},{"w":80,"h":80,"poly":[[[0,80],[40,0],[80,80]]]},{"w":100,"h":60,"poly":[[[0,0],[60,0],[100,60],[0,60]]]},{"w":100,"h":60,"poly":[[[0,60],[100,60],[20,0]]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 선대칭도형은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M5-2-u3-X08"},{"t":"㉯","mis":"M5-2-u3-X08"},{"t":"㉱","mis":"M5-2-u3-X08"}],"explanation":["㉰는 직사각형이에요","직사각형은 대칭축이 있어 접으면 겹쳐요.","나머지는 어떤 직선으로 접어도 겹치지 않아요."],"asset":{"type":"geo","items":[{"w":100,"h":60,"poly":[[[0,0],[60,0],[100,60],[0,60]]]},{"w":110.0,"h":60,"poly":[[[30.0,0],[110.0,0],[80,60],[0,60]]]},{"w":100,"h":60,"poly":[[[0,0],[100,0],[100,60],[0,60]]]},{"w":100,"h":60,"poly":[[[0,60],[100,60],[20,0]]]}]}},{"stem":"이번에는 다른 보기예요. 선대칭도형은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M5-2-u3-X08"},{"t":"㉯","mis":"M5-2-u3-X08"},{"t":"㉰","mis":"M5-2-u3-X08"}],"explanation":["㉱는 마름모예요","마름모는 대칭축이 있어 접으면 겹쳐요.","나머지는 어떤 직선으로 접어도 겹치지 않아요."],"asset":{"type":"geo","items":[{"w":100,"h":60,"poly":[[[0,60],[100,60],[20,0]]]},{"w":100,"h":60,"poly":[[[0,0],[60,0],[100,60],[0,60]]]},{"w":110.0,"h":60,"poly":[[[30.0,0],[110.0,0],[80,60],[0,60]]]},{"w":100,"h":80,"poly":[[[50.0,0],[100,40],[50.0,80],[0,40]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_basic#4','math',5,2,'u3','L04','g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',1,'mc','auto','선대칭도형이 아닌 것은 어느 것인가요?',ARRAY['M5-2-u3-X17']::text[],true,'{"seq":4,"concept":"M5-2-u3-C4","difficulty":1,"kind":"mc","stem":"선대칭도형이 아닌 것은 어느 것인가요?","options":[{"t":"직각사다리꼴","correct":true},{"t":"이등변삼각형","mis":"M5-2-u3-X17"},{"t":"직사각형","mis":"M5-2-u3-X17"},{"t":"정사각형","mis":"M5-2-u3-X17"}],"explanation":["직각사다리꼴은 어떤 직선으로 접어도 완전히 겹치지 않아요.","이등변삼각형, 직사각형, 정사각형은 모두 접어서 겹치는 직선이 있어요.","그래서 선대칭도형이 아닌 것은 직각사다리꼴이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 선대칭도형이 아닌 것은 어느 것인가요?","options":[{"t":"평행사변형","correct":true},{"t":"마름모","mis":"M5-2-u3-X17"},{"t":"정삼각형","mis":"M5-2-u3-X17"},{"t":"직사각형","mis":"M5-2-u3-X17"}],"explanation":["평행사변형은 어떤 직선으로 접어도 완전히 겹치지 않아요.","마름모, 정삼각형, 직사각형은 모두 접어서 겹치는 직선이 있어요.","그래서 선대칭도형이 아닌 것은 평행사변형이에요."]},{"stem":"이번에는 다른 보기예요. 선대칭도형이 아닌 것은 어느 것인가요?","options":[{"t":"세 변의 길이가 모두 다른 삼각형","correct":true},{"t":"정사각형","mis":"M5-2-u3-X17"},{"t":"이등변삼각형","mis":"M5-2-u3-X17"},{"t":"마름모","mis":"M5-2-u3-X17"}],"explanation":["세 변의 길이가 모두 다른 삼각형은 어떤 직선으로 접어도 완전히 겹치지 않아요.","정사각형, 이등변삼각형, 마름모는 모두 접어서 겹치는 직선이 있어요.","그래서 선대칭도형이 아닌 것은 세 변의 길이가 모두 다른 삼각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_basic#5','math',5,2,'u3','L04','g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',2,'sa','auto','마름모의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u3-C4","difficulty":2,"kind":"sa","stem":"마름모의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","두 대각선으로 접으면 겹쳐요 — 세로·가로가 아니라 대각선이에요.","그래서 마름모의 대칭축은 2개예요."],"mis":"M5-2-u3-X08","asset":{"type":"geo","items":[{"w":100,"h":80,"poly":[[[50.0,0],[100,40],[50.0,80],[0,40]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정삼각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","각 꼭짓점에서 마주 보는 변의 가운데로 내린 선 3개로 접혀요.","그래서 정삼각형의 대칭축은 3개예요."],"asset":{"type":"geo","items":[{"w":80,"h":69.2,"poly":[[[0,69.2],[40,0],[80,69.2]]]}],"tag":false}},{"stem":"십자 모양의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","세로·가로·두 대각선으로 접으면 겹쳐요.","그래서 십자 모양의 대칭축은 4개예요."],"asset":{"type":"geo","items":[{"w":60,"h":60,"poly":[[[20,0],[40,0],[40,20],[60,20],[60,40],[40,40],[40,60],[20,60],[20,40],[0,40],[0,20],[20,20]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_basic#6','math',5,2,'u3','L04','g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',2,'mc','auto','직사각형의 대각선에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X09','M5-2-u3-X17']::text[],true,'{"seq":6,"concept":"M5-2-u3-C4","difficulty":2,"kind":"mc","stem":"직사각형의 대각선에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓이를 반으로 나누지만 대칭축은 아니다","correct":true},{"t":"대칭축이다","mis":"M5-2-u3-X09"},{"t":"도형 밖에 있다","mis":"M5-2-u3-X17"},{"t":"길이가 한 변과 같다","mis":"M5-2-u3-X17"}],"explanation":["직사각형을 대각선으로 자르면 넓이가 같은 두 삼각형이 돼요.","그런데 대각선으로 접으면 꼭짓점이 어긋나 겹치지 않아요.","넓이를 반으로 나누는 것과 접어서 겹치는 것은 다른 일이에요."],"variant_rule":{"alt":[{"stem":"평행사변형의 대각선에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓이를 반으로 나누지만 대칭축은 아니다","correct":true},{"t":"대칭축이다","mis":"M5-2-u3-X09"},{"t":"도형 밖에 있다","mis":"M5-2-u3-X17"},{"t":"길이가 한 변과 같다","mis":"M5-2-u3-X17"}],"explanation":["평행사변형을 대각선으로 자르면 넓이가 같은 두 삼각형이 돼요.","그런데 대각선으로 접으면 꼭짓점이 어긋나 겹치지 않아요.","넓이를 반으로 나누는 것과 접어서 겹치는 것은 다른 일이에요."]},{"stem":"직사각형 모양 색종이의 대각선에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓이를 반으로 나누지만 대칭축은 아니다","correct":true},{"t":"대칭축이다","mis":"M5-2-u3-X09"},{"t":"도형 밖에 있다","mis":"M5-2-u3-X17"},{"t":"길이가 한 변과 같다","mis":"M5-2-u3-X17"}],"explanation":["직사각형 모양 색종이를 대각선으로 자르면 넓이가 같은 두 삼각형이 돼요.","그런데 대각선으로 접으면 꼭짓점이 어긋나 겹치지 않아요.","넓이를 반으로 나누는 것과 접어서 겹치는 것은 다른 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_basic#7','math',5,2,'u3','L04','g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',2,'ox','auto','직사각형의 대각선은 직사각형의 대칭축이에요.',ARRAY['M5-2-u3-X09']::text[],true,'{"seq":7,"concept":"M5-2-u3-C4","difficulty":2,"kind":"ox","stem":"직사각형의 대각선은 직사각형의 대칭축이에요.","answer":"X","reason_options":[{"t":"대각선으로 접으면 꼭짓점이 어긋나 겹치지 않으므로","correct":true},{"t":"대각선은 넓이를 반으로 나누므로","mis":"M5-2-u3-X09"}],"mis":"M5-2-u3-X09","explanation":["직사각형을 대각선으로 접어 보면 겹치지 않아요.","넓이를 반으로 나누는 것과 접어서 겹치는 것은 달라요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"한 도형에 대칭축이 여러 개 있을 수 있어요.","answer":"O","reason_options":[{"t":"정사각형은 대칭축이 4개인 것처럼 접어서 겹치는 직선이 여럿일 수 있으므로","correct":true},{"t":"대칭축은 언제나 하나뿐이므로","mis":"M5-2-u3-X08"}],"explanation":["직사각형은 2개, 정사각형은 4개의 대칭축이 있어요.","대칭축의 개수는 도형마다 달라요.","그래서 맞는 말이에요."]},{"stem":"마름모의 대칭축은 세로로 그은 선과 가로로 그은 선이에요.","answer":"O","reason_options":[{"t":"마름모는 두 대각선이 세로와 가로로 놓여 그 선으로 접으면 겹치므로","correct":true},{"t":"마름모는 대칭축이 4개이므로","mis":"M5-2-u3-X08"}],"explanation":["꼭짓점이 위아래·양옆에 놓인 마름모는 두 대각선이 세로선·가로선이에요.","두 대각선으로 접으면 겹쳐요.","그래서 맞는 말이에요 — 대칭축은 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_basic#8','math',5,2,'u3','L04','g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',2,'sa','auto','정사각형과 직사각형의 대칭축의 개수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C4","difficulty":2,"kind":"sa","stem":"정사각형과 직사각형의 대칭축의 개수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정사각형의 대칭축은 4개예요.","직사각형의 대칭축은 2개예요.","4 + 2 = 6(개)예요."],"mis":"M5-2-u3-X08","variant_rule":{"alt":[{"stem":"정삼각형과 이등변삼각형의 대칭축의 개수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형의 대칭축은 3개예요.","이등변삼각형의 대칭축은 1개예요.","3 + 1 = 4(개)예요."]},{"stem":"마름모와 정사각형의 대칭축의 개수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["마름모의 대칭축은 2개예요.","정사각형의 대칭축은 4개예요.","2 + 4 = 6(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_basic#9','math',5,2,'u3','L04','g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',2,'mc','auto','직사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?',ARRAY['M5-2-u3-X08','M5-2-u3-X09']::text[],true,'{"seq":9,"concept":"M5-2-u3-C4","difficulty":2,"kind":"mc","stem":"직사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?","options":[{"t":"직선 ㅁㅂ","correct":true},{"t":"직선 ㄱㄴ","mis":"M5-2-u3-X08"},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X08"},{"t":"모두 대칭축이에요","mis":"M5-2-u3-X09"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㅁㅂ은 대각선 — 넓이는 반으로 나누지만 접으면 겹치지 않아요.","그래서 답은 직선 ㅁㅂ이에요."],"asset":{"type":"geo","items":[{"w":180.0,"h":120,"pts":{"ㄱ":[90.0,0,"n"],"ㄴ":[90.0,120,"s"],"ㄷ":[10.0,60,"w"],"ㄹ":[170.0,60,"e"],"ㅁ":[0.0,0,"n"],"ㅂ":[180.0,120,"s"]},"poly":[[[30.0,20],[150.0,20],[150.0,100],[30.0,100]]],"seg":[[[90.0,0],[90.0,120]],[[10.0,60],[170.0,60]],[[0.0,0],[180.0,120]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?","options":[{"t":"직선 ㅁㅂ","correct":true},{"t":"직선 ㄱㄴ","mis":"M5-2-u3-X08"},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X08"},{"t":"모두 대칭축이에요","mis":"M5-2-u3-X09"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㅁㅂ은 한가운데를 지나지 않아 접으면 겹치지 않아요.","그래서 답은 직선 ㅁㅂ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄱ":[0,0,"n"],"ㄴ":[120,120,"s"],"ㄷ":[60,0,"n"],"ㄹ":[60,120,"s"],"ㅁ":[40,0,"n"],"ㅂ":[40,120,"s"]},"poly":[[[20,20],[100,20],[100,100],[20,100]]],"seg":[[[0,0],[120,120]],[[60,0],[60,120]],[[40,0],[40,120]]]}],"tag":false}},{"stem":"이등변삼각형에 직선 세 개를 그었어요. 대칭축인 직선은 어느 것인가요?","options":[{"t":"직선 ㄱㄴ","correct":true},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X09"},{"t":"직선 ㅁㅂ","mis":"M5-2-u3-X09"},{"t":"대칭축인 직선이 없어요","mis":"M5-2-u3-X08"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㄱㄴ만 꼭짓점에서 밑변 가운데로 내린 선이에요.","그래서 답은 직선 ㄱㄴ이에요."],"asset":{"type":"geo","items":[{"w":160,"h":140,"pts":{"ㄱ":[80,0,"n"],"ㄴ":[80,140,"s"],"ㄷ":[0,70.0,"w"],"ㄹ":[160,70.0,"e"],"ㅁ":[0,0,"n"],"ㅂ":[152.0,140,"s"]},"poly":[[[80,20],[140,120],[20,120]]],"seg":[[[80,0],[80,140]],[[0,70.0],[160,70.0]],[[0,0],[152.0,140]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_basic#10','math',5,2,'u3','L04','g5_2_math_u3_L04_basic','lesson_basic','M5-2-u3-C4',3,'sa','auto','정사각형, 평행사변형, 이등변삼각형, 직각사다리꼴 가운데 선대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u3-C4","difficulty":3,"kind":"sa","stem":"정사각형, 평행사변형, 이등변삼각형, 직각사다리꼴 가운데 선대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대칭축이 하나라도 있으면 선대칭도형이에요.","정사각형 4개, 평행사변형 0개, 이등변삼각형 1개, 직각사다리꼴 0개예요(대칭축 수).","대칭축이 있는 도형은 2개예요."],"mis":"M5-2-u3-X08","variant_rule":{"alt":[{"stem":"직사각형, 마름모, 평행사변형, 정삼각형 가운데 선대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["대칭축이 하나라도 있으면 선대칭도형이에요.","직사각형 2개, 마름모 2개, 평행사변형 0개, 정삼각형 3개예요(대칭축 수).","대칭축이 있는 도형은 3개예요."]},{"stem":"직각사다리꼴, 정사각형, 세 변의 길이가 모두 다른 삼각형, 평행사변형 가운데 선대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["대칭축이 하나라도 있으면 선대칭도형이에요.","직각사다리꼴 0개, 정사각형 4개, 세 변의 길이가 모두 다른 삼각형 0개, 평행사변형 0개예요(대칭축 수).","대칭축이 있는 도형은 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_challenge#1','math',5,2,'u3','L04','g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',2,'sa','auto','정육각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C4","difficulty":2,"kind":"sa","stem":"정육각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","마주 보는 꼭짓점을 잇는 선 3개와 마주 보는 변의 가운데를 잇는 선 3개로 접혀요.","그래서 정육각형의 대칭축은 6개예요."],"mis":"M5-2-u3-X08","asset":{"type":"geo","items":[{"w":80,"h":69.2,"poly":[[[20,0],[60,0],[80,34.6],[60,69.2],[20,69.2],[0,34.6]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정오각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","각 꼭짓점에서 마주 보는 변의 가운데로 내린 선 5개로 접혀요.","그래서 정오각형의 대칭축은 5개예요."]},{"stem":"ㄱ자 모양의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","모서리를 지나는 비스듬한 선 하나로만 접혀요.","그래서 ㄱ자 모양의 대칭축은 1개예요."],"asset":{"type":"geo","items":[{"w":40,"h":40,"poly":[[[0,0],[40,0],[40,40],[20,40],[20,20],[0,20]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
