INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_challenge#3','math',5,2,'u3','L04','g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',3,'mc','auto','정사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?',ARRAY['M5-2-u3-X08','M5-2-u3-X09']::text[],true,'{"seq":3,"concept":"M5-2-u3-C4","difficulty":3,"kind":"mc","stem":"정사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?","options":[{"t":"직선 ㅁㅂ","correct":true},{"t":"직선 ㄱㄴ","mis":"M5-2-u3-X08"},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X08"},{"t":"모두 대칭축이에요","mis":"M5-2-u3-X09"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㅁㅂ은 한가운데를 지나지 않아 접으면 겹치지 않아요.","그래서 답은 직선 ㅁㅂ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄱ":[0,0,"n"],"ㄴ":[120,120,"s"],"ㄷ":[60,0,"n"],"ㄹ":[60,120,"s"],"ㅁ":[40,0,"n"],"ㅂ":[40,120,"s"]},"poly":[[[20,20],[100,20],[100,100],[20,100]]],"seg":[[[0,0],[120,120]],[[60,0],[60,120]],[[40,0],[40,120]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형에 직선 세 개를 그었어요. 대칭축인 직선은 어느 것인가요?","options":[{"t":"직선 ㄱㄴ","correct":true},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X09"},{"t":"직선 ㅁㅂ","mis":"M5-2-u3-X09"},{"t":"대칭축인 직선이 없어요","mis":"M5-2-u3-X08"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㄱㄴ만 꼭짓점에서 밑변 가운데로 내린 선이에요.","그래서 답은 직선 ㄱㄴ이에요."],"asset":{"type":"geo","items":[{"w":160,"h":140,"pts":{"ㄱ":[80,0,"n"],"ㄴ":[80,140,"s"],"ㄷ":[0,70.0,"w"],"ㄹ":[160,70.0,"e"],"ㅁ":[0,0,"n"],"ㅂ":[152.0,140,"s"]},"poly":[[[80,20],[140,120],[20,120]]],"seg":[[[80,0],[80,140]],[[0,70.0],[160,70.0]],[[0,0],[152.0,140]]]}],"tag":false}},{"stem":"직사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?","options":[{"t":"직선 ㅁㅂ","correct":true},{"t":"직선 ㄱㄴ","mis":"M5-2-u3-X08"},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X08"},{"t":"모두 대칭축이에요","mis":"M5-2-u3-X09"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㅁㅂ은 대각선 — 넓이는 반으로 나누지만 접으면 겹치지 않아요.","그래서 답은 직선 ㅁㅂ이에요."],"asset":{"type":"geo","items":[{"w":180.0,"h":120,"pts":{"ㄱ":[90.0,0,"n"],"ㄴ":[90.0,120,"s"],"ㄷ":[10.0,60,"w"],"ㄹ":[170.0,60,"e"],"ㅁ":[0.0,0,"n"],"ㅂ":[180.0,120,"s"]},"poly":[[[30.0,20],[150.0,20],[150.0,100],[30.0,100]]],"seg":[[[90.0,0],[90.0,120]],[[10.0,60],[170.0,60]],[[0.0,0],[180.0,120]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_challenge#4','math',5,2,'u3','L04','g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',3,'mc','auto','알파벳 대문자(굵은 고딕체)를 도형으로 볼 때 선대칭도형인 것은 어느 것인가요?',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":4,"concept":"M5-2-u3-C4","difficulty":3,"kind":"mc","stem":"알파벳 대문자(굵은 고딕체)를 도형으로 볼 때 선대칭도형인 것은 어느 것인가요?","options":[{"t":"A","correct":true},{"t":"N","mis":"M5-2-u3-X15"},{"t":"S","mis":"M5-2-u3-X15"},{"t":"Z","mis":"M5-2-u3-X15"}],"explanation":["A는 한 직선을 따라 접으면 완전히 겹쳐요.","N, S, Z는 접어서는 겹치지 않고 반 바퀴 돌려야 겹쳐요.","돌려서 겹치는 것은 점대칭이라 선대칭과 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알파벳 대문자(굵은 고딕체)를 도형으로 볼 때 선대칭도형인 것은 어느 것인가요?","options":[{"t":"T","correct":true},{"t":"S","mis":"M5-2-u3-X15"},{"t":"Z","mis":"M5-2-u3-X15"},{"t":"N","mis":"M5-2-u3-X15"}],"explanation":["T는 한 직선을 따라 접으면 완전히 겹쳐요.","S, Z, N은 접어서는 겹치지 않고 반 바퀴 돌려야 겹쳐요.","돌려서 겹치는 것은 점대칭이라 선대칭과 달라요."]},{"stem":"이번에는 다른 보기예요. 알파벳 대문자(굵은 고딕체)를 도형으로 볼 때 선대칭도형인 것은 어느 것인가요?","options":[{"t":"M","correct":true},{"t":"Z","mis":"M5-2-u3-X15"},{"t":"N","mis":"M5-2-u3-X15"},{"t":"S","mis":"M5-2-u3-X15"}],"explanation":["M은 한 직선을 따라 접으면 완전히 겹쳐요.","Z, N, S는 접어서는 겹치지 않고 반 바퀴 돌려야 겹쳐요.","돌려서 겹치는 것은 점대칭이라 선대칭과 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_challenge#5','math',5,2,'u3','L04','g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',3,'error','auto','친구들이 대칭축에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u3-X09','M5-2-u3-X08']::text[],true,'{"seq":5,"concept":"M5-2-u3-C4","difficulty":3,"kind":"error","stem":"친구들이 대칭축에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「직사각형의 대칭축은 대각선까지 4개야.」","correct":true,"mis_target":"M5-2-u3-X09"},{"t":"도윤 — 「정사각형의 대칭축은 4개야.」","mis":"M5-2-u3-X08"},{"t":"하린 — 「직각사다리꼴은 선대칭도형이 아니야.」","mis":"M5-2-u3-X08"}],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선만이에요.","직사각형 2개·정사각형 4개·마름모 2개·이등변삼각형 1개·정삼각형 3개이고, 평행사변형·직각사다리꼴은 없어요.","수아의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 대칭축에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「평행사변형은 반으로 나눌 수 있으니 선대칭도형이야.」","correct":true,"mis_target":"M5-2-u3-X09"},{"t":"서연 — 「이등변삼각형의 대칭축은 1개야.」","mis":"M5-2-u3-X08"},{"t":"지호 — 「마름모의 대칭축은 2개야.」","mis":"M5-2-u3-X08"}],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선만이에요.","직사각형 2개·정사각형 4개·마름모 2개·이등변삼각형 1개·정삼각형 3개이고, 평행사변형·직각사다리꼴은 없어요.","민준의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 대칭축에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「정사각형의 대칭축은 세로·가로 2개뿐이야.」","correct":true,"mis_target":"M5-2-u3-X08"},{"t":"나린 — 「정삼각형의 대칭축은 3개야.」","mis":"M5-2-u3-X08"},{"t":"유진 — 「직사각형의 대각선은 대칭축이 아니야.」","mis":"M5-2-u3-X09"}],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선만이에요.","직사각형 2개·정사각형 4개·마름모 2개·이등변삼각형 1개·정삼각형 3개이고, 평행사변형·직각사다리꼴은 없어요.","가온의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_challenge#6','math',5,2,'u3','L04','g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',3,'ox','auto','평행사변형은 선대칭도형이에요.',ARRAY['M5-2-u3-X09']::text[],true,'{"seq":6,"concept":"M5-2-u3-C4","difficulty":3,"kind":"ox","stem":"평행사변형은 선대칭도형이에요.","answer":"X","reason_options":[{"t":"평행사변형은 어떤 직선으로 접어도 완전히 겹치지 않으므로","correct":true},{"t":"가운데를 지나는 선으로 반을 나눌 수 있으므로","mis":"M5-2-u3-X09"}],"mis":"M5-2-u3-X09","explanation":["평행사변형은 세로·가로·대각선 어느 쪽으로 접어도 겹치지 않아요.","반으로 나눌 수 있다고 대칭축이 되는 것은 아니에요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"정삼각형의 대칭축은 3개예요.","answer":"O","reason_options":[{"t":"각 꼭짓점에서 마주 보는 변의 가운데로 내린 선 3개로 접혀 겹치므로","correct":true},{"t":"삼각형은 대칭축이 하나뿐이므로","mis":"M5-2-u3-X08"}],"explanation":["정삼각형은 세 변의 길이가 같아요.","어느 꼭짓점에서 내린 선으로 접어도 겹쳐요.","그래서 맞는 말이에요."]},{"stem":"이등변삼각형을 가로로 반 접으면 완전히 겹쳐요.","answer":"X","reason_options":[{"t":"이등변삼각형은 꼭짓점에서 밑변 가운데로 내린 세로선으로만 접히므로","correct":true},{"t":"어떤 삼각형이든 가로로 접으면 겹치므로","mis":"M5-2-u3-X08"}],"explanation":["이등변삼각형을 가로로 접으면 위쪽 뾰족한 부분이 남아요.","접어서 겹치는 선은 세로선 하나예요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_challenge#7','math',5,2,'u3','L04','g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',3,'sa','auto','정육각형, 평행사변형, ㄱ자 모양, 십자 모양, 직각사다리꼴 가운데 선대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u3-C4","difficulty":3,"kind":"sa","stem":"정육각형, 평행사변형, ㄱ자 모양, 십자 모양, 직각사다리꼴 가운데 선대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["대칭축이 하나라도 있으면 선대칭도형이에요.","정육각형 6개, 평행사변형 0개, ㄱ자 모양 1개, 십자 모양 4개, 직각사다리꼴 0개예요(대칭축 수).","대칭축이 있는 도형은 3개예요."],"mis":"M5-2-u3-X08","variant_rule":{"alt":[{"stem":"정오각형, 정삼각형, 평행사변형, 마름모, 직사각형 가운데 선대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["대칭축이 하나라도 있으면 선대칭도형이에요.","정오각형 5개, 정삼각형 3개, 평행사변형 0개, 마름모 2개, 직사각형 2개예요(대칭축 수).","대칭축이 있는 도형은 4개예요."]},{"stem":"세 변의 길이가 모두 다른 삼각형, ㄱ자 모양, 직각사다리꼴, 정육각형, 평행사변형 가운데 선대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대칭축이 하나라도 있으면 선대칭도형이에요.","세 변의 길이가 모두 다른 삼각형 0개, ㄱ자 모양 1개, 직각사다리꼴 0개, 정육각형 6개, 평행사변형 0개예요(대칭축 수).","대칭축이 있는 도형은 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_challenge#8','math',5,2,'u3','L04','g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',4,'sa','auto','정육각형과 십자 모양의 대칭축의 개수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C4","difficulty":4,"kind":"sa","stem":"정육각형과 십자 모양의 대칭축의 개수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["정육각형의 대칭축은 6개예요.","십자 모양의 대칭축은 4개예요.","6 + 4 = 10(개)예요."],"mis":"M5-2-u3-X08","variant_rule":{"alt":[{"stem":"정오각형과 마름모의 대칭축의 개수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정오각형의 대칭축은 5개예요.","마름모의 대칭축은 2개예요.","5 + 2 = 7(개)예요."]},{"stem":"정삼각형과 정육각형의 대칭축의 개수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정삼각형의 대칭축은 3개예요.","정육각형의 대칭축은 6개예요.","3 + 6 = 9(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_challenge#9','math',5,2,'u3','L04','g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',4,'mc','auto','대칭축이 가장 많은 도형은 어느 것인가요?',ARRAY['M5-2-u3-X08']::text[],true,'{"seq":9,"concept":"M5-2-u3-C4","difficulty":4,"kind":"mc","stem":"대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정삼각형","correct":true},{"t":"마름모","mis":"M5-2-u3-X08"},{"t":"직사각형","mis":"M5-2-u3-X08"},{"t":"이등변삼각형","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","마름모 2개, 정삼각형 3개, 직사각형 2개, 이등변삼각형 1개예요.","가장 많은 것은 정삼각형이에요"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정오각형","correct":true},{"t":"정사각형","mis":"M5-2-u3-X08"},{"t":"정삼각형","mis":"M5-2-u3-X08"},{"t":"마름모","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정사각형 4개, 정오각형 5개, 정삼각형 3개, 마름모 2개예요.","가장 많은 것은 정오각형이에요"]},{"stem":"이번에는 다른 보기예요. 대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정육각형","correct":true},{"t":"정사각형","mis":"M5-2-u3-X08"},{"t":"정오각형","mis":"M5-2-u3-X08"},{"t":"ㄱ자 모양","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정육각형 6개, 정사각형 4개, 정오각형 5개, ㄱ자 모양 1개예요.","가장 많은 것은 정육각형이에요"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L04_challenge#10','math',5,2,'u3','L04','g5_2_math_u3_L04_challenge','lesson_challenge','M5-2-u3-C4',4,'essay','teacher','가로 6 cm, 세로 4 cm인 직사각형의 대칭축은 몇 개인지 쓰고, 대각선이 대칭축이 될 수 없는 까닭을 「넓이」와 「접기」라는 말을 넣어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C4","difficulty":4,"kind":"essay","stem":"가로 6 cm, 세로 4 cm인 직사각형의 대칭축은 몇 개인지 쓰고, 대각선이 대칭축이 될 수 없는 까닭을 「넓이」와 「접기」라는 말을 넣어 설명하세요.","answer_guide":{"answer":"예: 직사각형의 대칭축은 세로로 가운데를 지나는 선과 가로로 가운데를 지나는 선, 모두 2개이다. 대각선은 직사각형을 넓이가 같은 두 삼각형으로 나누지만, 대각선을 따라 접으면 꼭짓점이 어긋나 완전히 겹치지 않는다. 넓이를 반으로 나누는 것과 접어서 겹치는 것은 다르므로 대각선은 대칭축이 아니다.","scoring_points":["대칭축이 2개라고 썼는가","대각선이 넓이를 반으로 나눈다고 썼는가","대각선으로 접으면 겹치지 않아 대칭축이 아니라고 썼는가"]},"explanation":["대칭축은 세로·가로 가운데 선 2개예요.","대각선은 넓이를 반으로 나눠요.","그런데 접으면 겹치지 않아 대칭축이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_basic#1','math',5,2,'u3','L05','g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',1,'mc','auto','선대칭도형에서 대칭축과 대응점을 이은 선분이 만나는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X11','M5-2-u3-X10']::text[],true,'{"seq":1,"concept":"M5-2-u3-C5","difficulty":1,"kind":"mc","stem":"선대칭도형에서 대칭축과 대응점을 이은 선분이 만나는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"수직으로 만난다","correct":true},{"t":"비스듬히 만난다","mis":"M5-2-u3-X11"},{"t":"만나지 않는다","mis":"M5-2-u3-X11"},{"t":"선분의 한 끝에서 만난다","mis":"M5-2-u3-X10"}],"explanation":["대응점은 접었을 때 겹치는 두 점이에요.","접은 선(대칭축)은 두 점을 이은 선분과 수직으로 만나요.","대칭축에서 두 대응점까지의 거리가 같아 선분을 똑같이 둘로 나눠요."],"variant_rule":{"alt":[{"stem":"선대칭도형에서 대칭축은 대응점을 이은 선분을 어떻게 나누나요?","options":[{"t":"수직으로 만나 똑같이 둘로 나눈다","correct":true},{"t":"비스듬히 만나 똑같이 둘로 나눈다","mis":"M5-2-u3-X11"},{"t":"한쪽이 더 길게 나눈다","mis":"M5-2-u3-X10"},{"t":"나누지 않고 선분의 끝을 지난다","mis":"M5-2-u3-X10"}],"explanation":["대응점은 접었을 때 겹치는 두 점이에요.","접은 선(대칭축)은 두 점을 이은 선분과 수직으로 만나요.","대칭축에서 두 대응점까지의 거리가 같아 선분을 똑같이 둘로 나눠요."]},{"stem":"선대칭도형에서 대응점을 이은 선분과 대칭축이 만나서 이루는 각은 몇 도인가요?","options":[{"t":"90°","correct":true},{"t":"45°","mis":"M5-2-u3-X11"},{"t":"180°","mis":"M5-2-u3-X15"},{"t":"그때그때 다르다","mis":"M5-2-u3-X11"}],"explanation":["대응점은 접었을 때 겹치는 두 점이에요.","접은 선(대칭축)은 두 점을 이은 선분과 수직으로 만나요.","대칭축에서 두 대응점까지의 거리가 같아 선분을 똑같이 둘로 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_basic#2','math',5,2,'u3','L05','g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',1,'sa','auto','선대칭도형에서 대칭축에서 한 대응점까지의 거리가 3 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C5","difficulty":1,"kind":"sa","stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 3 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 3 cm예요.","3 + 3 = 6(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 5 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 5 cm예요.","5 + 5 = 10(cm)예요."]},{"stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 7 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 7 cm예요.","7 + 7 = 14(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_basic#3','math',5,2,'u3','L05','g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',1,'sa','auto','선대칭도형에서 대칭축 한쪽에 있는 두 변의 길이가 4 cm, 3 cm예요. 반대쪽에 있는 대응변 두 개의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u3-C5","difficulty":1,"kind":"sa","stem":"선대칭도형에서 대칭축 한쪽에 있는 두 변의 길이가 4 cm, 3 cm예요. 반대쪽에 있는 대응변 두 개의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["대응변의 길이는 같아요.","반대쪽 대응변도 4 cm, 3 cm예요.","4 + 3 = 7(cm)예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"선대칭도형에서 대칭축 한쪽에 있는 두 변의 길이가 5 cm, 6 cm예요. 반대쪽에 있는 대응변 두 개의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["대응변의 길이는 같아요.","반대쪽 대응변도 5 cm, 6 cm예요.","5 + 6 = 11(cm)예요."]},{"stem":"선대칭도형에서 대칭축 한쪽에 있는 두 변의 길이가 2 cm, 7 cm예요. 반대쪽에 있는 대응변 두 개의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["대응변의 길이는 같아요.","반대쪽 대응변도 2 cm, 7 cm예요.","2 + 7 = 9(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_basic#4','math',5,2,'u3','L05','g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',1,'sa','auto','육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄷㅂ과 대칭축이 만나는 점이에요. 선분 ㄷㅂ과 대칭축이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C5","difficulty":1,"kind":"sa","stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄷㅂ과 대칭축이 만나는 점이에요. 선분 ㄷㅂ과 대칭축이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["점 ㄷ과 점 ㅂ은 대응점이에요.","대칭축은 대응점을 이은 선분과 수직으로 만나요.","그래서 90°예요."],"mis":"M5-2-u3-X11","asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"],"ㅅ":[60.0,64.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]],[[120,64.0],[0,64.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅂ은 선분 ㄱㄷ과 대칭축이 만나는 점이에요. 선분 ㄱㄷ과 대칭축이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["점 ㄱ과 점 ㄷ은 대응점이에요.","대칭축은 대응점을 이은 선분과 수직으로 만나요.","그래서 90°예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"],"ㅂ":[60.0,64.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]],[[0,64.0],[120,64.0]]]}],"tag":false}},{"stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅇ은 선분 ㄷㅁ과 대칭축이 만나는 점이에요. 선분 ㄷㅁ과 대칭축이 만나서 이루는 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["점 ㄷ과 점 ㅁ은 대응점이에요.","대칭축은 대응점을 이은 선분과 수직으로 만나요.","그래서 90°예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"],"ㅇ":[84.0,60.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","