INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_basic#8','math',5,2,'u3','L05','g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',2,'ox','auto','선대칭도형에서 대칭축은 대응점을 이은 선분을 수직으로 이등분해요.',ARRAY['M5-2-u3-X11']::text[],true,'{"seq":8,"concept":"M5-2-u3-C5","difficulty":2,"kind":"ox","stem":"선대칭도형에서 대칭축은 대응점을 이은 선분을 수직으로 이등분해요.","answer":"O","reason_options":[{"t":"접었을 때 두 점이 겹치려면 대칭축과 수직이고 양쪽 거리가 같아야 하므로","correct":true},{"t":"대칭축은 선분의 한쪽 끝을 지나므로","mis":"M5-2-u3-X11"}],"mis":"M5-2-u3-X11","explanation":["대응점은 접어서 겹치는 두 점이에요.","대칭축과 수직으로 만나고 양쪽 거리가 같아요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"선대칭도형에서 대응각의 크기는 서로 같아요.","answer":"O","reason_options":[{"t":"접으면 완전히 겹치므로","correct":true},{"t":"대칭축 오른쪽 각이 늘 더 크므로","mis":"M5-2-u3-X07"}],"explanation":["대응각은 접었을 때 겹치는 각이에요.","겹치려면 크기가 같아야 해요.","그래서 맞는 말이에요."]},{"stem":"선대칭도형에서 대칭축 위에 있는 꼭짓점의 대응점은 자기 자신이에요.","answer":"O","reason_options":[{"t":"대칭축 위의 점은 접어도 그 자리에 그대로 있으므로","correct":true},{"t":"대칭축 위의 점은 대응점이 없으므로","mis":"M5-2-u3-X12"}],"explanation":["접는 선 위에 있는 점은 접어도 움직이지 않아요.","그래서 자기 자신과 겹쳐요.","맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_basic#9','math',5,2,'u3','L05','g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',2,'mc','auto','선대칭도형의 성질로 틀린 것은 어느 것인가요?',ARRAY['M5-2-u3-X17']::text[],true,'{"seq":9,"concept":"M5-2-u3-C5","difficulty":2,"kind":"mc","stem":"선대칭도형의 성질로 틀린 것은 어느 것인가요?","options":[{"t":"대칭축에서 두 대응점까지의 거리는 한쪽이 더 길다","correct":true},{"t":"대응변의 길이가 같다","mis":"M5-2-u3-X17"},{"t":"대응각의 크기가 같다","mis":"M5-2-u3-X17"},{"t":"대칭축이 대응점을 이은 선분을 이등분한다","mis":"M5-2-u3-X17"}],"explanation":["선대칭도형은 대칭축으로 접으면 완전히 겹쳐요.","그래서 대응변의 길이·대응각의 크기가 같고, 대칭축은 대응점을 이은 선분을 수직으로 이등분해요.","「대칭축에서 두 대응점까지의 거리는 한쪽이 더 길다」가 틀렸어요."],"variant_rule":{"alt":[{"stem":"선대칭도형에 대한 설명으로 틀린 것은 어느 것인가요?","options":[{"t":"대칭축은 대응점을 이은 선분과 비스듬히 만난다","correct":true},{"t":"대칭축을 따라 접으면 완전히 겹친다","mis":"M5-2-u3-X17"},{"t":"대응각의 크기가 같다","mis":"M5-2-u3-X17"},{"t":"대응변의 길이가 같다","mis":"M5-2-u3-X17"}],"explanation":["선대칭도형은 대칭축으로 접으면 완전히 겹쳐요.","그래서 대응변의 길이·대응각의 크기가 같고, 대칭축은 대응점을 이은 선분을 수직으로 이등분해요.","「대칭축은 대응점을 이은 선분과 비스듬히 만난다」가 틀렸어요."]},{"stem":"선대칭도형에 대한 설명으로 틀린 것은 어느 것인가요?","options":[{"t":"대응각은 크기가 서로 다를 수 있다","correct":true},{"t":"대칭축이 여러 개인 도형도 있다","mis":"M5-2-u3-X17"},{"t":"대칭축은 대응점을 이은 선분을 수직으로 이등분한다","mis":"M5-2-u3-X17"},{"t":"대응변의 길이가 같다","mis":"M5-2-u3-X17"}],"explanation":["선대칭도형은 대칭축으로 접으면 완전히 겹쳐요.","그래서 대응변의 길이·대응각의 크기가 같고, 대칭축은 대응점을 이은 선분을 수직으로 이등분해요.","「대응각은 크기가 서로 다를 수 있다」가 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_basic#10','math',5,2,'u3','L05','g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',3,'sa','auto','육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄷㅂ과 대칭축이 만나는 점이에요. 선분 ㄷㅅ이 4 cm일 때 선분 ㄷㅂ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u3-C5","difficulty":3,"kind":"sa","stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄷㅂ과 대칭축이 만나는 점이에요. 선분 ㄷㅅ이 4 cm일 때 선분 ㄷㅂ은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["점 ㄷ과 점 ㅂ은 대응점이에요.","대칭축은 선분 ㄷㅂ을 똑같이 둘로 나눠 선분 ㅂㅅ도 4 cm예요.","4 + 4 = 8(cm)예요."],"mis":"M5-2-u3-X10","asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"],"ㅅ":[60.0,64.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]],[[120,64.0],[0,64.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅂ은 선분 ㄱㄷ과 대칭축이 만나는 점이에요. 선분 ㄱㅂ이 6 cm일 때 선분 ㄱㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["점 ㄱ과 점 ㄷ은 대응점이에요.","대칭축은 선분 ㄱㄷ을 똑같이 둘로 나눠 선분 ㄷㅂ도 6 cm예요.","6 + 6 = 12(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"],"ㅂ":[60.0,64.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]],[[0,64.0],[120,64.0]]]}],"tag":false}},{"stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅇ은 선분 ㄷㅁ과 대칭축이 만나는 점이에요. 선분 ㄷㅇ이 5 cm일 때 선분 ㄷㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["점 ㄷ과 점 ㅁ은 대응점이에요.","대칭축은 선분 ㄷㅁ을 똑같이 둘로 나눠 선분 ㅁㅇ도 5 cm예요.","5 + 5 = 10(cm)예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"],"ㅇ":[84.0,60.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]],[[84.0,0],[84.0,120]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_challenge#1','math',5,2,'u3','L05','g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',2,'sa','auto','선대칭도형에서 두 대응점 사이의 거리가 10 cm예요. 대칭축에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C5","difficulty":2,"kind":"sa","stem":"선대칭도형에서 두 대응점 사이의 거리가 10 cm예요. 대칭축에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","그래서 한쪽은 전체의 반이에요.","10 ÷ 2 = 5(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형에서 두 대응점 사이의 거리가 16 cm예요. 대칭축에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","그래서 한쪽은 전체의 반이에요.","16 ÷ 2 = 8(cm)예요."]},{"stem":"선대칭도형에서 두 대응점 사이의 거리가 18 cm예요. 대칭축에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","그래서 한쪽은 전체의 반이에요.","18 ÷ 2 = 9(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_challenge#2','math',5,2,'u3','L05','g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',2,'mc','auto','육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 점 ㄹ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X15']::text[],true,'{"seq":2,"concept":"M5-2-u3-C5","difficulty":2,"kind":"mc","stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 점 ㄹ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X06"},{"t":"점 ㄱ","mis":"M5-2-u3-X06"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"}],"explanation":["대응점은 대칭축을 따라 접었을 때 겹치는 점이에요.","점 ㄹ을 대칭축 건너편으로 같은 거리만큼 옮기면 점 ㅁ이에요.","그래서 점 ㄹ의 대응점은 점 ㅁ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 점 ㄱ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅅ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X06"},{"t":"점 ㄷ","mis":"M5-2-u3-X06"},{"t":"점 ㄱ","mis":"M5-2-u3-X15"}],"explanation":["대응점은 대칭축을 따라 접었을 때 겹치는 점이에요.","점 ㄱ을 대칭축 건너편으로 같은 거리만큼 옮기면 점 ㅅ이에요.","그래서 점 ㄱ의 대응점은 점 ㅅ이에요."],"asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]]]}],"tag":false}},{"stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 점 ㅁ의 대응점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄱ","mis":"M5-2-u3-X06"},{"t":"점 ㄴ","mis":"M5-2-u3-X06"},{"t":"점 ㅁ","mis":"M5-2-u3-X15"}],"explanation":["대응점은 대칭축을 따라 접었을 때 겹치는 점이에요.","점 ㅁ을 대칭축 건너편으로 같은 거리만큼 옮기면 점 ㄹ이에요.","그래서 점 ㅁ의 대응점은 점 ㄹ이에요.