INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_challenge#3','math',5,2,'u3','L05','g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',3,'sa','auto','육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄱㄴ과 대칭축이 만나는 점이에요. 선분 ㄱㅅ이 7 cm일 때 선분 ㄱㄴ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u3-C5","difficulty":3,"kind":"sa","stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄱㄴ과 대칭축이 만나는 점이에요. 선분 ㄱㅅ이 7 cm일 때 선분 ㄱㄴ은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["점 ㄱ과 점 ㄴ은 대응점이에요.","대칭축은 선분 ㄱㄴ을 똑같이 둘로 나눠 선분 ㄴㅅ도 7 cm예요.","7 + 7 = 14(cm)예요."],"mis":"M5-2-u3-X10","asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"],"ㅅ":[60.0,24.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]],[[20,24.0],[100,24.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅇ은 선분 ㄴㅂ과 대칭축이 만나는 점이에요. 선분 ㄴㅇ이 8 cm일 때 선분 ㄴㅂ은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["점 ㄴ과 점 ㅂ은 대응점이에요.","대칭축은 선분 ㄴㅂ을 똑같이 둘로 나눠 선분 ㅂㅇ도 8 cm예요.","8 + 8 = 16(cm)예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"],"ㅇ":[84.0,60.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]],[[84.0,30.0],[84.0,90.0]]]}],"tag":false}},{"stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅂ은 선분 ㅁㄹ과 대칭축이 만나는 점이에요. 선분 ㅁㅂ이 9 cm일 때 선분 ㅁㄹ은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["점 ㅁ과 점 ㄹ은 대응점이에요.","대칭축은 선분 ㅁㄹ을 똑같이 둘로 나눠 선분 ㄹㅂ도 9 cm예요.","9 + 9 = 18(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"],"ㅂ":[60.0,124.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]],[[20,124.0],[100,124.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_challenge#4','math',5,2,'u3','L05','g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',3,'sa','auto','오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㄴ 6 cm, 변 ㄷㄹ 7 cm, 변 ㄹㅁ 8 cm일 때 이 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C5","difficulty":3,"kind":"sa","stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㄴ 6 cm, 변 ㄷㄹ 7 cm, 변 ㄹㅁ 8 cm일 때 이 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["대칭축 건너편 대응변은 길이가 같아요.","둘레의 변을 모두 쓰면 6, 6, 7, 8, 7이에요.","6 + 6 + 7 + 8 + 7 = 34(cm)예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㄴ 8 cm, 변 ㄴㄷ 5 cm, 변 ㄷㄹ 6 cm, 변 ㄹㅁ 4 cm일 때 이 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["대칭축 건너편 대응변은 길이가 같아요.","둘레의 변을 모두 쓰면 8, 5, 6, 4, 6, 5예요.","8 + 5 + 6 + 4 + 6 + 5 = 34(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false}},{"stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㄴ 9 cm, 변 ㄷㄹ 5 cm, 변 ㄹㅁ 6 cm일 때 이 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["대칭축 건너편 대응변은 길이가 같아요.","둘레의 변을 모두 쓰면 9, 9, 5, 6, 5예요.","9 + 9 + 5 + 6 + 5 = 34(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false}}]}}':