INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_challenge#5','math',5,2,'u3','L05','g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',3,'error','auto','친구들이 선대칭도형의 성질에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u3-X10','M5-2-u3-X11','M5-2-u3-X07']::text[],true,'{"seq":5,"concept":"M5-2-u3-C5","difficulty":3,"kind":"error","stem":"친구들이 선대칭도형의 성질에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「대칭축에서 대응점까지 5 cm니까 두 대응점 사이도 5 cm야.」","correct":true,"mis_target":"M5-2-u3-X10"},{"t":"도윤 — 「대칭축은 대응점을 이은 선분과 수직으로 만나.」","mis":"M5-2-u3-X11"},{"t":"하린 — 「대응변의 길이는 같아.」","mis":"M5-2-u3-X07"}],"explanation":["선대칭도형은 대칭축으로 접으면 대응점끼리 겹쳐요.","대칭축은 대응점을 이은 선분을 수직으로 이등분하고, 대응변·대응각은 같아요.","수아의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 선대칭도형의 성질에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「대칭축은 대응점을 이은 선분과 비스듬히 만나.」","correct":true,"mis_target":"M5-2-u3-X11"},{"t":"서연 — 「두 대응점 사이가 12 cm면 대칭축까지는 6 cm야.」","mis":"M5-2-u3-X10"},{"t":"지호 — 「대응각의 크기는 같아.」","mis":"M5-2-u3-X07"}],"explanation":["선대칭도형은 대칭축으로 접으면 대응점끼리 겹쳐요.","대칭축은 대응점을 이은 선분을 수직으로 이등분하고, 대응변·대응각은 같아요.","민준의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 선대칭도형의 성질에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「대응점은 이름 차례대로 짝지으면 돼.」","correct":true,"mis_target":"M5-2-u3-X06"},{"t":"나린 — 「대칭축으로 접으면 대응점끼리 겹쳐.」","mis":"M5-2-u3-X06"},{"t":"유진 — 「대칭축 위의 점은 접어도 제자리야.」","mis":"M5-2-u3-X12"}],"explanation":["선대칭도형은 대칭축으로 접으면 대응점끼리 겹쳐요.","대칭축은 대응점을 이은 선분을 수직으로 이등분하고, 대응변·대응각은 같아요.","가온의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_challenge#6','math',5,2,'u3','L05','g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',3,'ox','auto','선대칭도형에서 대칭축에서 한 대응점까지 4 cm라면 두 대응점 사이도 4 cm예요.',ARRAY['M5-2-u3-X10']::text[],true,'{"seq":6,"concept":"M5-2-u3-C5","difficulty":3,"kind":"ox","stem":"선대칭도형에서 대칭축에서 한 대응점까지 4 cm라면 두 대응점 사이도 4 cm예요.","answer":"X","reason_options":[{"t":"양쪽이 4 cm씩이라 두 대응점 사이는 8 cm이므로","correct":true},{"t":"대칭축이 선분을 나누지 않으므로","mis":"M5-2-u3-X10"}],"mis":"M5-2-u3-X10","explanation":["대칭축에서 다른 대응점까지도 4 cm예요.","두 대응점 사이는 4 + 4 = 8(cm)예요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"대칭축에서 한쪽 대응점까지 3 cm, 다른 쪽까지 4 cm여도 접으면 겹쳐요.","answer":"X","reason_options":[{"t":"거리가 다르면 접었을 때 점이 어긋나므로","correct":true},{"t":"조금 차이는 겹치는 데 상관없으므로","mis":"M5-2-u3-X10"}],"explanation":["접으면 3 cm 자리와 4 cm 자리가 어긋나요.","점이 어긋나면 변도 어긋나요.","그래서 틀린 말이에요."]},{"stem":"선대칭도형에서 대칭축 위에 있는 꼭짓점의 대응점은 자기 자신이에요.","answer":"O","reason_options":[{"t":"대칭축 위의 점은 접어도 그 자리에 그대로 있으므로","correct":true},{"t":"대칭축 위의 점은 대응점이 없으므로","mis":"M5-2-u3-X12"}],"explanation":["접는 선 위에 있는 점은 접어도 움직이지 않아요.","그래서 자기 자신과 겹쳐요.","맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_challenge#7','math',5,2,'u3','L05','g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',3,'sa','auto','칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄷㄹ이 9 cm일 때, 변 ㅁㄹ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u3-C5","difficulty":3,"kind":"sa","stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄷㄹ이 9 cm일 때, 변 ㅁㄹ은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["점 ㄷ ↔ 점 ㅁ, 점 ㄹ ↔ 점 ㄹ이 대응점이에요.","그래서 변 ㄷㄹ과 변 ㅁㄹ은 대응변이에요.","대응변의 길이는 같으므로 9 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄷㄹ이 7 cm일 때, 변 ㅂㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["점 ㄷ ↔ 점 ㅂ, 점 ㄹ ↔ 점 ㅁ이 대응점이에요.","그래서 변 ㄷㄹ과 변 ㅂㅁ은 대응변이에요.","대응변의 길이는 같으므로 7 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false}},{"stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄷㄹ이 8 cm일 때, 변 ㄱㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["점 ㄷ ↔ 점 ㄱ, 점 ㄹ ↔ 점 ㅁ이 대응점이에요.","그래서 변 ㄷㄹ과 변 ㄱㅁ은 대응변이에요.","대응변의 길이는 같으므로 8 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, diff