INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_challenge#8','math',5,2,'u3','L05','g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',4,'sa','auto','칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㄴ 4 cm, 변 ㄴㄷ 2 cm, 변 ㄷㄹ 5 cm, 변 ㅅㄱ 3 cm일 때 이 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C5","difficulty":4,"kind":"sa","stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㄴ 4 cm, 변 ㄴㄷ 2 cm, 변 ㄷㄹ 5 cm, 변 ㅅㄱ 3 cm일 때 이 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["대칭축 건너편 대응변은 길이가 같아요.","둘레의 변을 모두 쓰면 4, 2, 5, 5, 2, 4, 3이에요.","4 + 2 + 5 + 5 + 2 + 4 + 3 = 25(cm)예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㄴ 6 cm, 변 ㄴㄷ 3 cm, 변 ㄷㄹ 5 cm, 변 ㄹㅁ 2 cm일 때 이 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["대칭축 건너편 대응변은 길이가 같아요.","둘레의 변을 모두 쓰면 6, 3, 5, 2, 5, 3이에요.","6 + 3 + 5 + 2 + 5 + 3 = 24(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false}},{"stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㄴ 6 cm, 변 ㄴㄷ 1 cm, 변 ㄷㄹ 4 cm, 변 ㅅㄱ 5 cm일 때 이 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["대칭축 건너편 대응변은 길이가 같아요.","둘레의 변을 모두 쓰면 6, 1, 4, 4, 1, 6, 5예요.","6 + 1 + 4 + 4 + 1 + 6 + 5 = 27(cm)예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_challenge#9','math',5,2,'u3','L05','g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',4,'mc','auto','칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 각 ㄴ이 135°일 때 각 ㅂ은 몇 도인가요?',ARRAY['M5-2-u3-X07','M5-2-u3-X10','M5-2-u3-X11']::text[],true,'{"seq":9,"concept":"M5-2-u3-C5","difficulty":4,"kind":"mc","stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 각 ㄴ이 135°일 때 각 ㅂ은 몇 도인가요?","options":[{"t":"135°","correct":true},{"t":"45°","mis":"M5-2-u3-X07"},{"t":"270°","mis":"M5-2-u3-X10"},{"t":"90°","mis":"M5-2-u3-X11"}],"explanation":["점 ㄴ의 대응점은 점 ㅂ이에요.","그래서 각 ㄴ과 각 ㅂ은 대응각이에요.","대응각의 크기는 같으므로 135°예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 각 ㄹ이 120°일 때 각 ㅁ은 몇 도인가요?","options":[{"t":"120°","correct":true},{"t":"60°","mis":"M5-2-u3-X07"},{"t":"240°","mis":"M5-2-u3-X10"},{"t":"90°","mis":"M5-2-u3-X11"}],"explanation":["점 ㄹ의 대응점은 점 ㅁ이에요.","그래서 각 ㄹ과 각 ㅁ은 대응각이에요.","대응각의 크기는 같으므로 120°예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false}},{"stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 각 ㄷ이 115°일 때 각 ㄱ은 몇 도인가요?","options":[{"t":"115°","correct":true},{"t":"65°","mis":"M5-2-u3-X07"},{"t":"230°","mis":"M5-2-u3-X10"},{"t":"90°","mis":"M5-2-u3-X11"}],"explanation":["점 ㄷ의 대응점은 점 ㄱ이에요.","그래서 각 ㄷ과 각 ㄱ은 대응각이에요.","대응각의 크기는 같으므로 115°예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_challenge#10','math',5,2,'u3','L05','g5_2_math_u3_L05_challenge','lesson_challenge','M5-2-u3-C5',4,'essay','teacher','선대칭도형에서 대응점 ㄱ과 ㄴ을 이은 선분이 대칭축과 만나는 점을 ㄷ이라고 해요. 선분 ㄱㄷ이 3 cm일 때 선분 ㄱㄴ의 길이를 구하고, 만약 선분 ㄱㄷ이 3 cm, 선분 ㄴㄷ이 4 cm라면 이 도형이 선대칭도형이 될 수 없는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C5","difficulty":4,"kind":"essay","stem":"선대칭도형에서 대응점 ㄱ과 ㄴ을 이은 선분이 대칭축과 만나는 점을 ㄷ이라고 해요. 선분 ㄱㄷ이 3 cm일 때 선분 ㄱㄴ의 길이를 구하고, 만약 선분 ㄱㄷ이 3 cm, 선분 ㄴㄷ이 4 cm라면 이 도형이 선대칭도형이 될 수 없는 까닭을 쓰세요.","answer_guide":{"answer":"예: 대칭축은 대응점을 이은 선분을 수직으로 이등분하므로 선분 ㄴㄷ도 3 cm이고, 선분 ㄱㄴ은 3 + 3 = 6(cm)이다. 선분 ㄱㄷ이 3 cm, 선분 ㄴㄷ이 4 cm라면 대칭축을 따라 접었을 때 점 ㄱ과 점 ㄴ이 겹치지 않고 어긋난다. 점이 어긋나면 변도 어긋나 완전히 겹칠 수 없으므로 선대칭도형이 될 수 없다.","scoring_points":["선분 ㄱㄴ을 6 cm로 구했는가","대칭축이 선분을 이등분한다는 성질을 썼는가","거리가 다르면 접었을 때 점이 어긋나 겹치지 않는다고 썼는가"]},"explanation":["대칭축은 선분 ㄱㄴ을 이등분해요.","3 + 3 = 6(cm)이에요.","거리가 다르면 접어도 점이 어긋나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_basic#1','math',5,2,'u3','L06','g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',1,'mc','auto','선대칭도형을 완성할 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['M5-2-u3-X12','M5-2-u3-X17']::text[],true,'{"seq":1,"concept":"M5-2-u3-C6","difficulty":1,"kind":"mc","stem":"선대칭도형을 완성할 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"각 꼭짓점에서 대칭축까지의 거리를 잰다","correct":true},{"t":"변을 먼저 그린다","mis":"M5-2-u3-X12"},{"t":"도형에 색을 칠한다","mis":"M5-2-u3-X17"},{"t":"둘레를 구한다","mis":"M5-2-u3-X17"}],"explanation":["① 각 꼭짓점에서 대칭축까지의 거리를 재요.","② 반대쪽에 같은 거리만큼 떨어진 곳에 대응점을 찍어요.","③ 찍은 점을 차례대로 이어요 — 선부터 그으면 어디까지 그릴지 몰라요."],"variant_rule":{"alt":[{"stem":"선대칭도형을 완성하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"거리 재기 → 반대쪽에 대응점 찍기 → 차례대로 잇기","correct":true},{"t":"변 긋기 → 대응점 찍기 → 거리 재기","mis":"M5-2-u3-X12"},{"t":"대응점 찍기 → 거리 재기 → 색칠하기","mis":"M5-2-u3-X12"},{"t":"차례대로 잇기 → 거리 재기 → 대응점 찍기","mis":"M5-2-u3-X12"}],"explanation":["① 각 꼭짓점에서 대칭축까지의 거리를 재요.","② 반대쪽에 같은 거리만큼 떨어진 곳에 대응점을 찍어요.","③ 찍은 점을 차례대로 이어요 — 선부터 그으면 어디까지 그릴지 몰라요."]},{"stem":"선대칭도형을 그릴 때 점을 먼저 찍고 선을 나중에 긋는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대응점을 모두 찍은 뒤 이어야 어디까지 그릴지 알 수 있기 때문에","correct":true},{"t":"선을 먼저 그으면 모눈이 지워지기 때문에","mis":"M5-2-u3-X17"},{"t":"점은 몇 개를 찍어도 상관없기 때문에","mis":"M5-2-u3-X12"},{"t":"선은 대칭축과 늘 수직이기 때문에","mis":"M5-2-u3-X11"}],"explanation":["① 각 꼭짓점에서 대칭축까지의 거리를 재요.","② 반대쪽에 같은 거리만큼 떨어진 곳에 대응점을 찍어요.","③ 찍은 점을 차례대로 이어요 — 선부터 그으면 어디까지 그릴지 몰라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_basic#2','math',5,2,'u3','L06','g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',1,'sa','auto','선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 4칸 떨어져 있다면, 대응점은 대칭축에서 반대쪽으로 몇 칸 간 자리에 찍나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C6","difficulty":1,"kind":"sa","stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 4칸 떨어져 있다면, 대응점은 대칭축에서 반대쪽으로 몇 칸 간 자리에 찍나요? 숫자로 쓰세요.","answer":["4"],"explanation":["대칭축에서 두 대응점까지의 거리는 같아요.","그래서 반대쪽으로도 4칸 가요.","대칭축과 수직인 방향으로 4칸이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 3칸 떨어져 있다면, 대응점은 대칭축에서 반대쪽으로 몇 칸 간 자리에 찍나요? 숫자로 쓰세요.","answer":["3"],"explanation":["대칭축에서 두 대응점까지의 거리는 같아요.","그래서 반대쪽으로도 3칸 가요.","대칭축과 수직인 방향으로 3칸이에요."]},{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 5칸 떨어져 있다면, 대응점은 대칭축에서 반대쪽으로 몇 칸 간 자리에 찍나요? 숫자로 쓰세요.","answer":["5"],"explanation":["대칭축에서 두 대응점까지의 거리는 같아요.","그래서 반대쪽으로도 5칸 가요.","대칭축과 수직인 방향으로 5칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_basic#3','math',5,2,'u3','L06','g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',1,'mc','auto','선대칭도형을 그릴 때 대칭축 위에 있는 꼭짓점은 어떻게 하나요?',ARRAY['M5-2-u3-X12','M5-2-u3-X10']::text[],true,'{"seq":3,"concept":"M5-2-u3-C6","difficulty":1,"kind":"mc","stem":"선대칭도형을 그릴 때 대칭축 위에 있는 꼭짓점은 어떻게 하나요?","options":[{"t":"제자리에 그대로 둔다","correct":true},{"t":"반대쪽으로 옮긴다","mis":"M5-2-u3-X12"},{"t":"지운다","mis":"M5-2-u3-X12"},{"t":"두 배로 늘린다","mis":"M5-2-u3-X10"}],"explanation":["대칭축 위의 점은 대칭축까지의 거리가 0칸이에요.","반대쪽으로 0칸 가면 제자리예요.","접어도 움직이지 않으니 그대로 둬요."],"variant_rule":{"alt":[{"stem":"대칭축 위에 있는 꼭짓점의 대응점은 어디인가요?","options":[{"t":"그 꼭짓점 자기 자리","correct":true},{"t":"대칭축에서 1칸 떨어진 자리","mis":"M5-2-u3-X12"},{"t":"대칭축 반대쪽 끝","mis":"M5-2-u3-X12"},{"t":"대응점이 없다","mis":"M5-2-u3-X12"}],"explanation":["대칭축 위의 점은 대칭축까지의 거리가 0칸이에요.","반대쪽으로 0칸 가면 제자리예요.","접어도 움직이지 않으니 그대로 둬요."]},{"stem":"선대칭도형을 그릴 때 대칭축에서 0칸 떨어진 꼭짓점의 대응점은 어디에 찍나요?","options":[{"t":"그 꼭짓점과 같은 자리","correct":true},{"t":"반대쪽으로 1칸 간 자리","mis":"M5-2-u3-X12"},{"t":"반대쪽으로 2칸 간 자리","mis":"M5-2-u3-X10"},{"t":"찍을 수 없다","mis":"M5-2-u3-X12"}],"explanation":["대칭축 위의 점은 대칭축까지의 거리가 0칸이에요.","반대쪽으로 0칸 가면 제자리예요.","접어도 움직이지 않으니 그대로 둬요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_basic#4','math',5,2,'u3','L06','g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',1,'mc','auto','선대칭도형 그리기를 마친 뒤 확인하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X02']::text[],true,'{"seq":4,"concept":"M5-2-u3-C6","difficulty":1,"kind":"mc","stem":"선대칭도형 그리기를 마친 뒤 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"대칭축으로 접어 완전히 겹치는지 본다","correct":true},{"t":"반 바퀴 돌려 겹치는지 본다","mis":"M5-2-u3-X15"},{"t":"색이 같은지 본다","mis":"M5-2-u3-X02"},{"t":"변의 개수만 센다","mis":"M5-2-u3-X02"}],"explanation":["선대칭도형은 대칭축으로 접으면 완전히 겹쳐요.","대응점이 대칭축에서 같은 거리에 있어야 겹쳐요.","어긋나면 그 대응점을 다시 찍어요."],"variant_rule":{"alt":[{"stem":"순달이가 그린 선대칭도형이 바른지 알아보는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"대응점이 대칭축에서 같은 거리에 있는지 재어 본다","correct":true},{"t":"넓이만 재어 본다","mis":"M5-2-u3-X05"},{"t":"도형의 꼭짓점 수만 센다","mis":"M5-2-u3-X02"},{"t":"대칭축의 길이를 잰다","mis":"M5-2-u3-X10"}],"explanation":["선대칭도형은 대칭축으로 접으면 완전히 겹쳐요.","대응점이 대칭축에서 같은 거리에 있어야 겹쳐요.","어긋나면 그 대응점을 다시 찍어요."]},{"stem":"완성한 선대칭도형을 대칭축으로 접었더니 한 꼭짓점이 삐져나왔어요. 알 수 있는 것은 어느 것인가요?","options":[{"t":"그 꼭짓점의 대응점을 잘못 찍었다","correct":true},{"t":"도형이 점대칭도형이다","mis":"M5-2-u3-X15"},{"t":"대칭축이 두 개다","mis":"M5-2-u3-X08"},{"t":"바르게 그렸다","mis":"M5-2-u3-X17"}],"explanation":["선대칭도형은 대칭축으로 접으면 완전히 겹쳐요.","대응점이 대칭축에서 같은 거리에 있어야 겹쳐요.","어긋나면 그 대응점을 다시 찍어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_basic#5','math',5,2,'u3','L06','g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',2,'mc','auto','모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":5,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 3칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 3칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":160.0,"pts":{"ㄱ":[20,70.0,"w"],"ㄴ":[140,70.0,"e"],"ㄷ":[160,70.0,"e"],"ㄹ":[140,50.0,"e"]},"seg":[[[80,20.0],[80,140.0]],[[80,30.0],[20,70.0]],[[20,70.0],[60,110.0]],[[60,110.0],[80,130.0]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 2칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 2칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":160,"h":160.0,"pts":{"ㄱ":[40,90.0,"w"],"ㄴ":[120,70.0,"e"],"ㄷ":[120,90.0,"e"],"ㄹ":[140,90.0,"e"]},"seg":[[[80,20.0],[80,140.0]],[[80,30.0],[40,90.0]],[[40,90.0],[20,50.0]],[[20,50.0],[80,130.0]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 4칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 4칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄹ이에요."],"asset":{"type":"geo","items":[{"w":220,"h":160.0,"pts":{"ㄱ":[20,50.0,"w"],"ㄴ":[200,50.0,"e"],"ㄷ":[180,30.0,"e"],"ㄹ":[180,50.0,"e"]},"seg":[[[100,20.0],[100,140.0]],[[100,30.0],[20,50.0]],[[20,50.0],[60,110.0]],[[60,110.0],[100,130.0]]],"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_basic#6','math',5,2,'u3','L06','g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',2,'sa','auto','선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 2칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C6","difficulty":2,"kind":"sa","stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 2칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["대응점은 반대쪽으로 2칸 간 자리예요.","꼭짓점에서 대칭축까지 2칸, 대칭축에서 대응점까지 2칸이에요.","2 + 2 = 4(칸)이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 4칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대응점은 반대쪽으로 4칸 간 자리예요.","꼭짓점에서 대칭축까지 4칸, 대칭축에서 대응점까지 4칸이에요.","4 + 4 = 8(칸)이에요."]},{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 6칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["대응점은 반대쪽으로 6칸 간 자리예요.","꼭짓점에서 대칭축까지 6칸, 대칭축에서 대응점까지 6칸이에요.","6 + 6 = 12(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_basic#7','math',5,2,'u3','L06','g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',2,'mc','auto','대칭축이 비스듬한 경우 대응점을 찍는 방향은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":7,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"대칭축이 비스듬한 경우 대응점을 찍는 방향은 어느 것인가요?","options":[{"t":"대칭축과 수직인 방향","correct":true},{"t":"가로 방향","mis":"M5-2-u3-X12"},{"t":"세로 방향","mis":"M5-2-u3-X12"},{"t":"아무 방향이나","mis":"M5-2-u3-X12"}],"explanation":["대응점을 이은 선분은 대칭축과 수직으로 만나요.","그래서 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로·세로 칸만 세면 대칭축이 비스듬할 때 자리가 어긋나요."],"variant_rule":{"alt":[{"stem":"대칭축이 세로선일 때 대응점은 어느 쪽으로 가서 찍나요?","options":[{"t":"대칭축과 수직인 가로 방향으로 반대쪽","correct":true},{"t":"세로 방향으로 아래쪽","mis":"M5-2-u3-X12"},{"t":"비스듬히 위쪽","mis":"M5-2-u3-X12"},{"t":"대칭축을 따라 위쪽","mis":"M5-2-u3-X12"}],"explanation":["대응점을 이은 선분은 대칭축과 수직으로 만나요.","그래서 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로·세로 칸만 세면 대칭축이 비스듬할 때 자리가 어긋나요."]},{"stem":"대칭축이 가로선일 때 대응점은 어느 쪽으로 가서 찍나요?","options":[{"t":"대칭축과 수직인 세로 방향으로 반대쪽","correct":true},{"t":"가로 방향으로 오른쪽","mis":"M5-2-u3-X12"},{"t":"비스듬히 오른쪽 아래","mis":"M5-2-u3-X12"},{"t":"대칭축을 따라 왼쪽","mis":"M5-2-u3-X12"}],"explanation":["대응점을 이은 선분은 대칭축과 수직으로 만나요.","그래서 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로·세로 칸만 세면 대칭축이 비스듬할 때 자리가 어긋나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_basic#8','math',5,2,'u3','L06','g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',2,'ox','auto','선대칭도형을 그릴 때는 대응점을 모두 찍은 뒤 차례대로 이어요.',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":8,"concept":"M5-2-u3-C6","difficulty":2,"kind":"ox","stem":"선대칭도형을 그릴 때는 대응점을 모두 찍은 뒤 차례대로 이어요.","answer":"O","reason_options":[{"t":"점을 먼저 찍어야 어디까지 그릴지 알 수 있으므로","correct":true},{"t":"선부터 그어야 빨리 끝나므로","mis":"M5-2-u3-X12"}],"mis":"M5-2-u3-X12","explanation":["대응점을 먼저 모두 찍어요.","그다음 원래 도형의 차례대로 이어요.","맞는 말이에요."],"variant_rule":{"alt":[{"stem":"대칭축 위에 있는 꼭짓점은 그리기를 할 때 옮기지 않아요.","answer":"O","reason_options":[{"t":"대칭축 위의 점은 대응점이 자기 자신이므로","correct":true},{"t":"대칭축 위의 점은 지워야 하므로","mis":"M5-2-u3-X12"}],"explanation":["대칭축까지 0칸이에요.","반대쪽으로 0칸 가면 제자리예요.","맞는 말이에요."]},{"stem":"세로 대칭축으로 대응점을 찍을 때 위아래 자리는 그대로예요.","answer":"O","reason_options":[{"t":"대칭축과 수직인 가로 방향으로만 움직이므로","correct":true},{"t":"대칭축만큼 아래로 내려가야 하므로","mis":"M5-2-u3-X12"}],"explanation":["세로 대칭축과 수직인 방향은 가로예요.","가로로만 가니 높이는 그대로예요.","맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_basic#9','math',5,2,'u3','L06','g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',2,'sa','auto','대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 3 cm, 4 cm, 3 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C6","difficulty":2,"kind":"sa","stem":"대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 3 cm, 4 cm, 3 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 3 + 4 + 3 = 10(cm)예요.","둘레는 10 × 2 = 20(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 2 cm, 5 cm, 4 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 2 + 5 + 4 = 11(cm)예요.","둘레는 11 × 2 = 22(cm)예요."]},{"stem":"대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 5 cm, 3 cm, 2 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 5 + 3 + 2 = 10(cm)예요.","둘레는 10 × 2 = 20(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_basic#10','math',5,2,'u3','L06','g5_2_math_u3_L06_basic','lesson_basic','M5-2-u3-C6',3,'sa','auto','대칭축에서 1칸, 3칸, 5칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u3-C6","difficulty":3,"kind":"sa","stem":"대칭축에서 1칸, 3칸, 5칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["꼭짓점과 대응점 사이는 대칭축까지 거리의 두 배예요.","1 × 2 = 2, 3 × 2 = 6, 5 × 2 = 10이에요.","2 + 6 + 10 = 18(칸)이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"대칭축에서 2칸, 4칸, 1칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["꼭짓점과 대응점 사이는 대칭축까지 거리의 두 배예요.","2 × 2 = 4, 4 × 2 = 8, 1 × 2 = 2예요.","4 + 8 + 2 = 14(칸)이에요."]},{"stem":"대칭축에서 3칸, 2칸, 6칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["꼭짓점과 대응점 사이는 대칭축까지 거리의 두 배예요.","3 × 2 = 6, 2 × 2 = 4, 6 × 2 = 12예요.","6 + 4 + 12 = 22(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_challenge#1','math',5,2,'u3','L06','g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',2,'mc','auto','모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12','M5-2-u3-X10']::text[],true,'{"seq":1,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄴ","mis":"M5-2-u3-X10"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 2칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 2칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":140.0,"pts":{"ㄱ":[40,50.0,"w"],"ㄴ":[160,50.0,"e"],"ㄷ":[120,50.0,"e"],"ㄹ":[140,50.0,"e"]},"seg":[[[80,20.0],[80,120.0]],[[80,30.0],[40,50.0]],[[40,50.0],[20,90.0]],[[20,90.0],[80,110.0]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄷ","mis":"M5-2-u3-X10"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 3칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 3칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":220,"h":140.0,"pts":{"ㄱ":[20,90.0,"w"],"ㄴ":[140,90.0,"e"],"ㄷ":[200,90.0,"e"],"ㄹ":[140,70.0,"e"]},"seg":[[[80,20.0],[80,120.0]],[[80,30.0],[20,90.0]],[[20,90.0],[60,50.0]],[[60,50.0],[80,110.0]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄷ","mis":"M5-2-u3-X10"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 1칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 1칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄹ이에요."],"asset":{"type":"geo","items":[{"w":140,"h":140.0,"pts":{"ㄱ":[60,70.0,"w"],"ㄴ":[100,50.0,"e"],"ㄷ":[120,70.0,"e"],"ㄹ":[100,70.0,"e"]},"seg":[[[80,20.0],[80,120.0]],[[80,30.0],[60,70.0]],[[60,70.0],[20,90.0]],[[20,90.0],[80,110.0]]],"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_challenge#2','math',5,2,'u3','L06','g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',2,'sa','auto','선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 7칸 떨어져 있다면, 대응점은 대칭축에서 반대쪽으로 몇 칸 간 자리에 찍나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C6","difficulty":2,"kind":"sa","stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 7칸 떨어져 있다면, 대응점은 대칭축에서 반대쪽으로 몇 칸 간 자리에 찍나요? 숫자로 쓰세요.","answer":["7"],"explanation":["대칭축에서 두 대응점까지의 거리는 같아요.","그래서 반대쪽으로도 7칸 가요.","대칭축과 수직인 방향으로 7칸이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 8칸 떨어져 있다면, 대응점은 대칭축에서 반대쪽으로 몇 칸 간 자리에 찍나요? 숫자로 쓰세요.","answer":["8"],"explanation":["대칭축에서 두 대응점까지의 거리는 같아요.","그래서 반대쪽으로도 8칸 가요.","대칭축과 수직인 방향으로 8칸이에요."]},{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 6칸 떨어져 있다면, 대응점은 대칭축에서 반대쪽으로 몇 칸 간 자리에 찍나요? 숫자로 쓰세요.","answer":["6"],"explanation":["대칭축에서 두 대응점까지의 거리는 같아요.","그래서 반대쪽으로도 6칸 가요.","대칭축과 수직인 방향으로 6칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_challenge#3','math',5,2,'u3','L06','g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',3,'mc','auto','모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":3,"concept":"M5-2-u3-C6","difficulty":3,"kind":"mc","stem":"모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄷ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄴ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":160,"h":160,"pts":{"ㄱ":[40,80,"nw"],"ㄴ":[80,40,"se"],"ㄷ":[120,80,"se"],"ㄹ":[100,20,"se"]},"seg":[[[20,20],[140,140]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄴ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄹ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":200,"h":200,"pts":{"ㄱ":[40,100,"nw"],"ㄴ":[160,100,"se"],"ㄷ":[120,20,"se"],"ㄹ":[100,40,"se"]},"seg":[[[20,20],[180,180]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄹ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄷ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":180,"h":180,"pts":{"ㄱ":[60,100,"nw"],"ㄴ":[120,40,"se"],"ㄷ":[100,60,"se"],"ㄹ":[140,100,"se"]},"seg":[[[20,20],[160,160]]],"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_challenge#4','math',5,2,'u3','L06','g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',3,'sa','auto','대칭축에서 2칸, 3칸, 4칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C6","difficulty":3,"kind":"sa","stem":"대칭축에서 2칸, 3칸, 4칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["꼭짓점과 대응점 사이는 대칭축까지 거리의 두 배예요.","2 × 2 = 4, 3 × 2 = 6, 4 × 2 = 8이에요.","4 + 6 + 8 = 18(칸)이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"대칭축에서 1칸, 5칸, 6칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["꼭짓점과 대응점 사이는 대칭축까지 거리의 두 배예요.","1 × 2 = 2, 5 × 2 = 10, 6 × 2 = 12예요.","2 + 10 + 12 = 24(칸)이에요."]},{"stem":"대칭축에서 4칸, 4칸, 2칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["꼭짓점과 대응점 사이는 대칭축까지 거리의 두 배예요.","4 × 2 = 8, 4 × 2 = 8, 2 × 2 = 4예요.","8 + 8 + 4 = 20(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_challenge#5','math',5,2,'u3','L06','g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',3,'ox','auto','대칭축이 비스듬하면 가로 칸 수만 세어 대응점을 찍어요.',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":5,"concept":"M5-2-u3-C6","difficulty":3,"kind":"ox","stem":"대칭축이 비스듬하면 가로 칸 수만 세어 대응점을 찍어요.","answer":"X","reason_options":[{"t":"대칭축과 수직인 방향으로 같은 거리만큼 가야 하므로","correct":true},{"t":"모눈에서는 언제나 가로로만 세므로","mis":"M5-2-u3-X12"}],"mis":"M5-2-u3-X12","explanation":["대응점을 이은 선분은 대칭축과 수직이에요.","가로 칸만 세면 자리가 어긋나요.","틀린 말이에요."],"variant_rule":{"alt":[{"stem":"대칭축에서 2칸 떨어진 점의 대응점은 반대쪽으로 4칸 간 자리에 찍어요.","answer":"X","reason_options":[{"t":"대칭축에서 같은 거리인 2칸만큼 가야 하므로","correct":true},{"t":"두 배로 멀리 가야 겹치므로","mis":"M5-2-u3-X10"}],"explanation":["대칭축까지의 거리는 양쪽이 같아요.","반대쪽으로 2칸 가요 — 두 점 사이가 4칸이에요.","틀린 말이에요."]},{"stem":"세로 대칭축으로 대응점을 찍을 때 위아래 자리는 그대로예요.","answer":"O","reason_options":[{"t":"대칭축과 수직인 가로 방향으로만 움직이므로","correct":true},{"t":"대칭축만큼 아래로 내려가야 하므로","mis":"M5-2-u3-X12"}],"explanation":["세로 대칭축과 수직인 방향은 가로예요.","가로로만 가니 높이는 그대로예요.","맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_challenge#6','math',5,2,'u3','L06','g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',3,'sa','auto','대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 4 cm, 6 cm, 5 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C6","difficulty":3,"kind":"sa","stem":"대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 4 cm, 6 cm, 5 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 4 + 6 + 5 = 15(cm)예요.","둘레는 15 × 2 = 30(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 7 cm, 3 cm, 2 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 7 + 3 + 2 = 12(cm)예요.","둘레는 12 × 2 = 24(cm)예요."]},{"stem":"대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 6 cm, 6 cm, 3 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 6 + 6 + 3 = 15(cm)예요.","둘레는 15 × 2 = 30(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_challenge#7','math',5,2,'u3','L06','g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',3,'sa','auto','선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 9칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u3-C6","difficulty":3,"kind":"sa","stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 9칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["대응점은 반대쪽으로 9칸 간 자리예요.","꼭짓점에서 대칭축까지 9칸, 대칭축에서 대응점까지 9칸이에요.","9 + 9 = 18(칸)이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 7칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["대응점은 반대쪽으로 7칸 간 자리예요.","꼭짓점에서 대칭축까지 7칸, 대칭축에서 대응점까지 7칸이에요.","7 + 7 = 14(칸)이에요."]},{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 8칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대응점은 반대쪽으로 8칸 간 자리예요.","꼭짓점에서 대칭축까지 8칸, 대칭축에서 대응점까지 8칸이에요.","8 + 8 = 16(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_challenge#8','math',5,2,'u3','L06','g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',4,'mc','auto','모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":8,"concept":"M5-2-u3-C6","difficulty":4,"kind":"mc","stem":"모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄴ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄷ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":220,"h":220,"pts":{"ㄱ":[60,120,"nw"],"ㄴ":[180,120,"se"],"ㄷ":[120,60,"se"],"ㄹ":[140,40,"se"]},"seg":[[[20,20],[200,200]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄷ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄹ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":240,"h":240,"pts":{"ㄱ":[40,120,"nw"],"ㄴ":[140,20,"se"],"ㄷ":[200,120,"se"],"ㄹ":[120,40,"se"]},"seg":[[[20,20],[220,220]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄹ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄴ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":200,"h":200,"pts":{"ㄱ":[80,120,"nw"],"ㄴ":[120,80,"se"],"ㄷ":[140,60,"se"],"ㄹ":[160,120,"se"]},"seg":[[[20,20],[180,180]]],"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_challenge#9','math',5,2,'u3','L06','g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',4,'sa','auto','대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 3 cm, 2 cm, 4 cm, 1 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C6","difficulty":4,"kind":"sa","stem":"대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 3 cm, 2 cm, 4 cm, 1 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 3 + 2 + 4 + 1 = 10(cm)예요.","둘레는 10 × 2 = 20(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 5 cm, 2 cm, 2 cm, 3 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 5 + 2 + 2 + 3 = 12(cm)예요.","둘레는 12 × 2 = 24(cm)예요."]},{"stem":"대칭축 위에 꼭짓점 두 개를 두고 선대칭도형의 반쪽을 그렸더니 반쪽의 변이 4 cm, 4 cm, 1 cm, 2 cm였어요. 나머지 반쪽을 그려 완성한 도형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 4 + 4 + 1 + 2 = 11(cm)예요.","둘레는 11 × 2 = 22(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L06_challenge#10','math',5,2,'u3','L06','g5_2_math_u3_L06_challenge','lesson_challenge','M5-2-u3-C6',4,'essay','teacher','순달이가 모눈종이에 대칭축과 선대칭도형의 반쪽을 그려 두었어요. 나머지 반쪽을 그려 선대칭도형을 완성하는 방법을 차례대로 쓰고, 대칭축이 비스듬할 때 조심해야 할 점도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C6","difficulty":4,"kind":"essay","stem":"순달이가 모눈종이에 대칭축과 선대칭도형의 반쪽을 그려 두었어요. 나머지 반쪽을 그려 선대칭도형을 완성하는 방법을 차례대로 쓰고, 대칭축이 비스듬할 때 조심해야 할 점도 쓰세요.","answer_guide":{"answer":"예: ① 각 꼭짓점에서 대칭축까지의 거리(칸 수)를 잰다. ② 대칭축의 반대쪽으로 같은 거리만큼 떨어진 곳에 대응점을 찍는다. 대칭축 위에 있는 점은 그대로 둔다. ③ 찍은 점들을 원래 도형의 차례대로 잇고, 대칭축으로 접어 겹치는지 확인한다. 대칭축이 비스듬할 때는 가로 칸이나 세로 칸만 세면 안 되고, 대칭축과 수직인 방향으로 같은 거리만큼 가야 한다.","scoring_points":["거리 재기 → 대응점 찍기 → 잇기 차례로 썼는가","대칭축 위의 점은 그대로 둔다고 썼는가","비스듬할 때는 대칭축과 수직인 방향으로 간다고 썼는가"]},"explanation":["거리 재기 → 대응점 찍기 → 차례대로 잇기예요.","대칭축 위의 점은 제자리예요.","비스듬하면 대칭축과 수직인 방향으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_basic#1','math',5,2,'u3','L07','g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',1,'mc','auto','어떤 점을 중심으로 반 바퀴 돌렸을 때 완전히 겹치는 도형을 무엇이라고 하나요?',ARRAY['M5-2-u3-X15','M5-2-u3-X17','M5-2-u3-X02']::text[],true,'{"seq":1,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"어떤 점을 중심으로 반 바퀴 돌렸을 때 완전히 겹치는 도형을 무엇이라고 하나요?","options":[{"t":"점대칭도형","correct":true},{"t":"선대칭도형","mis":"M5-2-u3-X15"},{"t":"합동인 도형","mis":"M5-2-u3-X17"},{"t":"직각사다리꼴","mis":"M5-2-u3-X02"}],"explanation":["한 점을 중심으로 반 바퀴(180°) 돌렸을 때 완전히 겹치는 도형을 점대칭도형이라고 해요.","그 점을 대칭의 중심이라고 해요.","접기는 선대칭, 돌리기는 점대칭이에요 — 한 바퀴 돌리면 어떤 도형이든 제자리예요."],"variant_rule":{"alt":[{"stem":"점대칭도형을 반 바퀴 돌릴 때 중심이 되는 점을 무엇이라고 하나요?","options":[{"t":"대칭의 중심","correct":true},{"t":"대칭축","mis":"M5-2-u3-X15"},{"t":"대응점","mis":"M5-2-u3-X17"},{"t":"꼭짓점","mis":"M5-2-u3-X14"}],"explanation":["한 점을 중심으로 반 바퀴(180°) 돌렸을 때 완전히 겹치는 도형을 점대칭도형이라고 해요.","그 점을 대칭의 중심이라고 해요.","접기는 선대칭, 돌리기는 점대칭이에요 — 한 바퀴 돌리면 어떤 도형이든 제자리예요."]},{"stem":"어떤 도형이 점대칭도형인지 알아보는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 점을 중심으로 반 바퀴 돌려 완전히 겹치는지 본다","correct":true},{"t":"한 직선을 따라 접어 겹치는지 본다","mis":"M5-2-u3-X15"},{"t":"가운데에 점을 찍을 수 있는지 본다","mis":"M5-2-u3-X14"},{"t":"한 바퀴 돌려 겹치는지 본다","mis":"M5-2-u3-X14"}],"explanation":["한 점을 중심으로 반 바퀴(180°) 돌렸을 때 완전히 겹치는 도형을 점대칭도형이라고 해요.","그 점을 대칭의 중심이라고 해요.","접기는 선대칭, 돌리기는 점대칭이에요 — 한 바퀴 돌리면 어떤 도형이든 제자리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_basic#2','math',5,2,'u3','L07','g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',1,'mc','auto','점대칭도형인 평행사변형에서 대칭의 중심은 몇 개인가요?',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":2,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"점대칭도형인 평행사변형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."],"variant_rule":{"alt":[{"stem":"점대칭도형인 직사각형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]},{"stem":"점대칭도형인 마름모에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_basic#3','math',5,2,'u3','L07','g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',1,'mc','auto','이등변삼각형 한가운데에 점을 찍었어요. 알맞은 설명은 어느 것인가요?',ARRAY['M5-2-u3-X14','M5-2-u3-X15','M5-2-u3-X08']::text[],true,'{"seq":3,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"이등변삼각형 한가운데에 점을 찍었어요. 알맞은 설명은 어느 것인가요?","options":[{"t":"반 바퀴 돌리면 어긋나므로 점대칭도형이 아니다","correct":true},{"t":"점이 있으니 점대칭도형이다","mis":"M5-2-u3-X14"},{"t":"대칭의 중심이 두 개다","mis":"M5-2-u3-X15"},{"t":"접어도 겹치지 않는다","mis":"M5-2-u3-X08"}],"explanation":["점대칭도형은 반 바퀴 돌려 완전히 겹치는 도형이에요.","가운데에 점을 찍는 것과 돌려서 겹치는 것은 다른 일이에요.","판단의 기준은 점이 있는지가 아니라 겹치는지예요."],"variant_rule":{"alt":[{"stem":"정삼각형 한가운데에 점을 찍고 반 바퀴 돌렸어요. 알맞은 설명은 어느 것인가요?","options":[{"t":"꼭짓점이 아래로 가서 겹치지 않으므로 점대칭도형이 아니다","correct":true},{"t":"가운데에 점이 있으니 점대칭도형이다","mis":"M5-2-u3-X14"},{"t":"세 변이 같으니 점대칭도형이다","mis":"M5-2-u3-X14"},{"t":"대칭축이 없다","mis":"M5-2-u3-X08"}],"explanation":["점대칭도형은 반 바퀴 돌려 완전히 겹치는 도형이에요.","가운데에 점을 찍는 것과 돌려서 겹치는 것은 다른 일이에요.","판단의 기준은 점이 있는지가 아니라 겹치는지예요."]},{"stem":"현주는 「가운데에 점이 있으니 점대칭도형」이라고 적었어요. 이 판단이 잘못된 까닭은 어느 것인가요?","options":[{"t":"반 바퀴 돌려 겹치는지 확인하지 않았기 때문에","correct":true},{"t":"점이 두 개여야 하기 때문에","mis":"M5-2-u3-X15"},{"t":"점이 도형 밖에 있어야 하기 때문에","mis":"M5-2-u3-X14"},{"t":"대칭축이 없기 때문에","mis":"M5-2-u3-X15"}],"explanation":["점대칭도형은 반 바퀴 돌려 완전히 겹치는 도형이에요.","가운데에 점을 찍는 것과 돌려서 겹치는 것은 다른 일이에요.","판단의 기준은 점이 있는지가 아니라 겹치는지예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_basic#4','math',5,2,'u3','L07','g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',1,'mc','auto','점대칭도형인지 알아보려면 대칭의 중심을 중심으로 얼마만큼 돌려야 하나요?',ARRAY['M5-2-u3-X14']::text[],true,'{"seq":4,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"점대칭도형인지 알아보려면 대칭의 중심을 중심으로 얼마만큼 돌려야 하나요?","options":[{"t":"반 바퀴(180°)","correct":true},{"t":"한 바퀴(360°)","mis":"M5-2-u3-X14"},{"t":"직각만큼(90°)","mis":"M5-2-u3-X14"},{"t":"조금만 돌려도 된다","mis":"M5-2-u3-X14"}],"explanation":["점대칭도형은 반 바퀴(180°) 돌려 완전히 겹치는 도형이에요.","한 바퀴는 어떤 도형이든 제자리라 가를 수 없어요.","직각만큼만 돌리면 평행사변형처럼 점대칭도형도 겹치지 않아요."],"variant_rule":{"alt":[{"stem":"한 바퀴 돌리면 제자리로 돌아오는데 점대칭도형을 「반 바퀴」로 정하는 까닭은 어느 것인가요?","options":[{"t":"한 바퀴 돌리면 어떤 도형이든 겹쳐 가를 수 없기 때문에","correct":true},{"t":"반 바퀴가 더 빨라서","mis":"M5-2-u3-X14"},{"t":"반 바퀴 돌리면 도형이 작아져서","mis":"M5-2-u3-X01"},{"t":"한 바퀴 돌리면 크기가 바뀌어서","mis":"M5-2-u3-X01"}],"explanation":["점대칭도형은 반 바퀴(180°) 돌려 완전히 겹치는 도형이에요.","한 바퀴는 어떤 도형이든 제자리라 가를 수 없어요.","직각만큼만 돌리면 평행사변형처럼 점대칭도형도 겹치지 않아요."]},{"stem":"평행사변형을 대칭의 중심으로 직각만큼(90°)만 돌렸더니 겹치지 않았어요. 알맞은 설명은 어느 것인가요?","options":[{"t":"반 바퀴 돌려 보아야 점대칭도형인지 알 수 있다","correct":true},{"t":"그래서 점대칭도형이 아니다","mis":"M5-2-u3-X14"},{"t":"대칭의 중심이 잘못되었다","mis":"M5-2-u3-X15"},{"t":"평행사변형은 선대칭도형이다","mis":"M5-2-u3-X15"}],"explanation":["점대칭도형은 반 바퀴(180°) 돌려 완전히 겹치는 도형이에요.","한 바퀴는 어떤 도형이든 제자리라 가를 수 없어요.","직각만큼만 돌리면 평행사변형처럼 점대칭도형도 겹치지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_basic#5','math',5,2,'u3','L07','g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',2,'mc','auto','점대칭도형은 어느 것인가요?',ARRAY['M5-2-u3-X14']::text[],true,'{"seq":5,"concept":"M5-2-u3-C7","difficulty":2,"kind":"mc","stem":"점대칭도형은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-2-u3-X14"},{"t":"㉰","mis":"M5-2-u3-X14"},{"t":"㉱","mis":"M5-2-u3-X14"}],"explanation":["㉯는 평행사변형이에요","평행사변형은 반 바퀴 돌리면 완전히 겹쳐요.","나머지는 반 바퀴 돌리면 어긋나요."],"asset":{"type":"geo","items":[{"w":80,"h":80,"poly":[[[0,80],[40,0],[80,80]]]},{"w":110.0,"h":60,"poly":[[[30.0,0],[110.0,0],[80,60],[0,60]]]},{"w":100,"h":60,"poly":[[[0,0],[60,0],[100,60],[0,60]]]},{"w":80,"h":69.2,"poly":[[[0,69.2],[40,0],[80,69.2]]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 점대칭도형은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M5-2-u3-X14"},{"t":"㉯","mis":"M5-2-u3-X14"},{"t":"㉰","mis":"M5-2-u3-X14"}],"explanation":["㉱는 직사각형이에요","직사각형은 반 바퀴 돌리면 완전히 겹쳐요.","나머지는 반 바퀴 돌리면 어긋나요."],"asset":{"type":"geo","items":[{"w":100,"h":60,"poly":[[[0,0],[60,0],[100,60],[0,60]]]},{"w":80,"h":69.2,"poly":[[[0,69.2],[40,0],[80,69.2]]]},{"w":100,"h":60,"poly":[[[0,60],[100,60],[20,0]]]},{"w":100,"h":60,"poly":[[[0,0],[100,0],[100,60],[0,60]]]}]}},{"stem":"이번에는 다른 보기예요. 점대칭도형은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M5-2-u3-X14"},{"t":"㉰","mis":"M5-2-u3-X14"},{"t":"㉱","mis":"M5-2-u3-X14"}],"explanation":["㉮는 정사각형이에요","정사각형은 반 바퀴 돌리면 완전히 겹쳐요.","나머지는 반 바퀴 돌리면 어긋나요."],"asset":{"type":"geo","items":[{"w":80,"h":80,"poly":[[[0,0],[80,0],[80,80],[0,80]]]},{"w":80,"h":80,"poly":[[[0,80],[40,0],[80,80]]]},{"w":40,"h":40,"poly":[[[0,0],[40,0],[40,40],[20,40],[20,20],[0,20]]]},{"w":100,"h":60,"poly":[[[0,0],[60,0],[100,60],[0,60]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_basic#6','math',5,2,'u3','L07','g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',2,'sa','auto','평행사변형, 직사각형, 이등변삼각형, 직각사다리꼴 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C7","difficulty":2,"kind":"sa","stem":"평행사변형, 직사각형, 이등변삼각형, 직각사다리꼴 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","평행사변형 ○, 직사각형 ○, 이등변삼각형 ×, 직각사다리꼴 ×예요.","점대칭도형은 2개예요."],"mis":"M5-2-u3-X14","variant_rule":{"alt":[{"stem":"평행사변형, 직사각형, 정사각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","평행사변형 ○, 직사각형 ○, 정사각형 ○예요.","점대칭도형은 3개예요."]},{"stem":"정삼각형, 마름모, 직각사다리꼴, 정육각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","정삼각형 ×, 마름모 ○, 직각사다리꼴 ×, 정육각형 ○예요.","점대칭도형은 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_basic#7','math',5,2,'u3','L07','g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',2,'mc','auto','접어도 겹치고 반 바퀴 돌려도 겹치는 도형은 어느 것인가요?',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":7,"concept":"M5-2-u3-C7","difficulty":2,"kind":"mc","stem":"접어도 겹치고 반 바퀴 돌려도 겹치는 도형은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"평행사변형","mis":"M5-2-u3-X15"},{"t":"이등변삼각형","mis":"M5-2-u3-X15"},{"t":"직각사다리꼴","mis":"M5-2-u3-X15"}],"explanation":["직사각형은 접어도 겹치고(선대칭도형) 돌려도 겹쳐요(점대칭도형).","평행사변형은 돌리기만 돼요, 이등변삼각형은 접기만 돼요, 직각사다리꼴은 둘 다 안 돼요.","그래서 답은 직사각형이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 접어도 겹치고 반 바퀴 돌려도 겹치는 도형은 어느 것인가요?","options":[{"t":"정사각형","correct":true},{"t":"정삼각형","mis":"M5-2-u3-X15"},{"t":"평행사변형","mis":"M5-2-u3-X15"},{"t":"ㄱ자 모양","mis":"M5-2-u3-X15"}],"explanation":["정사각형은 접어도 겹치고(선대칭도형) 돌려도 겹쳐요(점대칭도형).","정삼각형은 접기만 돼요, 평행사변형은 돌리기만 돼요, ㄱ자 모양은 접기만 돼요.","그래서 답은 정사각형이에요."]},{"stem":"이번에는 다른 보기예요. 접어도 겹치고 반 바퀴 돌려도 겹치는 도형은 어느 것인가요?","options":[{"t":"마름모","correct":true},{"t":"이등변삼각형","mis":"M5-2-u3-X15"},{"t":"직각사다리꼴","mis":"M5-2-u3-X15"},{"t":"평행사변형","mis":"M5-2-u3-X15"}],"explanation":["마름모는 접어도 겹치고(선대칭도형) 돌려도 겹쳐요(점대칭도형).","이등변삼각형은 접기만 돼요, 직각사다리꼴은 둘 다 안 돼요, 평행사변형은 돌리기만 돼요.","그래서 답은 마름모예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_basic#8','math',5,2,'u3','L07','g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',2,'ox','auto','가운데에 점을 찍을 수 있는 도형은 모두 점대칭도형이에요.',ARRAY['M5-2-u3-X14']::text[],true,'{"seq":8,"concept":"M5-2-u3-C7","difficulty":2,"kind":"ox","stem":"가운데에 점을 찍을 수 있는 도형은 모두 점대칭도형이에요.","answer":"X","reason_options":[{"t":"그 점을 중심으로 반 바퀴 돌려 겹쳐야 점대칭도형이므로","correct":true},{"t":"가운데 점이 곧 대칭의 중심이므로","mis":"M5-2-u3-X14"}],"mis":"M5-2-u3-X14","explanation":["이등변삼각형 가운데에도 점을 찍을 수 있어요.","하지만 반 바퀴 돌리면 거꾸로 서서 어긋나요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"평행사변형은 점대칭도형이에요.","answer":"O","reason_options":[{"t":"두 대각선이 만나는 점을 중심으로 반 바퀴 돌리면 완전히 겹치므로","correct":true},{"t":"세로로 접으면 겹치므로","mis":"M5-2-u3-X15"}],"explanation":["평행사변형은 접어서는 겹치지 않아요.","반 바퀴 돌리면 완전히 겹쳐요.","그래서 맞는 말이에요."]},{"stem":"점대칭도형의 대칭의 중심은 두 개 이상일 수 있어요.","answer":"X","reason_options":[{"t":"반 바퀴 돌릴 때 붙잡는 점은 하나뿐이므로","correct":true},{"t":"대칭축처럼 여러 개일 수 있으므로","mis":"M5-2-u3-X15"}],"explanation":["대칭축은 여러 개일 수 있지만 대칭의 중심은 아니에요.","대칭의 중심은 언제나 1개예요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_basic#9','math',5,2,'u3','L07','g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',2,'mc','auto','접으면 겹치지 않는데 반 바퀴 돌리면 겹치는 도형은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X14']::text[],true,'{"seq":9,"concept":"M5-2-u3-C7","difficulty":2,"kind":"mc","stem":"접으면 겹치지 않는데 반 바퀴 돌리면 겹치는 도형은 어느 것인가요?","options":[{"t":"평행사변형","correct":true},{"t":"이등변삼각형","mis":"M5-2-u3-X15"},{"t":"직사각형","mis":"M5-2-u3-X15"},{"t":"직각사다리꼴","mis":"M5-2-u3-X14"}],"explanation":["평행사변형은 어느 직선으로 접어도 겹치지 않아 선대칭도형이 아니에요.","두 대각선이 만나는 점을 중심으로 반 바퀴 돌리면 완전히 겹쳐요.","그래서 점대칭도형이에요."],"variant_rule":{"alt":[{"stem":"여울이가 어떤 사각형을 세로로도 가로로도 접어 보았지만 겹치지 않았어요. 그런데 가운데를 콕 집고 반 바퀴 돌렸더니 딱 맞게 겹쳤어요. 이 사각형은 어느 것인가요?","options":[{"t":"평행사변형","correct":true},{"t":"정사각형","mis":"M5-2-u3-X15"},{"t":"직각사다리꼴","mis":"M5-2-u3-X14"},{"t":"직사각형","mis":"M5-2-u3-X15"}],"explanation":["평행사변형은 어느 직선으로 접어도 겹치지 않아 선대칭도형이 아니에요.","두 대각선이 만나는 점을 중심으로 반 바퀴 돌리면 완전히 겹쳐요.","그래서 점대칭도형이에요."]},{"stem":"선대칭도형이 아니면서 점대칭도형인 것은 어느 것인가요?","options":[{"t":"평행사변형","correct":true},{"t":"마름모","mis":"M5-2-u3-X15"},{"t":"정삼각형","mis":"M5-2-u3-X15"},{"t":"직각사다리꼴","mis":"M5-2-u3-X14"}],"explanation":["평행사변형은 어느 직선으로 접어도 겹치지 않아 선대칭도형이 아니에요.","두 대각선이 만나는 점을 중심으로 반 바퀴 돌리면 완전히 겹쳐요.","그래서 점대칭도형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_basic#10','math',5,2,'u3','L07','g5_2_math_u3_L07_basic','lesson_basic','M5-2-u3-C7',3,'sa','auto','정사각형의 대칭축의 개수와 대칭의 중심의 개수를 더하면 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u3-C7","difficulty":3,"kind":"sa","stem":"정사각형의 대칭축의 개수와 대칭의 중심의 개수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["정사각형의 대칭축은 4개예요.","점대칭도형의 대칭의 중심은 언제나 1개예요.","4 + 1 = 5(개)예요."],"mis":"M5-2-u3-X15","variant_rule":{"alt":[{"stem":"직사각형의 대칭축의 개수와 대칭의 중심의 개수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["직사각형의 대칭축은 2개예요.","점대칭도형의 대칭의 중심은 언제나 1개예요.","2 + 1 = 3(개)예요."]},{"stem":"마름모의 대칭축의 개수와 대칭의 중심의 개수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["마름모의 대칭축은 2개예요.","점대칭도형의 대칭의 중심은 언제나 1개예요.","2 + 1 = 3(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
