INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_challenge#2','math',5,2,'u3','L07','g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',2,'mc','auto','점대칭도형인 정사각형에서 대칭의 중심은 몇 개인가요?',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":2,"concept":"M5-2-u3-C7","difficulty":2,"kind":"mc","stem":"점대칭도형인 정사각형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."],"variant_rule":{"alt":[{"stem":"점대칭도형인 정육각형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]},{"stem":"점대칭도형인 십자 모양에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_challenge#3','math',5,2,'u3','L07','g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',3,'mc','auto','알파벳 대문자(굵은 고딕체)를 도형으로 볼 때 접으면 겹치지 않지만 반 바퀴 돌리면 겹치는 것은 어느 것인가요?',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":3,"concept":"M5-2-u3-C7","difficulty":3,"kind":"mc","stem":"알파벳 대문자(굵은 고딕체)를 도형으로 볼 때 접으면 겹치지 않지만 반 바퀴 돌리면 겹치는 것은 어느 것인가요?","options":[{"t":"N","correct":true},{"t":"A","mis":"M5-2-u3-X15"},{"t":"T","mis":"M5-2-u3-X15"},{"t":"M","mis":"M5-2-u3-X15"}],"explanation":["N은 어느 직선으로 접어도 겹치지 않아요.","그런데 한가운데를 중심으로 반 바퀴 돌리면 완전히 겹쳐요 — 점대칭도형이에요.","A, T, M은 접으면 겹치지만 돌리면 거꾸로 서요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알파벳 대문자(굵은 고딕체)를 도형으로 볼 때 접으면 겹치지 않지만 반 바퀴 돌리면 겹치는 것은 어느 것인가요?","options":[{"t":"S","correct":true},{"t":"T","mis":"M5-2-u3-X15"},{"t":"M","mis":"M5-2-u3-X15"},{"t":"A","mis":"M5-2-u3-X15"}],"explanation":["S는 어느 직선으로 접어도 겹치지 않아요.","그런데 한가운데를 중심으로 반 바퀴 돌리면 완전히 겹쳐요 — 점대칭도형이에요.","T, M, A는 접으면 겹치지만 돌리면 거꾸로 서요."]},{"stem":"이번에는 다른 보기예요. 알파벳 대문자(굵은 고딕체)를 도형으로 볼 때 접으면 겹치지 않지만 반 바퀴 돌리면 겹치는 것은 어느 것인가요?","options":[{"t":"Z","correct":true},{"t":"M","mis":"M5-2-u3-X15"},{"t":"A","mis":"M5-2-u3-X15"},{"t":"T","mis":"M5-2-u3-X15"}],"explanation":["Z는 어느 직선으로 접어도 겹치지 않아요.","그런데 한가운데를 중심으로 반 바퀴 돌리면 완전히 겹쳐요 — 점대칭도형이에요.","M, A, T는 접으면 겹치지만 돌리면 거꾸로 서요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_challenge#4','math',5,2,'u3','L07','g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',3,'sa','auto','정육각형, 정오각형, 십자 모양, ㄱ자 모양, 평행사변형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C7","difficulty":3,"kind":"sa","stem":"정육각형, 정오각형, 십자 모양, ㄱ자 모양, 평행사변형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","정육각형 ○, 정오각형 ×, 십자 모양 ○, ㄱ자 모양 ×, 평행사변형 ○예요.","점대칭도형은 3개예요."],"mis":"M5-2-u3-X14","variant_rule":{"alt":[{"stem":"정삼각형, 정사각형, 정오각형, 정육각형, 마름모 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","정삼각형 ×, 정사각형 ○, 정오각형 ×, 정육각형 ○, 마름모 ○예요.","점대칭도형은 3개예요."]},{"stem":"이등변삼각형, 직사각형, ㄱ자 모양, 십자 모양, 직각사다리꼴 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","이등변삼각형 ×, 직사각형 ○, ㄱ자 모양 ×, 십자 모양 ○, 직각사다리꼴 ×예요.","점대칭도형은 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_challenge#5','math',5,2,'u3','L07','g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',3,'ox','auto','직사각형은 선대칭도형이면서 점대칭도형이에요.',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":5,"concept":"M5-2-u3-C7","difficulty":3,"kind":"ox","stem":"직사각형은 선대칭도형이면서 점대칭도형이에요.","answer":"O","reason_options":[{"t":"접어도 겹치고 반 바퀴 돌려도 겹치므로","correct":true},{"t":"두 가지가 함께 될 수는 없으므로","mis":"M5-2-u3-X15"}],"mis":"M5-2-u3-X15","explanation":["직사각형은 세로·가로로 접으면 겹쳐요.","가운데를 중심으로 반 바퀴 돌려도 겹쳐요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"정삼각형은 점대칭도형이에요.","answer":"X","reason_options":[{"t":"반 바퀴 돌리면 꼭짓점이 아래로 가서 겹치지 않으므로","correct":true},{"t":"세 변이 같으면 돌려도 겹치므로","mis":"M5-2-u3-X14"}],"explanation":["정삼각형은 대칭축이 3개인 선대칭도형이에요.","그런데 반 바퀴 돌리면 거꾸로 서요.","그래서 틀린 말이에요."]},{"stem":"접어 보기만 하면 점대칭도형인지도 알 수 있어요.","answer":"X","reason_options":[{"t":"평행사변형처럼 접으면 안 겹치지만 돌리면 겹치는 도형이 있으므로","correct":true},{"t":"접어서 겹치면 돌려도 늘 겹치므로","mis":"M5-2-u3-X15"}],"explanation":["평행사변형은 접으면 안 겹치는데 돌리면 겹쳐요.","이등변삼각형은 접으면 겹치는데 돌리면 안 겹쳐요.","접어도 보고 돌려도 보아야 해요 — 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_challenge#6','math',5,2,'u3','L07','g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',3,'mc','auto','접어도 겹치고 반 바퀴 돌려도 겹치는 도형은 어느 것인가요?',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":6,"concept":"M5-2-u3-C7","difficulty":3,"kind":"mc","stem":"접어도 겹치고 반 바퀴 돌려도 겹치는 도형은 어느 것인가요?","options":[{"t":"정육각형","correct":true},{"t":"정오각형","mis":"M5-2-u3-X15"},{"t":"평행사변형","mis":"M5-2-u3-X15"},{"t":"정삼각형","mis":"M5-2-u3-X15"}],"explanation":["정육각형은 접어도 겹치고(선대칭도형) 돌려도 겹쳐요(점대칭도형).","정오각형은 접기만 돼요, 평행사변형은 돌리기만 돼요, 정삼각형은 접기만 돼요.","그래서 답은 정육각형이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 접어도 겹치고 반 바퀴 돌려도 겹치는 도형은 어느 것인가요?","options":[{"t":"십자 모양","correct":true},{"t":"ㄱ자 모양","mis":"M5-2-u3-X15"},{"t":"평행사변형","mis":"M5-2-u3-X15"},{"t":"이등변삼각형","mis":"M5-2-u3-X15"}],"explanation":["십자 모양은 접어도 겹치고(선대칭도형) 돌려도 겹쳐요(점대칭도형).","ㄱ자 모양은 접기만 돼요, 평행사변형은 돌리기만 돼요, 이등변삼각형은 접기만 돼요.","그래서 답은 십자 모양이에요."]},{"stem":"이번에는 다른 보기예요. 접어도 겹치고 반 바퀴 돌려도 겹치는 도형은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"평행사변형","mis":"M5-2-u3-X15"},{"t":"정오각형","mis":"M5-2-u3-X15"},{"t":"ㄱ자 모양","mis":"M5-2-u3-X15"}],"explanation":["직사각형은 접어도 겹치고(선대칭도형) 돌려도 겹쳐요(점대칭도형).","평행사변형은 돌리기만 돼요, 정오각형은 접기만 돼요, ㄱ자 모양은 접기만 돼요.","그래서 답은 직사각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_challenge#7','math',5,2,'u3','L07','g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',3,'sa','auto','평행사변형, 마름모, 정오각형, 이등변삼각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u3-C7","difficulty":3,"kind":"sa","stem":"평행사변형, 마름모, 정오각형, 이등변삼각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","평행사변형 ○, 마름모 ○, 정오각형 ×, 이등변삼각형 ×예요.","점대칭도형은 2개예요."],"mis":"M5-2-u3-X14","variant_rule":{"alt":[{"stem":"직각사다리꼴, 정육각형, 평행사변형, 정삼각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","직각사다리꼴 ×, 정육각형 ○, 평행사변형 ○, 정삼각형 ×예요.","점대칭도형은 2개예요."]},{"stem":"십자 모양, 정사각형, 세 변의 길이가 모두 다른 삼각형, 정오각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","십자 모양 ○, 정사각형 ○, 세 변의 길이가 모두 다른 삼각형 ×, 정오각형 ×예요.","점대칭도형은 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_challenge#8','math',5,2,'u3','L07','g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',4,'sa','auto','정육각형의 대칭축의 개수와 대칭의 중심의 개수를 더하면 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C7","difficulty":4,"kind":"sa","stem":"정육각형의 대칭축의 개수와 대칭의 중심의 개수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정육각형의 대칭축은 6개예요.","점대칭도형의 대칭의 중심은 언제나 1개예요.","6 + 1 = 7(개)예요."],"mis":"M5-2-u3-X15","variant_rule":{"alt":[{"stem":"십자 모양의 대칭축의 개수와 대칭의 중심의 개수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["십자 모양의 대칭축은 4개예요.","점대칭도형의 대칭의 중심은 언제나 1개예요.","4 + 1 = 5(개)예요."]},{"stem":"평행사변형의 대칭축의 개수와 대칭의 중심의 개수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["평행사변형의 대칭축은 0개예요.","점대칭도형의 대칭의 중심은 언제나 1개예요.","0 + 1 = 1(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_challenge#9','math',5,2,'u3','L07','g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',4,'sa','auto','정사각형, 직사각형, 마름모, 평행사변형, 정육각형, 정오각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C7","difficulty":4,"kind":"sa","stem":"정사각형, 직사각형, 마름모, 평행사변형, 정육각형, 정오각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","정사각형 ○, 직사각형 ○, 마름모 ○, 평행사변형 ○, 정육각형 ○, 정오각형 ×예요.","점대칭도형은 5개예요."],"mis":"M5-2-u3-X14","variant_rule":{"alt":[{"stem":"정삼각형, 이등변삼각형, ㄱ자 모양, 십자 모양, 직각사다리꼴, 마름모 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","정삼각형 ×, 이등변삼각형 ×, ㄱ자 모양 ×, 십자 모양 ○, 직각사다리꼴 ×, 마름모 ○예요.","점대칭도형은 2개예요."]},{"stem":"정육각형, 정오각형, 평행사변형, 세 변의 길이가 모두 다른 삼각형, 직사각형, 정삼각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","정육각형 ○, 정오각형 ×, 평행사변형 ○, 세 변의 길이가 모두 다른 삼각형 ×, 직사각형 ○, 정삼각형 ×예요.","점대칭도형은 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L07_challenge#10','math',5,2,'u3','L07','g5_2_math_u3_L07_challenge','lesson_challenge','M5-2-u3-C7',4,'essay','teacher','평행사변형과 이등변삼각형을 각각 접어 보고 돌려 보았어요. 두 도형이 선대칭도형인지, 점대칭도형인지 각각 쓰고, 도형을 가를 때 접어도 보고 돌려도 보아야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C7","difficulty":4,"kind":"essay","stem":"평행사변형과 이등변삼각형을 각각 접어 보고 돌려 보았어요. 두 도형이 선대칭도형인지, 점대칭도형인지 각각 쓰고, 도형을 가를 때 접어도 보고 돌려도 보아야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 평행사변형은 어느 직선으로 접어도 겹치지 않아 선대칭도형이 아니지만, 대각선이 만나는 점을 중심으로 반 바퀴 돌리면 겹쳐 점대칭도형이다. 이등변삼각형은 꼭짓점에서 밑변 가운데로 내린 선으로 접으면 겹쳐 선대칭도형이지만, 반 바퀴 돌리면 거꾸로 서 점대칭도형이 아니다. 접어 보기만 하면 평행사변형을 놓치고, 돌려 보기만 하면 이등변삼각형을 놓치므로 두 가지를 모두 해 보아야 한다.","scoring_points":["평행사변형 — 점대칭(선대칭 아님)이라고 썼는가","이등변삼각형 — 선대칭(점대칭 아님)이라고 썼는가","한 가지만 하면 놓치는 도형이 있다고 썼는가"]},"explanation":["평행사변형은 점대칭도형만이에요.","이등변삼각형은 선대칭도형만이에요.","접기·돌리기를 모두 해야 놓치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_basic#1','math',5,2,'u3','L08','g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',1,'sa','auto','점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 4 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C8","difficulty":1,"kind":"sa","stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 4 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 4 cm예요.","4 + 4 = 8(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 6 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 6 cm예요.","6 + 6 = 12(cm)예요."]},{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 3 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 3 cm예요.","3 + 3 = 6(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_basic#2','math',5,2,'u3','L08','g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',1,'sa','auto','점대칭도형에서 이웃한 두 변의 길이가 4 cm, 3 cm예요. 그 두 변의 대응변 두 개의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C8","difficulty":1,"kind":"sa","stem":"점대칭도형에서 이웃한 두 변의 길이가 4 cm, 3 cm예요. 그 두 변의 대응변 두 개의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["대응변의 길이는 같아요.","대응변도 4 cm, 3 cm예요.","4 + 3 = 7(cm)예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"점대칭도형에서 이웃한 두 변의 길이가 6 cm, 5 cm예요. 그 두 변의 대응변 두 개의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["대응변의 길이는 같아요.","대응변도 6 cm, 5 cm예요.","6 + 5 = 11(cm)예요."]},{"stem":"점대칭도형에서 이웃한 두 변의 길이가 2 cm, 8 cm예요. 그 두 변의 대응변 두 개의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["대응변의 길이는 같아요.","대응변도 2 cm, 8 cm예요.","2 + 8 = 10(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_basic#3','math',5,2,'u3','L08','g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',1,'sa','auto','점대칭도형에서 두 대응점 사이의 거리가 14 cm예요. 대칭의 중심에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u3-C8","difficulty":1,"kind":"sa","stem":"점대칭도형에서 두 대응점 사이의 거리가 14 cm예요. 대칭의 중심에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 한쪽은 전체의 반이에요.","14 ÷ 2 = 7(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"점대칭도형에서 두 대응점 사이의 거리가 10 cm예요. 대칭의 중심에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 한쪽은 전체의 반이에요.","10 ÷ 2 = 5(cm)예요."]},{"stem":"점대칭도형에서 두 대응점 사이의 거리가 18 cm예요. 대칭의 중심에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 한쪽은 전체의 반이에요.","18 ÷ 2 = 9(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_basic#4','math',5,2,'u3','L08','g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',1,'sa','auto','평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 변 ㄱㄴ이 6 cm일 때, 그 대응변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C8","difficulty":1,"kind":"sa","stem":"평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 변 ㄱㄴ이 6 cm일 때, 그 대응변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["점 ㄱ ↔ 점 ㄷ, 점 ㄴ ↔ 점 ㄹ이 대응점이에요.","그래서 변 ㄱㄴ의 대응변은 변 ㄷㄹ이에요.","대응변의 길이는 같으므로 6 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 변 ㄴㄷ이 4 cm일 때, 그 대응변은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["점 ㄴ ↔ 점 ㄹ, 점 ㄷ ↔ 점 ㄱ이 대응점이에요.","그래서 변 ㄴㄷ의 대응변은 변 ㄹㄱ이에요.","대응변의 길이는 같으므로 4 cm예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 변 ㄱㄴ이 5 cm일 때, 그 대응변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["점 ㄱ ↔ 점 ㄹ, 점 ㄴ ↔ 점 ㅁ이 대응점이에요.","그래서 변 ㄱㄴ의 대응변은 변 ㄹㅁ이에요.","대응변의 길이는 같으므로 5 cm예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
