INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_basic#7','math',5,2,'u3','L08','g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',2,'mc','auto','평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 각 ㄱ이 70°일 때 각 ㄷ은 몇 도인가요?',ARRAY['M5-2-u3-X07','M5-2-u3-X15','M5-2-u3-X10']::text[],true,'{"seq":7,"concept":"M5-2-u3-C8","difficulty":2,"kind":"mc","stem":"평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 각 ㄱ이 70°일 때 각 ㄷ은 몇 도인가요?","options":[{"t":"70°","correct":true},{"t":"110°","mis":"M5-2-u3-X07"},{"t":"290°","mis":"M5-2-u3-X15"},{"t":"35°","mis":"M5-2-u3-X10"}],"explanation":["점 ㄱ의 대응점은 점 ㄷ이에요.","그래서 각 ㄱ과 각 ㄷ은 대응각이에요.","대응각의 크기는 같으므로 70°예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 각 ㄴ이 110°일 때 각 ㄹ은 몇 도인가요?","options":[{"t":"110°","correct":true},{"t":"70°","mis":"M5-2-u3-X07"},{"t":"250°","mis":"M5-2-u3-X15"},{"t":"55°","mis":"M5-2-u3-X10"}],"explanation":["점 ㄴ의 대응점은 점 ㄹ이에요.","그래서 각 ㄴ과 각 ㄹ은 대응각이에요.","대응각의 크기는 같으므로 110°예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 각 ㄷ이 135°일 때 각 ㅂ은 몇 도인가요?","options":[{"t":"135°","correct":true},{"t":"45°","mis":"M5-2-u3-X07"},{"t":"225°","mis":"M5-2-u3-X15"},{"t":"67°","mis":"M5-2-u3-X10"}],"explanation":["점 ㄷ의 대응점은 점 ㅂ이에요.","그래서 각 ㄷ과 각 ㅂ은 대응각이에요.","대응각의 크기는 같으므로 135°예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_basic#8','math',5,2,'u3','L08','g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',2,'ox','auto','점대칭도형에서 대응점을 이은 선분은 모두 대칭의 중심을 지나요.',ARRAY['M5-2-u3-X13']::text[],true,'{"seq":8,"concept":"M5-2-u3-C8","difficulty":2,"kind":"ox","stem":"점대칭도형에서 대응점을 이은 선분은 모두 대칭의 중심을 지나요.","answer":"O","reason_options":[{"t":"반 바퀴 돌리면 모든 점이 중심 반대편으로 가므로","correct":true},{"t":"대응점을 이은 선분은 서로 만나지 않으므로","mis":"M5-2-u3-X13"}],"mis":"M5-2-u3-X13","explanation":["반 바퀴 돌리기는 한 점을 붙들고 도형을 돌리는 일이에요.","모든 점이 그 점 반대편으로 가요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"점대칭도형에서 대응각의 크기는 서로 같아요.","answer":"O","reason_options":[{"t":"반 바퀴 돌리면 완전히 겹치므로","correct":true},{"t":"돌리면 각이 반으로 줄어들므로","mis":"M5-2-u3-X07"}],"explanation":["대응각은 반 바퀴 돌렸을 때 겹치는 각이에요.","겹치려면 크기가 같아야 해요.","그래서 맞는 말이에요."]},{"stem":"점대칭도형에서 대응변의 길이는 서로 같아요.","answer":"O","reason_options":[{"t":"반 바퀴 돌리면 대응변이 완전히 겹치므로","correct":true},{"t":"대응변은 늘 반 길이이므로","mis":"M5-2-u3-X07"}],"explanation":["대응변은 돌렸을 때 겹치는 변이에요.","겹치려면 길이가 같아야 해요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_basic#9','math',5,2,'u3','L08','g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',2,'mc','auto','점대칭도형에서 대응점을 이은 선분과 대칭의 중심의 관계로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X13','M5-2-u3-X15']::text[],true,'{"seq":9,"concept":"M5-2-u3-C8","difficulty":2,"kind":"mc","stem":"점대칭도형에서 대응점을 이은 선분과 대칭의 중심의 관계로 알맞은 것은 어느 것인가요?","options":[{"t":"대칭의 중심이 선분을 이등분한다","correct":true},{"t":"대칭의 중심이 선분 밖에 있다","mis":"M5-2-u3-X13"},{"t":"선분과 대칭의 중심이 수직으로 만난다","mis":"M5-2-u3-X15"},{"t":"대칭의 중심이 선분의 끝에 있다","mis":"M5-2-u3-X13"}],"explanation":["점대칭도형에서 대응점을 이은 선분은 모두 대칭의 중심을 지나요.","대칭의 중심은 그 선분을 똑같이 둘로 나눠요(이등분).","수직으로 만나는 것은 선대칭도형의 대칭축이에요."],"variant_rule":{"alt":[{"stem":"점대칭도형에서 대응점을 이은 선분을 여러 개 그었어요. 알맞은 설명은 어느 것인가요?","options":[{"t":"모두 대칭의 중심 한 점에서 만난다","correct":true},{"t":"서로 만나지 않는다","mis":"M5-2-u3-X13"},{"t":"서로 수직으로 만난다","mis":"M5-2-u3-X15"},{"t":"길이가 모두 같다","mis":"M5-2-u3-X10"}],"explanation":["점대칭도형에서 대응점을 이은 선분은 모두 대칭의 중심을 지나요.","대칭의 중심은 그 선분을 똑같이 둘로 나눠요(이등분).","수직으로 만나는 것은 선대칭도형의 대칭축이에요."]},{"stem":"선대칭도형과 점대칭도형의 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"대칭축은 대응점을 이은 선분을 수직이등분하고, 대칭의 중심은 이등분만 한다","correct":true},{"t":"대칭축은 이등분만 하고, 대칭의 중심은 수직이등분한다","mis":"M5-2-u3-X15"},{"t":"점대칭도형은 대응변의 길이가 다르다","mis":"M5-2-u3-X07"},{"t":"선대칭도형에는 대응점이 없다","mis":"M5-2-u3-X15"}],"explanation":["점대칭도형에서 대응점을 이은 선분은 모두 대칭의 중심을 지나요.","대칭의 중심은 그 선분을 똑같이 둘로 나눠요(이등분).","수직으로 만나는 것은 선대칭도형의 대칭축이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_basic#10','math',5,2,'u3','L08','g5_2_math_u3_L08_basic','lesson_basic','M5-2-u3-C8',3,'sa','auto','평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄱㅇ이 5 cm일 때 선분 ㄱㄷ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u3-C8","difficulty":3,"kind":"sa","stem":"평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄱㅇ이 5 cm일 때 선분 ㄱㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["점 ㄱ과 점 ㄷ은 대응점이고 선분 ㄱㄷ은 점 ㅇ을 지나요.","점 ㅇ이 선분을 이등분해 선분 ㄷㅇ도 5 cm예요.","5 + 5 = 10(cm)예요."],"mis":"M5-2-u3-X10","asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[[[40,0],[100,80]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄴㅇ이 3 cm일 때 선분 ㄴㄹ은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["점 ㄴ과 점 ㄹ은 대응점이고 선분 ㄴㄹ은 점 ㅇ을 지나요.","점 ㅇ이 선분을 이등분해 선분 ㄹㅇ도 3 cm예요.","3 + 3 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[[[140,0],[0,80]]]}],"tag":false}},{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄷㅇ이 4 cm일 때 선분 ㄷㅂ은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["점 ㄷ과 점 ㅂ은 대응점이고 선분 ㄷㅂ은 점 ㅇ을 지나요.","점 ㅇ이 선분을 이등분해 선분 ㅂㅇ도 4 cm예요.","4 + 4 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[140,40],[0,40]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
