e"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_challenge#2','math',5,2,'u3','L08','g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',2,'mc','auto','평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄱㅇ과 길이가 같은 선분은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X10']::text[],true,'{"seq":2,"concept":"M5-2-u3-C8","difficulty":2,"kind":"mc","stem":"평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄱㅇ과 길이가 같은 선분은 어느 것인가요?","options":[{"t":"선분 ㄷㅇ","correct":true},{"t":"선분 ㄴㅇ","mis":"M5-2-u3-X06"},{"t":"선분 ㄹㅇ","mis":"M5-2-u3-X06"},{"t":"선분 ㄱㄷ","mis":"M5-2-u3-X10"}],"explanation":["점 ㄱ의 대응점은 점 ㄷ이에요.","대칭의 중심 ㅇ은 선분 ㄱㄷ을 이등분해요.","그래서 선분 ㄱㅇ과 선분 ㄷㅇ의 길이가 같아요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[[[40,0],[100,80]],[[140,0],[0,80]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄴㅇ과 길이가 같은 선분은 어느 것인가요?","options":[{"t":"선분 ㅁㅇ","correct":true},{"t":"선분 ㄱㅇ","mis":"M5-2-u3-X06"},{"t":"선분 ㄷㅇ","mis":"M5-2-u3-X06"},{"t":"선분 ㄴㅁ","mis":"M5-2-u3-X10"}],"explanation":["점 ㄴ의 대응점은 점 ㅁ이에요.","대칭의 중심 ㅇ은 선분 ㄴㅁ을 이등분해요.","그래서 선분 ㄴㅇ과 선분 ㅁㅇ의 길이가 같아요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[20,0],[120,80]],[[100,0],[40,80]],[[140,40],[0,40]]]}],"tag":false}},{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄷㅇ과 길이가 같은 선분은 어느 것인가요?","options":[{"t":"선분 ㅂㅇ","correct":true},{"t":"선분 ㄱㅇ","mis":"M5-2-u3-X06"},{"t":"선분 ㄴㅇ","mis":"M5-2-u3-X06"},{"t":"선분 ㄷㅂ","mis":"M5-2-u3-X10"}],"explanation":["점 ㄷ의 대응점은 점 ㅂ이에요.","대칭의 중심 ㅇ은 선분 ㄷㅂ을 이등분해요.","그래서 선분 ㄷㅇ과 선분 ㅂㅇ의 길이가 같아요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[20,0],[120,80]],[[100,0],[40,80]],[[140,40],[0,40]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_challenge#3','math',5,2,'u3','L08','g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',3,'error','auto','친구들이 점대칭도형의 성질에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13','M5-2-u3-X07']::text[],true,'{"seq":3,"concept":"M5-2-u3-C8","difficulty":3,"kind":"error","stem":"친구들이 점대칭도형의 성질에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「대칭의 중심은 대응점을 이은 선분과 수직으로 만나.」","correct":true,"mis_target":"M5-2-u3-X15"},{"t":"도윤 — 「대응점을 이은 선분은 모두 중심을 지나.」","mis":"M5-2-u3-X13"},{"t":"하린 — 「대응변의 길이는 같아.」","mis":"M5-2-u3-X07"}],"explanation":["점대칭도형에서 대응점을 이은 선분은 모두 대칭의 중심을 지나요.","대칭의 중심은 그 선분을 이등분만 하고(수직 아님), 대응변·대응각은 같아요.","수아의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 점대칭도형의 성질에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「중심에서 대응점까지 7 cm니까 대응점 사이도 7 cm야.」","correct":true,"mis_target":"M5-2-u3-X10"},{"t":"서연 — 「대칭의 중심은 선분을 이등분해.」","mis":"M5-2-u3-X10"},{"t":"지호 — 「대응각의 크기는 같아.」","mis":"M5-2-u3-X07"}],"explanation":["점대칭도형에서 대응점을 이은 선분은 모두 대칭의 중심을 지나요.","대칭의 중심은 그 선분을 이등분만 하고(수직 아님), 대응변·대응각은 같아요.","민준의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 점대칭도형의 성질에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「대응점은 가장 가까운 꼭짓점이야.」","correct":true,"mis_target":"M5-2-u3-X06"},{"t":"나린 — 「대응점은 중심을 지나 반대편에 있어.」","mis":"M5-2-u3-X13"},{"t":"유진 — 「대칭의 중심은 하나뿐이야.」","mis":"M5-2-u3-X15"}],"explanation":["점대칭도형에서 대응점을 이은 선분은 모두 대칭의 중심을 지나요.","대칭의 중심은 그 선분을 이등분만 하고(수직 아님), 대응변·대응각은 같아요.","가온의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_challenge#4','math',5,2,'u3','L08','g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',3,'sa','auto','점 ㅇ을 대칭의 중심으로 하는 점대칭도형인 평행사변형 ㄱㄴㄷㄹ에서 변 ㄱㄴ이 7 cm, 변 ㄴㄷ이 4 cm예요. 평행사변형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C8","difficulty":3,"kind":"sa","stem":"점 ㅇ을 대칭의 중심으로 하는 점대칭도형인 평행사변형 ㄱㄴㄷㄹ에서 변 ㄱㄴ이 7 cm, 변 ㄴㄷ이 4 cm예요. 평행사변형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["변 ㄱㄴ의 대응변은 변 ㄷㄹ, 변 ㄴㄷ의 대응변은 변 ㄹㄱ이에요.","대응변의 길이는 같아요.","7 + 4 + 7 + 4 = 22(cm)예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㅇ을 대칭의 중심으로 하는 점대칭도형인 평행사변형 ㄱㄴㄷㄹ에서 변 ㄱㄴ이 9 cm, 변 ㄴㄷ이 5 cm예요. 평행사변형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["변 ㄱㄴ의 대응변은 변 ㄷㄹ, 변 ㄴㄷ의 대응변은 변 ㄹㄱ이에요.","대응변의 길이는 같아요.","9 + 5 + 9 + 5 = 28(cm)예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"점 ㅇ을 대칭의 중심으로 하는 점대칭도형인 평행사변형 ㄱㄴㄷㄹ에서 변 ㄱㄴ이 8 cm, 변 ㄴㄷ이 6 cm예요. 평행사변형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["변 ㄱㄴ의 대응변은 변 ㄷㄹ, 변 ㄴㄷ의 대응변은 변 ㄹㄱ이에요.","대응변의 길이는 같아요.","8 + 6 + 8 + 6 = 28(cm)예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_challenge#5','math',5,2,'u3','L08','g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',3,'ox','auto','점대칭도형에서 대칭의 중심은 대응점을 이은 선분과 수직으로 만나요.',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":5,"concept":"M5-2-u3-C8","difficulty":3,"kind":"ox","stem":"점대칭도형에서 대칭의 중심은 대응점을 이은 선분과 수직으로 만나요.","answer":"X","reason_options":[{"t":"대칭의 중심은 선분을 이등분만 하고 수직으로 만나는 것은 대칭축이므로","correct":true},{"t":"대칭의 중심도 대칭축처럼 수직으로 나누므로","mis":"M5-2-u3-X15"}],"mis":"M5-2-u3-X15","explanation":["수직이등분은 선대칭도형의 대칭축이 하는 일이에요.","대칭의 중심은 선분을 똑같이 둘로 나누기만 해요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지 6 cm라면 두 대응점 사이는 6 cm예요.","answer":"X","reason_options":[{"t":"중심이 선분을 이등분해 두 대응점 사이는 12 cm이므로","correct":true},{"t":"대응점 사이는 중심까지의 거리와 같으므로","mis":"M5-2-u3-X10"}],"explanation":["다른 대응점까지도 6 cm예요.","6 + 6 = 12(cm)예요.","그래서 틀린 말이에요."]},{"stem":"점대칭도형에서 대응점을 이은 선분은 모두 대칭의 중심을 지나요.","answer":"O","reason_options":[{"t":"반 바퀴 돌리면 모든 점이 중심 반대편으로 가므로","correct":true},{"t":"대응점을 이은 선분은 서로 만나지 않으므로","mis":"M5-2-u3-X13"}],"explanation":["반 바퀴 돌리기는 한 점을 붙들고 도형을 돌리는 일이에요.","모든 점이 그 점 반대편으로 가요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_challenge#6','math',5,2,'u3','L08','g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',3,'mc','auto','육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 변 ㄷㄹ의 대응변은 어느 것인가요?',ARRAY['M5-2-u3-X07','M5-2-u3-X06','M5-2-u3-X15']::text[],true,'{"seq":6,"concept":"M5-2-u3-C8","difficulty":3,"kind":"mc","stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 변 ㄷㄹ의 대응변은 어느 것인가요?","options":[{"t":"변 ㅂㄱ","correct":true},{"t":"변 ㄱㄴ","mis":"M5-2-u3-X07"},{"t":"변 ㄴㄷ","mis":"M5-2-u3-X06"},{"t":"변 ㄷㄹ","mis":"M5-2-u3-X15"}],"explanation":["먼저 대응점을 찾아요 — 점 ㄷ ↔ 점 ㅂ, 점 ㄹ ↔ 점 ㄱ.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㅂㄱ이에요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 변 ㄹㅁ의 대응변은 어느 것인가요?","options":[{"t":"변 ㄱㄴ","correct":true},{"t":"변 ㄴㄷ","mis":"M5-2-u3-X07"},{"t":"변 ㄷㄹ","mis":"M5-2-u3-X06"},{"t":"변 ㄹㅁ","mis":"M5-2-u3-X15"}],"explanation":["먼저 대응점을 찾아요 — 점 ㄹ ↔ 점 ㄱ, 점 ㅁ ↔ 점 ㄴ.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㄱㄴ이에요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}},{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 변 ㅂㄱ의 대응변은 어느 것인가요?","options":[{"t":"변 ㄷㄹ","correct":true},{"t":"변 ㄱㄴ","mis":"M5-2-u3-X07"},{"t":"변 ㄴㄷ","mis":"M5-2-u3-X06"},{"t":"변 ㅂㄱ","mis":"M5-2-u3-X15"}],"explanation":["먼저 대응점을 찾아요 — 점 ㅂ ↔ 점 ㄷ, 점 ㄱ ↔ 점 ㄹ.","대응점끼리 이은 변이 대응변이에요.","그래서 변 ㄷㄹ이에요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,