INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_challenge#7','math',5,2,'u3','L08','g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',3,'sa','auto','육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄱㅇ이 6 cm일 때 선분 ㄱㄹ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u3-C8","difficulty":3,"kind":"sa","stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄱㅇ이 6 cm일 때 선분 ㄱㄹ은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["점 ㄱ과 점 ㄹ은 대응점이고 선분 ㄱㄹ은 점 ㅇ을 지나요.","점 ㅇ이 선분을 이등분해 선분 ㄹㅇ도 6 cm예요.","6 + 6 = 12(cm)예요."],"mis":"M5-2-u3-X10","asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[20,0],[120,80]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄴㅇ이 7 cm일 때 선분 ㄴㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["점 ㄴ과 점 ㅁ은 대응점이고 선분 ㄴㅁ은 점 ㅇ을 지나요.","점 ㅇ이 선분을 이등분해 선분 ㅁㅇ도 7 cm예요.","7 + 7 = 14(cm)예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[100,0],[40,80]]]}],"tag":false}},{"stem":"평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 선분 ㄱㅇ이 8 cm일 때 선분 ㄱㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["점 ㄱ과 점 ㄷ은 대응점이고 선분 ㄱㄷ은 점 ㅇ을 지나요.","점 ㅇ이 선분을 이등분해 선분 ㄷㅇ도 8 cm예요.","8 + 8 = 16(cm)예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[[[40,0],[100,80]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLU