INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_challenge#8','math',5,2,'u3','L08','g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',4,'mc','auto','육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 각 ㄱ이 125°일 때 각 ㄹ은 몇 도인가요?',ARRAY['M5-2-u3-X07','M5-2-u3-X15','M5-2-u3-X10']::text[],true,'{"seq":8,"concept":"M5-2-u3-C8","difficulty":4,"kind":"mc","stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 각 ㄱ이 125°일 때 각 ㄹ은 몇 도인가요?","options":[{"t":"125°","correct":true},{"t":"55°","mis":"M5-2-u3-X07"},{"t":"235°","mis":"M5-2-u3-X15"},{"t":"62°","mis":"M5-2-u3-X10"}],"explanation":["점 ㄱ의 대응점은 점 ㄹ이에요.","그래서 각 ㄱ과 각 ㄹ은 대응각이에요.","대응각의 크기는 같으므로 125°예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 각 ㄴ이 115°일 때 각 ㅁ은 몇 도인가요?","options":[{"t":"115°","correct":true},{"t":"65°","mis":"M5-2-u3-X07"},{"t":"245°","mis":"M5-2-u3-X15"},{"t":"57°","mis":"M5-2-u3-X10"}],"explanation":["점 ㄴ의 대응점은 점 ㅁ이에요.","그래서 각 ㄴ과 각 ㅁ은 대응각이에요.","대응각의 크기는 같으므로 115°예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}},{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 각 ㄹ이 120°일 때 각 ㄱ은 몇 도인가요?","options":[{"t":"120°","correct":true},{"t":"60°","mis":"M5-2-u3-X07"},{"t":"240°","mis":"M5-2-u3-X15"},{"t":"150°","mis":"M5-2-u3-X07"}],"explanation":["점 ㄹ의 대응점은 점 ㄱ이에요.","그래서 각 ㄹ과 각 ㄱ은 대응각이에요.","대응각의 크기는 같으므로 120°예요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_challenge#9','math',5,2,'u3','L08','g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',4,'sa','auto','점대칭도형에서 두 대응점 사이의 거리가 24 cm예요. 대칭의 중심에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C8","difficulty":4,"kind":"sa","stem":"점대칭도형에서 두 대응점 사이의 거리가 24 cm예요. 대칭의 중심에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 한쪽은 전체의 반이에요.","24 ÷ 2 = 12(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"점대칭도형에서 두 대응점 사이의 거리가 30 cm예요. 대칭의 중심에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 한쪽은 전체의 반이에요.","30 ÷ 2 = 15(cm)예요."]},{"stem":"점대칭도형에서 두 대응점 사이의 거리가 36 cm예요. 대칭의 중심에서 한 대응점까지는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 한쪽은 전체의 반이에요.","36 ÷ 2 = 18(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L08_challenge#10','math',5,2,'u3','L08','g5_2_math_u3_L08_challenge','lesson_challenge','M5-2-u3-C8',4,'essay','teacher','선대칭도형의 대칭축과 점대칭도형의 대칭의 중심이 대응점을 이은 선분과 어떤 관계인지 각각 쓰고, 점대칭도형에서 대응점을 이은 선분을 여러 개 그으면 어떻게 되는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C8","difficulty":4,"kind":"essay","stem":"선대칭도형의 대칭축과 점대칭도형의 대칭의 중심이 대응점을 이은 선분과 어떤 관계인지 각각 쓰고, 점대칭도형에서 대응점을 이은 선분을 여러 개 그으면 어떻게 되는지 쓰세요.","answer_guide":{"answer":"예: 선대칭도형의 대칭축은 대응점을 이은 선분과 수직으로 만나고 그 선분을 똑같이 둘로 나눈다(수직이등분). 점대칭도형의 대칭의 중심은 대응점을 이은 선분 위에 있으면서 그 선분을 똑같이 둘로 나누지만 수직으로 만나지는 않는다(이등분). 점대칭도형에서 대응점을 이은 선분을 여러 개 그으면 모두 대칭의 중심 한 점에서 만난다.","scoring_points":["대칭축은 수직이등분한다고 썼는가","대칭의 중심은 이등분만 한다(수직 아님)고 썼는가","선분들이 모두 대칭의 중심에서 만난다고 썼는가"]},"explanation":["대칭축 — 수직이등분이에요.","대칭의 중심 — 이등분만 해요.","대응점을 이은 선분은 모두 중심에서 만나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_basic#1','math',5,2,'u3','L09','g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',1,'mc','auto','점대칭도형을 그릴 때 대응점을 찍는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X13','M5-2-u3-X15']::text[],true,'{"seq":1,"concept":"M5-2-u3-C9","difficulty":1,"kind":"mc","stem":"점대칭도형을 그릴 때 대응점을 찍는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"대칭의 중심을 지나 같은 거리만큼 더 간 자리에 찍는다","correct":true},{"t":"중심까지 간 거리만큼 되돌아온다","mis":"M5-2-u3-X13"},{"t":"대칭의 중심에 그대로 찍는다","mis":"M5-2-u3-X13"},{"t":"대칭축과 수직인 방향으로 찍는다","mis":"M5-2-u3-X15"}],"explanation":["① 꼭짓점에서 대칭의 중심까지 몇 칸인지 세요.","② 중심을 지나 같은 칸 수만큼 더 간 자리에 대응점을 찍어요.","③ 찍은 점을 차례대로 이어요 — 선대칭처럼 수직으로 가는 것이 아니에요."],"variant_rule":{"alt":[{"stem":"점대칭도형을 완성하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"중심까지 칸 수 세기 → 중심을 지나 같은 만큼 더 가서 찍기 → 차례대로 잇기","correct":true},{"t":"차례대로 잇기 → 칸 수 세기 → 찍기","mis":"M5-2-u3-X13"},{"t":"중심에 점 찍기 → 차례대로 잇기 → 칸 수 세기","mis":"M5-2-u3-X13"},{"t":"대칭축 긋기 → 수직으로 찍기 → 접어 보기","mis":"M5-2-u3-X15"}],"explanation":["① 꼭짓점에서 대칭의 중심까지 몇 칸인지 세요.","② 중심을 지나 같은 칸 수만큼 더 간 자리에 대응점을 찍어요.","③ 찍은 점을 차례대로 이어요 — 선대칭처럼 수직으로 가는 것이 아니에요."]},{"stem":"선대칭도형 그리기와 점대칭도형 그리기의 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"선대칭은 대칭축과 수직으로, 점대칭은 중심을 지나는 방향으로 간다","correct":true},{"t":"둘 다 대칭축과 수직으로 간다","mis":"M5-2-u3-X15"},{"t":"점대칭은 중심에서 멈춘다","mis":"M5-2-u3-X13"},{"t":"선대칭은 중심을 지나 간다","mis":"M5-2-u3-X15"}],"explanation":["① 꼭짓점에서 대칭의 중심까지 몇 칸인지 세요.","② 중심을 지나 같은 칸 수만큼 더 간 자리에 대응점을 찍어요.","③ 찍은 점을 차례대로 이어요 — 선대칭처럼 수직으로 가는 것이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_basic#2','math',5,2,'u3','L09','g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',1,'sa','auto','점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 3칸이에요. 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C9","difficulty":1,"kind":"sa","stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 3칸이에요. 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대응점은 중심을 지나 3칸 더 간 자리예요.","꼭짓점에서 중심까지 3칸, 중심에서 대응점까지 3칸이에요.","3 + 3 = 6(칸)이에요."],"mis":"M5-2-u3-X13","variant_rule":{"alt":[{"stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 2칸이에요. 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["대응점은 중심을 지나 2칸 더 간 자리예요.","꼭짓점에서 중심까지 2칸, 중심에서 대응점까지 2칸이에요.","2 + 2 = 4(칸)이에요."]},{"stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 4칸이에요. 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대응점은 중심을 지나 4칸 더 간 자리예요.","꼭짓점에서 중심까지 4칸, 중심에서 대응점까지 4칸이에요.","4 + 4 = 8(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_basic#3','math',5,2,'u3','L09','g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',1,'mc','auto','점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 오른쪽 2칸, 아래 1칸을 갔어요. 대응점은 대칭의 중심에서 어느 쪽으로 가서 찍나요?',ARRAY['M5-2-u3-X13']::text[],true,'{"seq":3,"concept":"M5-2-u3-C9","difficulty":1,"kind":"mc","stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 오른쪽 2칸, 아래 1칸을 갔어요. 대응점은 대칭의 중심에서 어느 쪽으로 가서 찍나요?","options":[{"t":"오른쪽 2칸, 아래 1칸","correct":true},{"t":"왼쪽 2칸, 위 1칸","mis":"M5-2-u3-X13"},{"t":"오른쪽 1칸, 아래 2칸","mis":"M5-2-u3-X13"},{"t":"왼쪽 1칸, 위 2칸","mis":"M5-2-u3-X13"}],"explanation":["대응점은 중심을 지나 같은 만큼 더 간 자리예요.","꼭짓점에서 중심까지 간 방향 그대로 한 번 더 가요.","그래서 중심에서 오른쪽 2칸, 아래 1칸이에요."],"variant_rule":{"alt":[{"stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 오른쪽 1칸, 아래 3칸을 갔어요. 대응점은 대칭의 중심에서 어느 쪽으로 가서 찍나요?","options":[{"t":"오른쪽 1칸, 아래 3칸","correct":true},{"t":"왼쪽 1칸, 위 3칸","mis":"M5-2-u3-X13"},{"t":"오른쪽 3칸, 아래 1칸","mis":"M5-2-u3-X13"},{"t":"왼쪽 3칸, 위 1칸","mis":"M5-2-u3-X13"}],"explanation":["대응점은 중심을 지나 같은 만큼 더 간 자리예요.","꼭짓점에서 중심까지 간 방향 그대로 한 번 더 가요.","그래서 중심에서 오른쪽 1칸, 아래 3칸이에요."]},{"stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 왼쪽 2칸, 아래 1칸을 갔어요. 대응점은 대칭의 중심에서 어느 쪽으로 가서 찍나요?","options":[{"t":"왼쪽 2칸, 아래 1칸","correct":true},{"t":"오른쪽 2칸, 위 1칸","mis":"M5-2-u3-X13"},{"t":"오른쪽 1칸, 위 2칸","mis":"M5-2-u3-X13"},{"t":"왼쪽 1칸, 아래 2칸","mis":"M5-2-u3-X13"}],"explanation":["대응점은 중심을 지나 같은 만큼 더 간 자리예요.","꼭짓점에서 중심까지 간 방향 그대로 한 번 더 가요.","그래서 중심에서 왼쪽 2칸, 아래 1칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_basic#4','math',5,2,'u3','L09','g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',1,'sa','auto','점대칭도형에서 한 꼭짓점과 그 대응점 사이가 10칸이에요. 꼭짓점에서 대칭의 중심까지는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C9","difficulty":1,"kind":"sa","stem":"점대칭도형에서 한 꼭짓점과 그 대응점 사이가 10칸이에요. 꼭짓점에서 대칭의 중심까지는 몇 칸인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 중심까지는 전체의 반이에요.","10 ÷ 2 = 5(칸)이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"점대칭도형에서 한 꼭짓점과 그 대응점 사이가 8칸이에요. 꼭짓점에서 대칭의 중심까지는 몇 칸인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 중심까지는 전체의 반이에요.","8 ÷ 2 = 4(칸)이에요."]},{"stem":"점대칭도형에서 한 꼭짓점과 그 대응점 사이가 12칸이에요. 꼭짓점에서 대칭의 중심까지는 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 중심까지는 전체의 반이에요.","12 ÷ 2 = 6(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_basic#5','math',5,2,'u3','L09','g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',2,'mc','auto','모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13']::text[],true,'{"seq":5,"concept":"M5-2-u3-C9","difficulty":2,"kind":"mc","stem":"모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 2칸, 아래 1칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 2칸, 아래 1칸) 대응점이에요.","그래서 점 ㄴ이에요 — 점 ㄷ·ㄹ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":120,"h":80,"pts":{"ㄱ":[20,20,"ne"],"ㅇ":[60,40,"ne"],"ㄴ":[100,60,"ne"],"ㄷ":[100,20,"ne"],"ㄹ":[20,60,"ne"]},"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 2칸, 아래 1칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 2칸, 아래 1칸) 대응점이에요.","그래서 점 ㄷ이에요 — 점 ㄴ·ㄹ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":120,"h":80,"pts":{"ㄱ":[100,20,"ne"],"ㅇ":[60,40,"ne"],"ㄴ":[20,20,"ne"],"ㄷ":[20,60,"ne"],"ㄹ":[100,60,"ne"]},"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 1칸, 위 2칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 1칸, 위 2칸) 대응점이에요.","그래서 점 ㄹ이에요 — 점 ㄷ·ㄴ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":80,"h":120,"pts":{"ㄱ":[20,100,"ne"],"ㅇ":[40,60,"ne"],"ㄴ":[20,20,"ne"],"ㄷ":[60,100,"ne"],"ㄹ":[60,20,"ne"]},"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_basic#6','math',5,2,'u3','L09','g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',2,'mc','auto','점대칭도형을 다 그린 뒤 확인하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X05','M5-2-u3-X02']::text[],true,'{"seq":6,"concept":"M5-2-u3-C9","difficulty":2,"kind":"mc","stem":"점대칭도형을 다 그린 뒤 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"대칭의 중심을 기준으로 반 바퀴 돌려 겹치는지 본다","correct":true},{"t":"대칭축으로 접어 본다","mis":"M5-2-u3-X15"},{"t":"넓이를 재어 본다","mis":"M5-2-u3-X05"},{"t":"색을 칠해 본다","mis":"M5-2-u3-X02"}],"explanation":["점대칭도형은 반 바퀴 돌려 완전히 겹쳐야 해요.","중심까지만 가면 대응점이 도형 안쪽에 찍혀 작아져요.","중심은 도착하는 곳이 아니라 지나가는 곳이에요."],"variant_rule":{"alt":[{"stem":"대응점을 중심까지만 가서 찍었다면 어떻게 되나요?","options":[{"t":"원래보다 작은 도형이 되어 겹치지 않는다","correct":true},{"t":"원래 도형과 겹친다","mis":"M5-2-u3-X13"},{"t":"원래보다 큰 도형이 된다","mis":"M5-2-u3-X10"},{"t":"달라지지 않는다","mis":"M5-2-u3-X13"}],"explanation":["점대칭도형은 반 바퀴 돌려 완전히 겹쳐야 해요.","중심까지만 가면 대응점이 도형 안쪽에 찍혀 작아져요.","중심은 도착하는 곳이 아니라 지나가는 곳이에요."]},{"stem":"점대칭도형을 그릴 때 「중심은 지나가는 곳」이라고 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"중심에서 멈추면 대응점이 안쪽에 찍혀 겹치지 않기 때문에","correct":true},{"t":"중심에 대응점을 찍어야 하기 때문에","mis":"M5-2-u3-X13"},{"t":"중심은 대칭축 위에 있기 때문에","mis":"M5-2-u3-X15"},{"t":"중심을 지나면 도형이 두 배가 되기 때문에","mis":"M5-2-u3-X10"}],"explanation":["점대칭도형은 반 바퀴 돌려 완전히 겹쳐야 해요.","중심까지만 가면 대응점이 도형 안쪽에 찍혀 작아져요.","중심은 도착하는 곳이 아니라 지나가는 곳이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_basic#7','math',5,2,'u3','L09','g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',2,'ox','auto','점대칭도형을 그릴 때 꼭짓점에서 중심까지 오른쪽 2칸, 아래 1칸 갔다면 대응점은 중심에서 오른쪽 2칸, 아래 1칸 간 자리예요.',ARRAY['M5-2-u3-X13']::text[],true,'{"seq":7,"concept":"M5-2-u3-C9","difficulty":2,"kind":"ox","stem":"점대칭도형을 그릴 때 꼭짓점에서 중심까지 오른쪽 2칸, 아래 1칸 갔다면 대응점은 중심에서 오른쪽 2칸, 아래 1칸 간 자리예요.","answer":"O","reason_options":[{"t":"중심을 지나 같은 방향으로 같은 만큼 더 가므로","correct":true},{"t":"중심에서 반대로 왼쪽 2칸, 위 1칸 가야 하므로","mis":"M5-2-u3-X13"}],"mis":"M5-2-u3-X13","explanation":["꼭짓점 → 중심이 오른쪽 2칸, 아래 1칸이에요.","중심을 지나 같은 만큼 한 번 더 가요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"점대칭도형을 그릴 때 대응점은 대칭의 중심에 찍어요.","answer":"X","reason_options":[{"t":"중심을 지나 같은 거리만큼 더 간 자리에 찍어야 하므로","correct":true},{"t":"모든 대응점은 중심 한 점에 모이므로","mis":"M5-2-u3-X13"}],"explanation":["중심은 지나가는 곳이에요.","중심에 찍으면 반 바퀴 돌려도 겹치지 않아요.","그래서 틀린 말이에요."]},{"stem":"점대칭도형을 다 그린 뒤에는 반 바퀴 돌려 겹치는지 확인해요.","answer":"O","reason_options":[{"t":"점대칭도형은 반 바퀴 돌려 완전히 겹치는 도형이므로","correct":true},{"t":"대칭축으로 접어 보아야 하므로","mis":"M5-2-u3-X15"}],"explanation":["점대칭도형의 뜻이 반 바퀴 돌려 겹치는 것이에요.","겹치면 바르게 그린 거예요.","맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_basic#8','math',5,2,'u3','L09','g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',2,'sa','auto','대칭의 중심까지 2칸, 4칸, 5칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C9","difficulty":2,"kind":"sa","stem":"대칭의 중심까지 2칸, 4칸, 5칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["꼭짓점과 대응점 사이는 중심까지 거리의 두 배예요.","2 × 2 = 4, 4 × 2 = 8, 5 × 2 = 10이에요.","4 + 8 + 10 = 22(칸)이에요."],"mis":"M5-2-u3-X13","variant_rule":{"alt":[{"stem":"대칭의 중심까지 1칸, 3칸, 6칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["꼭짓점과 대응점 사이는 중심까지 거리의 두 배예요.","1 × 2 = 2, 3 × 2 = 6, 6 × 2 = 12예요.","2 + 6 + 12 = 20(칸)이에요."]},{"stem":"대칭의 중심까지 3칸, 3칸, 4칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["꼭짓점과 대응점 사이는 중심까지 거리의 두 배예요.","3 × 2 = 6, 3 × 2 = 6, 4 × 2 = 8이에요.","6 + 6 + 8 = 20(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_basic#9','math',5,2,'u3','L09','g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',2,'sa','auto','점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 4 cm, 2 cm, 2 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C9","difficulty":2,"kind":"sa","stem":"점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 4 cm, 2 cm, 2 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 4 + 2 + 2 = 8(cm)예요.","둘레는 8 × 2 = 16(cm)예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 5 cm, 3 cm, 1 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 5 + 3 + 1 = 9(cm)예요.","둘레는 9 × 2 = 18(cm)예요."]},{"stem":"점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 3 cm, 6 cm, 2 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 3 + 6 + 2 = 11(cm)예요.","둘레는 11 × 2 = 22(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_basic#10','math',5,2,'u3','L09','g5_2_math_u3_L09_basic','lesson_basic','M5-2-u3-C9',3,'mc','auto','모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13']::text[],true,'{"seq":10,"concept":"M5-2-u3-C9","difficulty":3,"kind":"mc","stem":"모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 3칸, 위 2칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 3칸, 위 2칸) 대응점이에요.","그래서 점 ㄷ이에요 — 점 ㄹ·ㄴ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[140,100,"ne"],"ㅇ":[80,60,"ne"],"ㄴ":[140,20,"ne"],"ㄷ":[20,20,"ne"],"ㄹ":[20,100,"ne"]},"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 3칸, 위 1칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 3칸, 위 1칸) 대응점이에요.","그래서 점 ㄴ이에요 — 점 ㄹ·ㄷ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":160,"h":80,"pts":{"ㄱ":[20,60,"ne"],"ㅇ":[80,40,"ne"],"ㄴ":[140,20,"ne"],"ㄷ":[20,20,"ne"],"ㄹ":[140,60,"ne"]},"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 1칸, 아래 3칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 1칸, 아래 3칸) 대응점이에요.","그래서 점 ㄹ이에요 — 점 ㄴ·ㄷ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":80,"h":160,"pts":{"ㄱ":[20,20,"ne"],"ㅇ":[40,80,"ne"],"ㄴ":[60,20,"ne"],"ㄷ":[20,140,"ne"],"ㄹ":[60,140,"ne"]},"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_challenge#1','math',5,2,'u3','L09','g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',2,'sa','auto','점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 7칸이에요. 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C9","difficulty":2,"kind":"sa","stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 7칸이에요. 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["대응점은 중심을 지나 7칸 더 간 자리예요.","꼭짓점에서 중심까지 7칸, 중심에서 대응점까지 7칸이에요.","7 + 7 = 14(칸)이에요."],"mis":"M5-2-u3-X13","variant_rule":{"alt":[{"stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 8칸이에요. 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대응점은 중심을 지나 8칸 더 간 자리예요.","꼭짓점에서 중심까지 8칸, 중심에서 대응점까지 8칸이에요.","8 + 8 = 16(칸)이에요."]},{"stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 9칸이에요. 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["대응점은 중심을 지나 9칸 더 간 자리예요.","꼭짓점에서 중심까지 9칸, 중심에서 대응점까지 9칸이에요.","9 + 9 = 18(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_challenge#2','math',5,2,'u3','L09','g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',2,'mc','auto','점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 왼쪽 3칸, 아래 2칸을 갔어요. 대응점은 대칭의 중심에서 어느 쪽으로 가서 찍나요?',ARRAY['M5-2-u3-X13']::text[],true,'{"seq":2,"concept":"M5-2-u3-C9","difficulty":2,"kind":"mc","stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 왼쪽 3칸, 아래 2칸을 갔어요. 대응점은 대칭의 중심에서 어느 쪽으로 가서 찍나요?","options":[{"t":"왼쪽 3칸, 아래 2칸","correct":true},{"t":"오른쪽 3칸, 위 2칸","mis":"M5-2-u3-X13"},{"t":"오른쪽 2칸, 위 3칸","mis":"M5-2-u3-X13"},{"t":"왼쪽 2칸, 아래 3칸","mis":"M5-2-u3-X13"}],"explanation":["대응점은 중심을 지나 같은 만큼 더 간 자리예요.","꼭짓점에서 중심까지 간 방향 그대로 한 번 더 가요.","그래서 중심에서 왼쪽 3칸, 아래 2칸이에요."],"variant_rule":{"alt":[{"stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 오른쪽 3칸, 위 1칸을 갔어요. 대응점은 대칭의 중심에서 어느 쪽으로 가서 찍나요?","options":[{"t":"오른쪽 3칸, 위 1칸","correct":true},{"t":"왼쪽 3칸, 아래 1칸","mis":"M5-2-u3-X13"},{"t":"왼쪽 1칸, 아래 3칸","mis":"M5-2-u3-X13"},{"t":"오른쪽 1칸, 위 3칸","mis":"M5-2-u3-X13"}],"explanation":["대응점은 중심을 지나 같은 만큼 더 간 자리예요.","꼭짓점에서 중심까지 간 방향 그대로 한 번 더 가요.","그래서 중심에서 오른쪽 3칸, 위 1칸이에요."]},{"stem":"점대칭도형을 그리려고 해요. 꼭짓점에서 대칭의 중심까지 왼쪽 1칸, 위 2칸을 갔어요. 대응점은 대칭의 중심에서 어느 쪽으로 가서 찍나요?","options":[{"t":"왼쪽 1칸, 위 2칸","correct":true},{"t":"오른쪽 1칸, 아래 2칸","mis":"M5-2-u3-X13"},{"t":"왼쪽 2칸, 위 1칸","mis":"M5-2-u3-X13"},{"t":"오른쪽 2칸, 아래 1칸","mis":"M5-2-u3-X13"}],"explanation":["대응점은 중심을 지나 같은 만큼 더 간 자리예요.","꼭짓점에서 중심까지 간 방향 그대로 한 번 더 가요.","그래서 중심에서 왼쪽 1칸, 위 2칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_challenge#3','math',5,2,'u3','L09','g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',3,'mc','auto','모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13']::text[],true,'{"seq":3,"concept":"M5-2-u3-C9","difficulty":3,"kind":"mc","stem":"모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 2칸, 위 3칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 2칸, 위 3칸) 대응점이에요.","그래서 점 ㄴ이에요 — 점 ㄹ·ㄷ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":120,"h":160,"pts":{"ㄱ":[100,140,"ne"],"ㅇ":[60,80,"ne"],"ㄴ":[20,20,"ne"],"ㄷ":[100,20,"ne"],"ㄹ":[20,140,"ne"]},"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 3칸, 아래 2칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 3칸, 아래 2칸) 대응점이에요.","그래서 점 ㄷ이에요 — 점 ㄴ·ㄹ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20,20,"ne"],"ㅇ":[80,60,"ne"],"ㄴ":[140,20,"ne"],"ㄷ":[140,100,"ne"],"ㄹ":[20,100,"ne"]},"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 3칸, 아래 2칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 3칸, 아래 2칸) 대응점이에요.","그래서 점 ㄹ이에요 — 점 ㄷ·ㄴ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[140,20,"ne"],"ㅇ":[80,60,"ne"],"ㄴ":[140,100,"ne"],"ㄷ":[20,20,"ne"],"ㄹ":[20,100,"ne"]},"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_challenge#4','math',5,2,'u3','L09','g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',3,'ox','auto','점대칭도형을 그릴 때 중심에 가까운 꼭짓점의 대응점은 중심에 가깝게 찍혀요.',ARRAY['M5-2-u3-X10']::text[],true,'{"seq":4,"concept":"M5-2-u3-C9","difficulty":3,"kind":"ox","stem":"점대칭도형을 그릴 때 중심에 가까운 꼭짓점의 대응점은 중심에 가깝게 찍혀요.","answer":"O","reason_options":[{"t":"중심을 지나 같은 거리만큼 더 가므로","correct":true},{"t":"모든 대응점은 중심에서 같은 거리에 있으므로","mis":"M5-2-u3-X10"}],"mis":"M5-2-u3-X10","explanation":["중심까지 1칸이면 반대편으로도 1칸이에요.","먼 점은 멀게, 가까운 점은 가깝게 찍혀요.","맞는 말이에요."],"variant_rule":{"alt":[{"stem":"점대칭도형도 대칭축과 수직인 방향으로 대응점을 찍어요.","answer":"X","reason_options":[{"t":"점대칭도형은 중심을 지나는 방향으로 같은 거리만큼 가므로","correct":true},{"t":"모든 대칭도형은 수직으로 찍으므로","mis":"M5-2-u3-X15"}],"explanation":["수직 방향으로 가는 것은 선대칭도형이에요.","점대칭도형은 중심을 지나 반대편으로 가요.","틀린 말이에요."]},{"stem":"점대칭도형을 그릴 때 대응점은 대칭의 중심에 찍어요.","answer":"X","reason_options":[{"t":"중심을 지나 같은 거리만큼 더 간 자리에 찍어야 하므로","correct":true},{"t":"모든 대응점은 중심 한 점에 모이므로","mis":"M5-2-u3-X13"}],"explanation":["중심은 지나가는 곳이에요.","중심에 찍으면 반 바퀴 돌려도 겹치지 않아요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_challenge#5','math',5,2,'u3','L09','g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',3,'sa','auto','대칭의 중심까지 2칸, 5칸, 6칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u3-C9","difficulty":3,"kind":"sa","stem":"대칭의 중심까지 2칸, 5칸, 6칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["꼭짓점과 대응점 사이는 중심까지 거리의 두 배예요.","2 × 2 = 4, 5 × 2 = 10, 6 × 2 = 12예요.","4 + 10 + 12 = 26(칸)이에요."],"mis":"M5-2-u3-X13","variant_rule":{"alt":[{"stem":"대칭의 중심까지 4칸, 4칸, 7칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["꼭짓점과 대응점 사이는 중심까지 거리의 두 배예요.","4 × 2 = 8, 4 × 2 = 8, 7 × 2 = 14예요.","8 + 8 + 14 = 30(칸)이에요."]},{"stem":"대칭의 중심까지 1칸, 6칸, 8칸 떨어진 꼭짓점이 하나씩 있어요. 세 꼭짓점과 그 대응점 사이의 거리를 모두 더하면 몇 칸인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["꼭짓점과 대응점 사이는 중심까지 거리의 두 배예요.","1 × 2 = 2, 6 × 2 = 12, 8 × 2 = 16이에요.","2 + 12 + 16 = 30(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_challenge#6','math',5,2,'u3','L09','g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',3,'sa','auto','점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 6 cm, 4 cm, 3 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C9","difficulty":3,"kind":"sa","stem":"점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 6 cm, 4 cm, 3 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 6 + 4 + 3 = 13(cm)예요.","둘레는 13 × 2 = 26(cm)예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 7 cm, 2 cm, 5 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 7 + 2 + 5 = 14(cm)예요.","둘레는 14 × 2 = 28(cm)예요."]},{"stem":"점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 5 cm, 5 cm, 4 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 5 + 5 + 4 = 14(cm)예요.","둘레는 14 × 2 = 28(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_challenge#7','math',5,2,'u3','L09','g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',3,'sa','auto','점대칭도형에서 한 꼭짓점과 그 대응점 사이가 16칸이에요. 꼭짓점에서 대칭의 중심까지는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u3-C9","difficulty":3,"kind":"sa","stem":"점대칭도형에서 한 꼭짓점과 그 대응점 사이가 16칸이에요. 꼭짓점에서 대칭의 중심까지는 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 중심까지는 전체의 반이에요.","16 ÷ 2 = 8(칸)이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"점대칭도형에서 한 꼭짓점과 그 대응점 사이가 18칸이에요. 꼭짓점에서 대칭의 중심까지는 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 중심까지는 전체의 반이에요.","18 ÷ 2 = 9(칸)이에요."]},{"stem":"점대칭도형에서 한 꼭짓점과 그 대응점 사이가 14칸이에요. 꼭짓점에서 대칭의 중심까지는 몇 칸인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","그래서 중심까지는 전체의 반이에요.","14 ÷ 2 = 7(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_challenge#8','math',5,2,'u3','L09','g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',4,'sa','auto','점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 4 cm, 3 cm, 2 cm, 1 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C9","difficulty":4,"kind":"sa","stem":"점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 4 cm, 3 cm, 2 cm, 1 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 4 + 3 + 2 + 1 = 10(cm)예요.","둘레는 10 × 2 = 20(cm)예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 5 cm, 1 cm, 3 cm, 2 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 5 + 1 + 3 + 2 = 11(cm)예요.","둘레는 11 × 2 = 22(cm)예요."]},{"stem":"점대칭도형의 반쪽을 그렸더니 반쪽에 있는 변이 6 cm, 2 cm, 2 cm, 3 cm였어요. 나머지 반쪽을 그려 완성한 도형 전체의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["나머지 반쪽에는 길이가 같은 대응변이 생겨요.","반쪽 변의 합은 6 + 2 + 2 + 3 = 13(cm)예요.","둘레는 13 × 2 = 26(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_challenge#9','math',5,2,'u3','L09','g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',4,'mc','auto','모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13']::text[],true,'{"seq":9,"concept":"M5-2-u3-C9","difficulty":4,"kind":"mc","stem":"모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 4칸, 위 1칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 4칸, 위 1칸) 대응점이에요.","그래서 점 ㄷ이에요 — 점 ㄹ·ㄴ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":200,"h":80,"pts":{"ㄱ":[20,60,"ne"],"ㅇ":[100,40,"ne"],"ㄴ":[20,20,"ne"],"ㄷ":[180,20,"ne"],"ㄹ":[180,60,"ne"]},"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 1칸, 아래 3칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 1칸, 아래 3칸) 대응점이에요.","그래서 점 ㄴ이에요 — 점 ㄷ·ㄹ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":80,"h":160,"pts":{"ㄱ":[60,20,"ne"],"ㅇ":[40,80,"ne"],"ㄴ":[20,140,"ne"],"ㄷ":[20,20,"ne"],"ㄹ":[60,140,"ne"]},"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 4칸, 위 3칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 4칸, 위 3칸) 대응점이에요.","그래서 점 ㄹ이에요 — 점 ㄴ·ㄷ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":200,"h":160,"pts":{"ㄱ":[180,140,"ne"],"ㅇ":[100,80,"ne"],"ㄴ":[20,140,"ne"],"ㄷ":[180,20,"ne"],"ㄹ":[20,20,"ne"]},"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L09_challenge#10','math',5,2,'u3','L09','g5_2_math_u3_L09_challenge','lesson_challenge','M5-2-u3-C9',4,'essay','teacher','점대칭도형을 그리려고 해요. 꼭짓점 ㄱ에서 대칭의 중심까지 오른쪽으로 2칸, 아래로 1칸을 갔어요. 점 ㄱ의 대응점을 대칭의 중심에서 어디에 찍어야 하는지 쓰고, 대응점을 중심까지만 가서 찍으면 어떻게 되는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C9","difficulty":4,"kind":"essay","stem":"점대칭도형을 그리려고 해요. 꼭짓점 ㄱ에서 대칭의 중심까지 오른쪽으로 2칸, 아래로 1칸을 갔어요. 점 ㄱ의 대응점을 대칭의 중심에서 어디에 찍어야 하는지 쓰고, 대응점을 중심까지만 가서 찍으면 어떻게 되는지 쓰세요.","answer_guide":{"answer":"예: 대응점은 대칭의 중심을 지나 같은 만큼 더 간 자리이므로, 중심에서 오른쪽으로 2칸, 아래로 1칸 간 자리에 찍는다. 그러면 점 ㄱ과 대응점 사이는 오른쪽으로 4칸, 아래로 2칸이 되고 중심이 그 선분을 이등분한다. 중심까지만 가서 찍으면 대응점이 도형 안쪽에 찍혀 원래보다 작은 도형이 되므로 반 바퀴 돌려도 겹치지 않는다.","scoring_points":["중심에서 오른쪽 2칸, 아래 1칸이라고 썼는가","중심을 지나 같은 만큼 더 간다는 까닭을 썼는가","중심에서 멈추면 작아져 겹치지 않는다고 썼는가"]},"explanation":["중심을 지나 같은 만큼 한 번 더 가요.","중심에서 오른쪽 2칸, 아래 1칸이에요.","중심에서 멈추면 작아져 겹치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_basic#1','math',5,2,'u3','L10','g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',1,'mc','auto','사과나무 4그루가 있는 땅을 네 곳에 똑같이 나누려고 해요. 땅을 나누는 조건으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M5-2-u3-X17']::text[],true,'{"seq":1,"concept":"M5-2-u3-C10","difficulty":1,"kind":"mc","stem":"사과나무 4그루가 있는 땅을 네 곳에 똑같이 나누려고 해요. 땅을 나누는 조건으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"도형의 넓이만 같으면 된다","correct":true},{"t":"합동인 도형 4개로 나눈다","mis":"M5-2-u3-X17"},{"t":"각 도형에 사과나무가 한 그루씩 들어간다","mis":"M5-2-u3-X17"},{"t":"조각마다 정사각형의 개수가 같다","mis":"M5-2-u3-X17"}],"explanation":["조건 ① 땅을 합동인 도형 4개로 나눠요.","조건 ② 각 도형에 사과나무가 한 그루씩 들어가요.","「똑같이」는 넓이가 같은 것이 아니라 조각들이 서로 합동이라는 뜻이에요."],"variant_rule":{"alt":[{"stem":"땅을 「똑같이」 나누었다는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"나눈 조각들이 서로 합동이다","correct":true},{"t":"나눈 조각들의 넓이만 같다","mis":"M5-2-u3-X05"},{"t":"나눈 조각들의 둘레만 같다","mis":"M5-2-u3-X05"},{"t":"나눈 조각들의 색이 같다","mis":"M5-2-u3-X02"}],"explanation":["조건 ① 땅을 합동인 도형 4개로 나눠요.","조건 ② 각 도형에 사과나무가 한 그루씩 들어가요.","「똑같이」는 넓이가 같은 것이 아니라 조각들이 서로 합동이라는 뜻이에요."]},{"stem":"땅을 바르게 나누었는지 확인할 때 살펴야 할 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"조각들이 서로 합동인지와 조각마다 나무가 한 그루씩인지","correct":true},{"t":"조각의 수만","mis":"M5-2-u3-X16"},{"t":"나무가 한 그루씩인지만","mis":"M5-2-u3-X16"},{"t":"조각들의 넓이가 같은지만","mis":"M5-2-u3-X05"}],"explanation":["조건 ① 땅을 합동인 도형 4개로 나눠요.","조건 ② 각 도형에 사과나무가 한 그루씩 들어가요.","「똑같이」는 넓이가 같은 것이 아니라 조각들이 서로 합동이라는 뜻이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_basic#2','math',5,2,'u3','L10','g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',1,'sa','auto','모양과 크기가 같은 정사각형 12개가 붙어 있는 땅을 서로 합동인 도형 4개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C10","difficulty":1,"kind":"sa","stem":"모양과 크기가 같은 정사각형 12개가 붙어 있는 땅을 서로 합동인 도형 4개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","12개를 4조각에 똑같이 나누어요.","12 ÷ 4 = 3(개)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"모양과 크기가 같은 정사각형 16개가 붙어 있는 땅을 서로 합동인 도형 4개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","16개를 4조각에 똑같이 나누어요.","16 ÷ 4 = 4(개)예요."]},{"stem":"모양과 크기가 같은 정사각형 18개가 붙어 있는 땅을 서로 합동인 도형 6개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","18개를 6조각에 똑같이 나누어요.","18 ÷ 6 = 3(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_basic#3','math',5,2,'u3','L10','g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',1,'mc','auto','나눈 네 도형이 서로 합동인지 확인하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X02','M5-2-u3-X16','M5-2-u3-X05']::text[],true,'{"seq":3,"concept":"M5-2-u3-C10","difficulty":1,"kind":"mc","stem":"나눈 네 도형이 서로 합동인지 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"포개어 완전히 겹치는지 본다","correct":true},{"t":"색이 같은지 본다","mis":"M5-2-u3-X02"},{"t":"사과나무의 크기를 잰다","mis":"M5-2-u3-X16"},{"t":"정사각형의 개수만 센다","mis":"M5-2-u3-X05"}],"explanation":["합동인지는 포개어 완전히 겹치는지로 알아봐요 — 돌리거나 뒤집어 겹쳐도 돼요.","나무 조건도 함께 확인해요.","두 조건을 모두 만족해야 바르게 나눈 거예요."],"variant_rule":{"alt":[{"stem":"나눈 조각 하나가 다른 조각과 돌려야 겹쳐요. 알맞은 설명은 어느 것인가요?","options":[{"t":"돌려서 겹치므로 두 조각은 합동이다","correct":true},{"t":"돌려야 겹치므로 합동이 아니다","mis":"M5-2-u3-X04"},{"t":"넓이가 달라진다","mis":"M5-2-u3-X01"},{"t":"나무가 두 그루가 된다","mis":"M5-2-u3-X16"}],"explanation":["합동인지는 포개어 완전히 겹치는지로 알아봐요 — 돌리거나 뒤집어 겹쳐도 돼요.","나무 조건도 함께 확인해요.","두 조건을 모두 만족해야 바르게 나눈 거예요."]},{"stem":"일자 모양으로는 조건에 맞게 나눌 수 없었어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"일자 모양으로 나누면 나무가 두 그루 든 조각과 없는 조각이 생기기 때문에","correct":true},{"t":"일자 모양은 정사각형 4개라서","mis":"M5-2-u3-X16"},{"t":"일자 모양은 넓이가 달라서","mis":"M5-2-u3-X05"},{"t":"일자 모양은 합동이 될 수 없어서","mis":"M5-2-u3-X03"}],"explanation":["합동인지는 포개어 완전히 겹치는지로 알아봐요 — 돌리거나 뒤집어 겹쳐도 돼요.","나무 조건도 함께 확인해요.","두 조건을 모두 만족해야 바르게 나눈 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_basic#4','math',5,2,'u3','L10','g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',1,'sa','auto','나눈 한 조각은 한 변이 5 m인 정사각형 3개가 붙은 ㄱ자 모양이에요. 이 조각의 둘레는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C10","difficulty":1,"kind":"sa","stem":"나눈 한 조각은 한 변이 5 m인 정사각형 3개가 붙은 ㄱ자 모양이에요. 이 조각의 둘레는 몇 m인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["ㄱ자 모양의 둘레를 따라가면 정사각형 한 변이 8번 나와요.","모서리를 돌며 세면 2 + 1 + 1 + 1 + 1 + 2 = 8(번)이에요.","5 × 8 = 40(m)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"나눈 한 조각은 한 변이 4 m인 정사각형 3개가 붙은 ㄱ자 모양이에요. 이 조각의 둘레는 몇 m인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["ㄱ자 모양의 둘레를 따라가면 정사각형 한 변이 8번 나와요.","모서리를 돌며 세면 2 + 1 + 1 + 1 + 1 + 2 = 8(번)이에요.","4 × 8 = 32(m)예요."]},{"stem":"나눈 한 조각은 한 변이 6 m인 정사각형 3개가 붙은 ㄱ자 모양이에요. 이 조각의 둘레는 몇 m인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["ㄱ자 모양의 둘레를 따라가면 정사각형 한 변이 8번 나와요.","모서리를 돌며 세면 2 + 1 + 1 + 1 + 1 + 2 = 8(번)이에요.","6 × 8 = 48(m)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_basic#5','math',5,2,'u3','L10','g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',2,'sa','auto','정사각형 12개가 붙은 땅을 그림처럼 일자 모양 네 조각으로 나누었어요. 점 ㄱ·ㄴ·ㄷ·ㄹ은 사과나무가 있는 자리예요. 사과나무가 한 그루도 없는 조각은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u3-C10","difficulty":2,"kind":"sa","stem":"정사각형 12개가 붙은 땅을 그림처럼 일자 모양 네 조각으로 나누었어요. 점 ㄱ·ㄴ·ㄷ·ㄹ은 사과나무가 있는 자리예요. 사과나무가 한 그루도 없는 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["왼쪽 조각부터 나무 수를 세면 2, 0, 0, 2그루예요.","나무가 없는 조각은 2개예요.","조각끼리는 합동이어도 나무 조건이 어긋나 바르게 나눈 것이 아니에요."],"mis":"M5-2-u3-X16","asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[140.0,20.0,"ne"],"ㄷ":[20.0,100.0,"ne"],"ㄹ":[140.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 정사각형 12개가 붙은 땅을 그림처럼 일자 모양 네 조각으로 나누었어요. 점 ㄱ·ㄴ·ㄷ·ㄹ은 사과나무가 있는 자리예요. 사과나무가 한 그루도 없는 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["왼쪽 조각부터 나무 수를 세면 1, 1, 2, 0그루예요.","나무가 없는 조각은 1개예요.","조각끼리는 합동이어도 나무 조건이 어긋나 바르게 나눈 것이 아니에요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[60.0,60.0,"ne"],"ㄷ":[100.0,20.0,"ne"],"ㄹ":[100.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40}],"tag":false}},{"stem":"이번에는 다른 보기예요. 정사각형 12개가 붙은 땅을 그림처럼 일자 모양 네 조각으로 나누었어요. 점 ㄱ·ㄴ·ㄷ·ㄹ은 사과나무가 있는 자리예요. 사과나무가 한 그루도 없는 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["왼쪽 조각부터 나무 수를 세면 0, 2, 1, 1그루예요.","나무가 없는 조각은 1개예요.","조각끼리는 합동이어도 나무 조건이 어긋나 바르게 나눈 것이 아니에요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[60.0,20.0,"ne"],"ㄴ":[60.0,100.0,"ne"],"ㄷ":[140.0,60.0,"ne"],"ㄹ":[100.0,60.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_basic#6','math',5,2,'u3','L10','g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',2,'mc','auto','정사각형 3개로 된 ㄱ자 모양과 일자 모양에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X02','M5-2-u3-X05']::text[],true,'{"seq":6,"concept":"M5-2-u3-C10","difficulty":2,"kind":"mc","stem":"정사각형 3개로 된 ㄱ자 모양과 일자 모양에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"모양이 달라 포개도 겹치지 않으므로 합동이 아니다","correct":true},{"t":"포개면 겹치므로 합동이다","mis":"M5-2-u3-X02"},{"t":"넓이가 같으므로 합동이다","mis":"M5-2-u3-X05"},{"t":"둘레가 같으므로 합동이다","mis":"M5-2-u3-X05"}],"explanation":["정사각형 3개가 붙는 모양은 일자 모양과 ㄱ자 모양 두 가지뿐이에요.","둘은 넓이(칸 수)가 같아도 포개면 겹치지 않아요.","그래서 네 조각이 서로 합동이려면 한 가지 모양으로만 나누어야 해요."],"variant_rule":{"alt":[{"stem":"정사각형 12개를 정사각형 3개씩 네 조각으로 나누었는데 두 조각은 ㄱ자, 두 조각은 일자 모양이에요. 알맞은 설명은 어느 것인가요?","options":[{"t":"네 조각이 서로 합동이 아니라서 똑같이 나눈 것이 아니다","correct":true},{"t":"칸 수가 같으니 똑같이 나눈 것이다","mis":"M5-2-u3-X05"},{"t":"넓이가 같으니 똑같이 나눈 것이다","mis":"M5-2-u3-X05"},{"t":"조각 수가 4개이니 똑같이 나눈 것이다","mis":"M5-2-u3-X16"}],"explanation":["정사각형 3개가 붙는 모양은 일자 모양과 ㄱ자 모양 두 가지뿐이에요.","둘은 넓이(칸 수)가 같아도 포개면 겹치지 않아요.","그래서 네 조각이 서로 합동이려면 한 가지 모양으로만 나누어야 해요."]},{"stem":"정사각형 3개가 붙은 모양은 몇 가지인가요(돌리거나 뒤집어 겹치는 것은 한 가지로 봐요)?","options":[{"t":"2가지(일자 모양, ㄱ자 모양)","correct":true},{"t":"1가지","mis":"M5-2-u3-X16"},{"t":"3가지","mis":"M5-2-u3-X02"},{"t":"4가지","mis":"M5-2-u3-X04"}],"explanation":["정사각형 3개가 붙는 모양은 일자 모양과 ㄱ자 모양 두 가지뿐이에요.","둘은 넓이(칸 수)가 같아도 포개면 겹치지 않아요.","그래서 네 조각이 서로 합동이려면 한 가지 모양으로만 나누어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_basic#7','math',5,2,'u3','L10','g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',2,'ox','auto','정사각형 12개를 넓이가 같은 네 조각으로 나누면 언제나 똑같이 나눈 것이에요.',ARRAY['M5-2-u3-X05']::text[],true,'{"seq":7,"concept":"M5-2-u3-C10","difficulty":2,"kind":"ox","stem":"정사각형 12개를 넓이가 같은 네 조각으로 나누면 언제나 똑같이 나눈 것이에요.","answer":"X","reason_options":[{"t":"넓이가 같아도 모양이 달라 겹치지 않으면 합동이 아니므로","correct":true},{"t":"넓이가 같으면 늘 합동이므로","mis":"M5-2-u3-X05"}],"mis":"M5-2-u3-X05","explanation":["일자 조각과 ㄱ자 조각은 넓이가 같아요.","그런데 포개도 겹치지 않아요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"정사각형 12개를 합동인 도형 4개로 나누면 한 조각은 정사각형 3개예요.","answer":"O","reason_options":[{"t":"12 ÷ 4 = 3이므로","correct":true},{"t":"12 − 4 = 8이므로","mis":"M5-2-u3-X16"}],"explanation":["합동인 조각은 정사각형 수가 같아요.","12 ÷ 4 = 3(개)예요.","맞는 말이에요."]},{"stem":"나눈 조각을 뒤집어야 다른 조각과 겹친다면 두 조각은 합동이 아니에요.","answer":"X","reason_options":[{"t":"뒤집어서 겹쳐도 합동이므로","correct":true},{"t":"같은 방향으로 놓여야 합동이므로","mis":"M5-2-u3-X04"}],"explanation":["뒤집기는 모양과 크기를 바꾸지 않아요.","뒤집어 겹치면 합동이에요.","틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_basic#8','math',5,2,'u3','L10','g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',2,'sa','auto','정사각형 20개가 붙은 땅에 사과나무가 5그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C10","difficulty":2,"kind":"sa","stem":"정사각형 20개가 붙은 땅에 사과나무가 5그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나무가 한 그루씩이니 조각은 나무 수만큼 5개예요.","정사각형 20개를 5조각에 똑같이 나누어요.","20 ÷ 5 = 4(개)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"정사각형 15개가 붙은 땅에 사과나무가 5그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나무가 한 그루씩이니 조각은 나무 수만큼 5개예요.","정사각형 15개를 5조각에 똑같이 나누어요.","15 ÷ 5 = 3(개)예요."]},{"stem":"정사각형 24개가 붙은 땅에 사과나무가 6그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나무가 한 그루씩이니 조각은 나무 수만큼 6개예요.","정사각형 24개를 6조각에 똑같이 나누어요.","24 ÷ 6 = 4(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_basic#9','math',5,2,'u3','L10','g5_2_math_u3_L10_basic','lesson_basic','M5-2-u3-C10',2,'sa','auto','모양과 크기가 같은 정삼각형 12개가 붙어 있는 땅을 서로 합동인 도형 4개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C10","difficulty":2,"kind":"sa","stem":"모양과 크기가 같은 정삼각형 12개가 붙어 있는 땅을 서로 합동인 도형 4개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정삼각형의 개수도 같아요.","12개를 4조각에 똑같이 나누어요.","12 ÷ 4 = 3(개)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"모양과 크기가 같은 정삼각형 18개가 붙어 있는 땅을 서로 합동인 도형 3개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["합동인 조각들은 크기가 같아 정삼각형의 개수도 같아요.","18개를 3조각에 똑같이 나누어요.","18 ÷ 3 = 6(개)예요."]},{"stem":"모양과 크기가 같은 정삼각형 16개가 붙어 있는 땅을 서로 합동인 도형 4개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["합동인 조각들은 크기가 같아 정삼각형의 개수도 같아요.","16개를 4조각에 똑같이 나누어요.","16 ÷ 4 = 4(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
