INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_challenge#1','math',5,2,'u3','L10','g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',2,'sa','auto','모양과 크기가 같은 정사각형 20개가 붙어 있는 땅을 서로 합동인 도형 5개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C10","difficulty":2,"kind":"sa","stem":"모양과 크기가 같은 정사각형 20개가 붙어 있는 땅을 서로 합동인 도형 5개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","20개를 5조각에 똑같이 나누어요.","20 ÷ 5 = 4(개)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"모양과 크기가 같은 정사각형 24개가 붙어 있는 땅을 서로 합동인 도형 8개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","24개를 8조각에 똑같이 나누어요.","24 ÷ 8 = 3(개)예요."]},{"stem":"모양과 크기가 같은 정사각형 30개가 붙어 있는 땅을 서로 합동인 도형 6개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","30개를 6조각에 똑같이 나누어요.","30 ÷ 6 = 5(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_challenge#2','math',5,2,'u3','L10','g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',2,'sa','auto','나눈 한 조각은 한 변이 3 m인 정사각형 3개가 붙은 ㄱ자 모양이에요. 이 조각의 둘레는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C10","difficulty":2,"kind":"sa","stem":"나눈 한 조각은 한 변이 3 m인 정사각형 3개가 붙은 ㄱ자 모양이에요. 이 조각의 둘레는 몇 m인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["ㄱ자 모양의 둘레를 따라가면 정사각형 한 변이 8번 나와요.","모서리를 돌며 세면 2 + 1 + 1 + 1 + 1 + 2 = 8(번)이에요.","3 × 8 = 24(m)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"나눈 한 조각은 한 변이 7 m인 정사각형 3개가 붙은 ㄱ자 모양이에요. 이 조각의 둘레는 몇 m인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["ㄱ자 모양의 둘레를 따라가면 정사각형 한 변이 8번 나와요.","모서리를 돌며 세면 2 + 1 + 1 + 1 + 1 + 2 = 8(번)이에요.","7 × 8 = 56(m)예요."]},{"stem":"나눈 한 조각은 한 변이 9 m인 정사각형 3개가 붙은 ㄱ자 모양이에요. 이 조각의 둘레는 몇 m인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["ㄱ자 모양의 둘레를 따라가면 정사각형 한 변이 8번 나와요.","모서리를 돌며 세면 2 + 1 + 1 + 1 + 1 + 2 = 8(번)이에요.","9 × 8 = 72(m)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_challenge#3','math',5,2,'u3','L10','g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',3,'sa','auto','정사각형 12개가 붙은 땅을 그림처럼 일자 모양 네 조각으로 나누었어요. 점 ㄱ·ㄴ·ㄷ·ㄹ은 사과나무가 있는 자리예요. 사과나무가 한 그루도 없는 조각은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u3-C10","difficulty":3,"kind":"sa","stem":"정사각형 12개가 붙은 땅을 그림처럼 일자 모양 네 조각으로 나누었어요. 점 ㄱ·ㄴ·ㄷ·ㄹ은 사과나무가 있는 자리예요. 사과나무가 한 그루도 없는 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["왼쪽 조각부터 나무 수를 세면 0, 2, 1, 1그루예요.","나무가 없는 조각은 1개예요.","조각끼리는 합동이어도 나무 조건이 어긋나 바르게 나눈 것이 아니에요."],"mis":"M5-2-u3-X16","asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[60.0,20.0,"ne"],"ㄴ":[60.0,100.0,"ne"],"ㄷ":[140.0,60.0,"ne"],"ㄹ":[100.0,60.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 정사각형 12개가 붙은 땅을 그림처럼 일자 모양 네 조각으로 나누었어요. 점 ㄱ·ㄴ·ㄷ·ㄹ은 사과나무가 있는 자리예요. 사과나무가 한 그루도 없는 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["왼쪽 조각부터 나무 수를 세면 2, 0, 0, 2그루예요.","나무가 없는 조각은 2개예요.","조각끼리는 합동이어도 나무 조건이 어긋나 바르게 나눈 것이 아니에요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[140.0,20.0,"ne"],"ㄷ":[20.0,100.0,"ne"],"ㄹ":[140.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40}],"tag":false}},{"stem":"이번에는 다른 보기예요. 정사각형 12개가 붙은 땅을 그림처럼 일자 모양 네 조각으로 나누었어요. 점 ㄱ·ㄴ·ㄷ·ㄹ은 사과나무가 있는 자리예요. 사과나무가 한 그루도 없는 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["왼쪽 조각부터 나무 수를 세면 1, 1, 2, 0그루예요.","나무가 없는 조각은 1개예요.","조각끼리는 합동이어도 나무 조건이 어긋나 바르게 나눈 것이 아니에요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[60.0,60.0,"ne"],"ㄷ":[100.0,20.0,"ne"],"ㄹ":[100.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_challenge#4','math',5,2,'u3','L10','g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',3,'mc','auto','사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X02']::text[],true,'{"seq":4,"concept":"M5-2-u3-C10","difficulty":3,"kind":"mc","stem":"사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 일자 조각 넷, ㉯는 ㄱ자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 0, 2, 1, 1, ㉯ 1, 1, 1, 1그루예요.","나무가 한 그루씩인 것은 ㉯예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[60.0,20.0,"ne"],"ㄴ":[60.0,100.0,"ne"],"ㄷ":[140.0,60.0,"ne"],"ㄹ":[100.0,60.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40},{"w":160,"h":120,"pts":{"ㅁ":[60.0,20.0,"ne"],"ㅂ":[60.0,100.0,"ne"],"ㅅ":[140.0,60.0,"ne"],"ㅇ":[100.0,60.0,"ne"]},"poly":[[[0,0],[80,0],[80,40],[40,40],[40,80],[0,80]],[[80,0],[160,0],[160,80],[120,80],[120,40],[80,40]],[[40,40],[80,40],[80,120],[0,120],[0,80],[40,80]],[[80,40],[120,40],[120,80],[160,80],[160,120],[80,120]]],"grid":40}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 일자 조각 넷, ㉯는 ㄱ자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 2, 0, 0, 2, ㉯ 1, 1, 1, 1그루예요.","나무가 한 그루씩인 것은 ㉯예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[140.0,20.0,"ne"],"ㄷ":[20.0,100.0,"ne"],"ㄹ":[140.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40},{"w":160,"h":120,"pts":{"ㅁ":[20.0,20.0,"ne"],"ㅂ":[140.0,20.0,"ne"],"ㅅ":[20.0,100.0,"ne"],"ㅇ":[140.0,100.0,"ne"]},"poly":[[[0,0],[80,0],[80,40],[40,40],[40,80],[0,80]],[[80,0],[160,0],[160,80],[120,80],[120,40],[80,40]],[[40,40],[80,40],[80,120],[0,120],[0,80],[40,80]],[[80,40],[120,40],[120,80],[160,80],[160,120],[80,120]]],"grid":40}]}},{"stem":"이번에는 다른 보기예요. 사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 ㄱ자 조각 넷, ㉯는 일자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 1, 1, 1, 1, ㉯ 1, 1, 2, 0그루예요.","나무가 한 그루씩인 것은 ㉮예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[60.0,60.0,"ne"],"ㄷ":[100.0,20.0,"ne"],"ㄹ":[100.0,100.0,"ne"]},"poly":[[[0,0],[80,0],[80,40],[40,40],[40,80],[0,80]],[[80,0],[160,0],[160,80],[120,80],[120,40],[80,40]],[[40,40],[80,40],[80,120],[0,120],[0,80],[40,80]],[[80,40],[120,40],[120,80],[160,80],[160,120],[80,120]]],"grid":40},{"w":160,"h":120,"pts":{"ㅁ":[20.0,20.0,"ne"],"ㅂ":[60.0,60.0,"ne"],"ㅅ":[100.0,20.0,"ne"],"ㅇ":[100.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_challenge#5','math',5,2,'u3','L10','g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',3,'ox','auto','땅을 합동인 네 조각으로 나누었어도 나무가 두 그루인 조각이 있으면 조건에 맞지 않아요.',ARRAY['M5-2-u3-X16']::text[],true,'{"seq":5,"concept":"M5-2-u3-C10","difficulty":3,"kind":"ox","stem":"땅을 합동인 네 조각으로 나누었어도 나무가 두 그루인 조각이 있으면 조건에 맞지 않아요.","answer":"O","reason_options":[{"t":"조각마다 나무가 한 그루씩이어야 하므로","correct":true},{"t":"합동이기만 하면 되므로","mis":"M5-2-u3-X16"}],"mis":"M5-2-u3-X16","explanation":["조건은 두 가지예요 — 합동, 나무 한 그루씩.","나무가 두 그루인 조각이 있으면 두 번째 조건이 어긋나요.","맞는 말이에요."],"variant_rule":{"alt":[{"stem":"정사각형 12개를 넓이가 같은 네 조각으로 나누면 언제나 똑같이 나눈 것이에요.","answer":"X","reason_options":[{"t":"넓이가 같아도 모양이 달라 겹치지 않으면 합동이 아니므로","correct":true},{"t":"넓이가 같으면 늘 합동이므로","mis":"M5-2-u3-X05"}],"explanation":["일자 조각과 ㄱ자 조각은 넓이가 같아요.","그런데 포개도 겹치지 않아요.","그래서 틀린 말이에요."]},{"stem":"나눈 조각을 뒤집어야 다른 조각과 겹친다면 두 조각은 합동이 아니에요.","answer":"X","reason_options":[{"t":"뒤집어서 겹쳐도 합동이므로","correct":true},{"t":"같은 방향으로 놓여야 합동이므로","mis":"M5-2-u3-X04"}],"explanation":["뒤집기는 모양과 크기를 바꾸지 않아요.","뒤집어 겹치면 합동이에요.","틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_challenge#6','math',5,2,'u3','L10','g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',3,'sa','auto','정사각형 28개가 붙은 땅에 사과나무가 7그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C10","difficulty":3,"kind":"sa","stem":"정사각형 28개가 붙은 땅에 사과나무가 7그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나무가 한 그루씩이니 조각은 나무 수만큼 7개예요.","정사각형 28개를 7조각에 똑같이 나누어요.","28 ÷ 7 = 4(개)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"정사각형 36개가 붙은 땅에 사과나무가 9그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나무가 한 그루씩이니 조각은 나무 수만큼 9개예요.","정사각형 36개를 9조각에 똑같이 나누어요.","36 ÷ 9 = 4(개)예요."]},{"stem":"정사각형 32개가 붙은 땅에 사과나무가 8그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나무가 한 그루씩이니 조각은 나무 수만큼 8개예요.","정사각형 32개를 8조각에 똑같이 나누어요.","32 ÷ 8 = 4(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_challenge#7','math',5,2,'u3','L10','g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',3,'sa','auto','모양과 크기가 같은 정삼각형 24개가 붙어 있는 땅을 서로 합동인 도형 6개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u3-C10","difficulty":3,"kind":"sa","stem":"모양과 크기가 같은 정삼각형 24개가 붙어 있는 땅을 서로 합동인 도형 6개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["합동인 조각들은 크기가 같아 정삼각형의 개수도 같아요.","24개를 6조각에 똑같이 나누어요.","24 ÷ 6 = 4(개)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"모양과 크기가 같은 정삼각형 30개가 붙어 있는 땅을 서로 합동인 도형 5개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["합동인 조각들은 크기가 같아 정삼각형의 개수도 같아요.","30개를 5조각에 똑같이 나누어요.","30 ÷ 5 = 6(개)예요."]},{"stem":"모양과 크기가 같은 정삼각형 36개가 붙어 있는 땅을 서로 합동인 도형 4개로 나누려고 해요. 한 도형은 정삼각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["합동인 조각들은 크기가 같아 정삼각형의 개수도 같아요.","36개를 4조각에 똑같이 나누어요.","36 ÷ 4 = 9(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_challenge#8','math',5,2,'u3','L10','g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',4,'sa','auto','가로 6칸, 세로 4칸인 직사각형 모양 땅(칸 하나는 정사각형)에 사과나무가 8그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C10","difficulty":4,"kind":"sa","stem":"가로 6칸, 세로 4칸인 직사각형 모양 땅(칸 하나는 정사각형)에 사과나무가 8그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["땅의 정사각형은 6 × 4 = 24(개)예요.","나무가 한 그루씩이니 조각은 8개예요.","24 ÷ 8 = 3(개)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"가로 5칸, 세로 6칸인 직사각형 모양 땅(칸 하나는 정사각형)에 사과나무가 6그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["땅의 정사각형은 5 × 6 = 30(개)예요.","나무가 한 그루씩이니 조각은 6개예요.","30 ÷ 6 = 5(개)예요."]},{"stem":"가로 8칸, 세로 3칸인 직사각형 모양 땅(칸 하나는 정사각형)에 사과나무가 4그루 있어요. 나무가 한 그루씩 들어가도록 서로 합동인 도형으로 나누면, 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["땅의 정사각형은 8 × 3 = 24(개)예요.","나무가 한 그루씩이니 조각은 4개예요.","24 ÷ 4 = 6(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_challenge#9','math',5,2,'u3','L10','g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',4,'sa','auto','어떤 땅을 정사각형 4개가 붙은 합동인 도형 9개로 남김없이 나누었더니 조각마다 사과나무가 1그루씩 들어갔어요. 땅 전체는 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u3-C10","difficulty":4,"kind":"sa","stem":"어떤 땅을 정사각형 4개가 붙은 합동인 도형 9개로 남김없이 나누었더니 조각마다 사과나무가 1그루씩 들어갔어요. 땅 전체는 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["합동인 조각은 정사각형 수가 모두 4개예요.","조각이 9개이니 4 × 9 = 36(개)예요.","나무 수(1그루씩)는 땅의 넓이와 상관없어요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"어떤 땅을 정사각형 6개가 붙은 합동인 도형 7개로 남김없이 나누었더니 조각마다 사과나무가 2그루씩 들어갔어요. 땅 전체는 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["합동인 조각은 정사각형 수가 모두 6개예요.","조각이 7개이니 6 × 7 = 42(개)예요.","나무 수(2그루씩)는 땅의 넓이와 상관없어요."]},{"stem":"어떤 땅을 정사각형 5개가 붙은 합동인 도형 8개로 남김없이 나누었더니 조각마다 사과나무가 1그루씩 들어갔어요. 땅 전체는 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["합동인 조각은 정사각형 수가 모두 5개예요.","조각이 8개이니 5 × 8 = 40(개)예요.","나무 수(1그루씩)는 땅의 넓이와 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L10_challenge#10','math',5,2,'u3','L10','g5_2_math_u3_L10_challenge','lesson_challenge','M5-2-u3-C10',4,'essay','teacher','사과나무 4그루가 있는, 정사각형 12개가 붙은 땅을 학생들에게 똑같이 나누어 주려고 해요(조건: 합동인 도형 4개, 조각마다 사과나무 한 그루). 한 조각이 정사각형 몇 개인지 구하는 방법을 쓰고, 일자 모양 조각과 ㄱ자 모양 조각을 섞어 나누면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u3-C10","difficulty":4,"kind":"essay","stem":"사과나무 4그루가 있는, 정사각형 12개가 붙은 땅을 학생들에게 똑같이 나누어 주려고 해요(조건: 합동인 도형 4개, 조각마다 사과나무 한 그루). 한 조각이 정사각형 몇 개인지 구하는 방법을 쓰고, 일자 모양 조각과 ㄱ자 모양 조각을 섞어 나누면 안 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 합동인 조각은 크기가 같으므로 12 ÷ 4 = 3, 한 조각은 정사각형 3개이다. 정사각형 3개로 된 모양은 일자 모양과 ㄱ자 모양 두 가지인데, 두 모양은 넓이는 같아도 포개면 겹치지 않아 합동이 아니다. 조각들이 서로 합동이어야 똑같이 나눈 것이므로 한 가지 모양으로만 나누어야 하고, 마지막에 조각마다 나무가 한 그루씩인지 확인한다.","scoring_points":["12 ÷ 4 = 3(개)을 구했는가","일자·ㄱ자는 넓이가 같아도 합동이 아니라고 썼는가","한 가지 모양으로 나누고 나무 조건을 확인한다고 썼는가"]},"explanation":["12 ÷ 4 = 3(개)이에요.","일자와 ㄱ자는 합동이 아니에요.","한 가지 모양으로 나누고 나무를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#1','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C1',1,'sa','auto','한 변이 9 cm인 정사각형을 시계 방향으로 반 바퀴 돌렸을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C1","difficulty":1,"kind":"sa","stem":"한 변이 9 cm인 정사각형을 시계 방향으로 반 바퀴 돌렸을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["돌리기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 9 cm예요."],"mis":"M5-2-u3-X01","variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 5 cm인 직사각형을 왼쪽으로 뒤집었을 때, 움직인 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["뒤집기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 5 cm예요."]},{"stem":"한 변이 6 cm인 정사각형을 오른쪽으로 5칸 밀었을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["밀기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#2','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C2',1,'sa','auto','한 변이 5 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C2","difficulty":1,"kind":"sa","stem":"한 변이 5 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 5 cm예요.","둘레는 5 × 4 = 20(cm)예요."],"mis":"M5-2-u3-X03","variant_rule":{"alt":[{"stem":"한 변이 6 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 6 cm예요.","둘레는 6 × 4 = 24(cm)예요."]},{"stem":"한 변이 8 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 8 cm예요.","둘레는 8 × 4 = 32(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#3','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C3',1,'sa','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄴ이 85°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u3-C3","difficulty":1,"kind":"sa","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄴ이 85°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["점 ㄴ의 대응점은 점 ㅂ이에요.","각 ㄴ과 각 ㅂ은 대응각이에요.","대응각의 크기는 같으므로 85°예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄱ이 65°일 때 각 ㅁ은 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["점 ㄱ의 대응점은 점 ㅁ이에요.","각 ㄱ과 각 ㅁ은 대응각이에요.","대응각의 크기는 같으므로 65°예요."]},{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄹ이 90°일 때 각 ㅇ은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["점 ㄹ의 대응점은 점 ㅇ이에요.","각 ㄹ과 각 ㅇ은 대응각이에요.","대응각의 크기는 같으므로 90°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#4','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C4',1,'sa','auto','직사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C4","difficulty":1,"kind":"sa","stem":"직사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","세로로, 가로로 접으면 겹쳐요 — 대각선으로는 겹치지 않아요.","그래서 직사각형의 대칭축은 2개예요."],"mis":"M5-2-u3-X08","asset":{"type":"geo","items":[{"w":100,"h":60,"poly":[[[0,0],[100,0],[100,60],[0,60]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","세로·가로·두 대각선으로 접으면 겹쳐요.","그래서 정사각형의 대칭축은 4개예요."],"asset":{"type":"geo","items":[{"w":80,"h":80,"poly":[[[0,0],[80,0],[80,80],[0,80]]]}],"tag":false}},{"stem":"마름모의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","두 대각선으로 접으면 겹쳐요 — 세로·가로가 아니라 대각선이에요.","그래서 마름모의 대칭축은 2개예요."],"asset":{"type":"geo","items":[{"w":100,"h":80,"poly":[[[50.0,0],[100,40],[50.0,80],[0,40]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#5','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C5',1,'sa','auto','선대칭도형에서 대칭축에서 한 대응점까지의 거리가 4 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u3-C5","difficulty":1,"kind":"sa","stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 4 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 4 cm예요.","4 + 4 = 8(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 6 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 6 cm예요.","6 + 6 = 12(cm)예요."]},{"stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 8 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 8 cm예요.","8 + 8 = 16(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#6','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C6',1,'sa','auto','선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 3칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C6","difficulty":1,"kind":"sa","stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 3칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대응점은 반대쪽으로 3칸 간 자리예요.","꼭짓점에서 대칭축까지 3칸, 대칭축에서 대응점까지 3칸이에요.","3 + 3 = 6(칸)이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 5칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["대응점은 반대쪽으로 5칸 간 자리예요.","꼭짓점에서 대칭축까지 5칸, 대칭축에서 대응점까지 5칸이에요.","5 + 5 = 10(칸)이에요."]},{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 4칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대응점은 반대쪽으로 4칸 간 자리예요.","꼭짓점에서 대칭축까지 4칸, 대칭축에서 대응점까지 4칸이에요.","4 + 4 = 8(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#7','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C7',1,'mc','auto','점대칭도형인 평행사변형에서 대칭의 중심은 몇 개인가요?',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":7,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"점대칭도형인 평행사변형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."],"variant_rule":{"alt":[{"stem":"점대칭도형인 정사각형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]},{"stem":"점대칭도형인 마름모에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#8','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C8',1,'sa','auto','점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 5 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C8","difficulty":1,"kind":"sa","stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 5 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 5 cm예요.","5 + 5 = 10(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 7 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 7 cm예요.","7 + 7 = 14(cm)예요."]},{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 3 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 3 cm예요.","3 + 3 = 6(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
