INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#12','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C5',2,'sa','auto','오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄷㄹ이 6 cm일 때, 변 ㄱㅁ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M5-2-u3-C5","difficulty":2,"kind":"sa","stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄷㄹ이 6 cm일 때, 변 ㄱㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["점 ㄷ ↔ 점 ㄱ, 점 ㄹ ↔ 점 ㅁ이 대응점이에요.","그래서 변 ㄷㄹ과 변 ㄱㅁ은 대응변이에요.","대응변의 길이는 같으므로 6 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㅂ이 5 cm일 때, 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["점 ㄱ ↔ 점 ㄴ, 점 ㅂ ↔ 점 ㄷ이 대응점이에요.","그래서 변 ㄱㅂ과 변 ㄴㄷ은 대응변이에요.","대응변의 길이는 같으므로 5 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false}},{"stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄴㄷ이 3 cm일 때, 변 ㅂㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㄴ ↔ 점 ㅂ, 점 ㄷ ↔ 점 ㅁ이 대응점이에요.","그래서 변 ㄴㄷ과 변 ㅂㅁ은 대응변이에요.","대응변의 길이는 같으므로 3 cm예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#13','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C6',2,'mc','auto','모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":13,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 3칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 3칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":160.0,"pts":{"ㄱ":[20,70.0,"w"],"ㄴ":[160,70.0,"e"],"ㄷ":[140,70.0,"e"],"ㄹ":[140,50.0,"e"]},"seg":[[[80,20.0],[80,140.0]],[[80,30.0],[20,70.0]],[[20,70.0],[60,110.0]],[[60,110.0],[80,130.0]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 2칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 2칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":140.0,"pts":{"ㄱ":[60,50.0,"w"],"ㄴ":[140,50.0,"e"],"ㄷ":[140,30.0,"e"],"ㄹ":[160,50.0,"e"]},"seg":[[[100,20.0],[100,120.0]],[[100,30.0],[60,50.0]],[[60,50.0],[20,90.0]],[[20,90.0],[100,110.0]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 4칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 4칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄹ이에요."],"asset":{"type":"geo","items":[{"w":220,"h":160.0,"pts":{"ㄱ":[20,90.0,"w"],"ㄴ":[180,70.0,"e"],"ㄷ":[200,90.0,"e"],"ㄹ":[180,90.0,"e"]},"seg":[[[100,20.0],[100,140.0]],[[100,30.0],[20,90.0]],[[20,90.0],[60,50.0]],[[60,50.0],[100,130.0]]],"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#14','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C7',2,'sa','auto','평행사변형, 정삼각형, 직사각형, 직각사다리꼴 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M5-2-u3-C7","difficulty":2,"kind":"sa","stem":"평행사변형, 정삼각형, 직사각형, 직각사다리꼴 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","평행사변형 ○, 정삼각형 ×, 직사각형 ○, 직각사다리꼴 ×예요.","점대칭도형은 2개예요."],"mis":"M5-2-u3-X14","variant_rule":{"alt":[{"stem":"마름모, 이등변삼각형, 정사각형, 정육각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","마름모 ○, 이등변삼각형 ×, 정사각형 ○, 정육각형 ○예요.","점대칭도형은 3개예요."]},{"stem":"ㄱ자 모양, 십자 모양, 평행사변형, 정오각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","ㄱ자 모양 ×, 십자 모양 ○, 평행사변형 ○, 정오각형 ×예요.","점대칭도형은 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
