INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#20','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C6',3,'mc','auto','모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":20,"concept":"M5-2-u3-C6","difficulty":3,"kind":"mc","stem":"모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄴ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄷ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":160,"h":160,"pts":{"ㄱ":[40,80,"nw"],"ㄴ":[120,80,"se"],"ㄷ":[80,40,"se"],"ㄹ":[100,20,"se"]},"seg":[[[20,20],[140,140]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄹ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄴ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":180,"h":180,"pts":{"ㄱ":[60,100,"nw"],"ㄴ":[100,60,"se"],"ㄷ":[120,40,"se"],"ㄹ":[140,100,"se"]},"seg":[[[20,20],[160,160]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄷ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄹ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":200,"h":200,"pts":{"ㄱ":[40,100,"nw"],"ㄴ":[120,20,"se"],"ㄷ":[160,100,"se"],"ㄹ":[100,40,"