INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#21','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C9',3,'mc','auto','모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13']::text[],true,'{"seq":21,"concept":"M5-2-u3-C9","difficulty":3,"kind":"mc","stem":"모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 2칸, 위 1칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 2칸, 위 1칸) 대응점이에요.","그래서 점 ㄴ이에요 — 점 ㄹ·ㄷ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":120,"h":80,"pts":{"ㄱ":[100,60,"ne"],"ㅇ":[60,40,"ne"],"ㄴ":[20,20,"ne"],"ㄷ":[100,20,"ne"],"ㄹ":[20,60,"ne"]},"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 2칸, 위 3칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 2칸, 위 3칸) 대응점이에요.","그래서 점 ㄷ이에요 — 점 ㄴ·ㄹ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":120,"h":160,"pts":{"ㄱ":[20,140,"ne"],"ㅇ":[60,80,"ne"],"ㄴ":[100,140,"ne"],"ㄷ":[100,20,"ne"],"ㄹ":[20,20,"ne"]},"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 3칸, 아래 2칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 3칸, 아래 2칸) 대응점이에요.","그래서 점 ㄹ이에요 — 점 ㄷ·ㄴ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[140,20,"ne"],"ㅇ":[80,60,"ne"],"ㄴ":[140,100,"ne"],"ㄷ":[20,20,"ne"],"ㄹ":[20,100,"ne"]},"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#22','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C10',3,'mc','auto','사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X02']::text[],true,'{"seq":22,"concept":"M5-2-u3-C10","difficulty":3,"kind":"mc","stem":"사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 일자 조각 넷, ㉯는 ㄱ자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 2, 0, 0, 2, ㉯ 1, 1, 1, 1그루예요.","나무가 한 그루씩인 것은 ㉯예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[140.0,20.0,"ne"],"ㄷ":[20.0,100.0,"ne"],"ㄹ":[140.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40},{"w":160,"h":120,"pts":{"ㅁ":[20.0,20.0,"ne"],"ㅂ":[140.0,20.0,"ne"],"ㅅ":[20.0,100.0,"ne"],"ㅇ":[140.0,100.0,"ne"]},"poly":[[[0,0],[80,0],[80,40],[40,40],[40,80],[0,80]],[[80,0],[160,0],[160,80],[120,80],[120,40],[80,40]],[[40,40],[80,40],[80,120],[0,120],[0,80],[40,80]],[[80,40],[120,40],[120,80],[160,80],[160,120],[80,120]]],"grid":40}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 ㄱ자 조각 넷, ㉯는 일자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 1, 1, 1, 1, ㉯ 1, 1, 2, 0그루예요.","나무가 한 그루씩인 것은 ㉮예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[60.0,60.0,"ne"],"ㄷ":[100.0,20.0,"ne"],"