INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#23','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C4',4,'essay','teacher','십자 모양(정사각형 5개를 십자로 붙인 모양)의 대칭축은 몇 개인지 쓰고, 십자 모양이 점대칭도형이기도 한지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u3-C4","difficulty":4,"kind":"essay","stem":"십자 모양(정사각형 5개를 십자로 붙인 모양)의 대칭축은 몇 개인지 쓰고, 십자 모양이 점대칭도형이기도 한지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 십자 모양은 세로로 접어도, 가로로 접어도, 두 대각선으로 접어도 완전히 겹치므로 대칭축이 4개이다. 또 가운데 정사각형의 한가운데 점을 중심으로 반 바퀴 돌려도 완전히 겹치므로 점대칭도형이기도 하다.","scoring_points":["대칭축 4개를 찾았는가","반 바퀴 돌려 겹친다고 썼는가","선대칭도형이면서 점대칭도형이라고 썼는가"]},"explanation":["세로·가로·두 대각선 — 대칭축 4개예요.","반 바퀴 돌려도 겹쳐요.","선대칭도형이면서 점대칭도형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#24','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C3',4,'essay','teacher','삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 변 ㄱㄴ 5 cm, 변 ㄴㄷ 7 cm, 변 ㄷㄱ 6 cm이고 각 ㄱ 60°, 각 ㄴ 50°일 때 삼각형 ㄹㅁㅂ의 둘레와 각 ㅂ의 크기를 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u3-C3","difficulty":4,"kind":"essay","stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 변 ㄱㄴ 5 cm, 변 ㄴㄷ 7 cm, 변 ㄷㄱ 6 cm이고 각 ㄱ 60°, 각 ㄴ 50°일 때 삼각형 ㄹㅁㅂ의 둘레와 각 ㅂ의 크기를 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 합동인 두 삼각형은 대응변의 길이가 같으므로 삼각형 ㄹㅁㅂ의 둘레는 5 + 7 + 6 = 18(cm)이다. 삼각형 ㄱㄴㄷ에서 각 ㄷ = 180 − 60 − 50 = 70(°)이고, 각 ㅂ은 각 ㄷ의 대응각이므로 70°이다.","scoring_points":["둘레 18 cm를 구했는가","각 ㄷ = 70°를 구했는가","각 ㅂ이 각 ㄷ의 대응각이라 70°라고 썼는가"]},"explanation":["5 + 7 + 6 = 18(cm)이에요.","각 ㄷ = 180 − 60 − 50 = 70(°)이에요.","각 ㅂ은 각 ㄷ의 대응각 — 70°예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_a#25','math',5,2,'u3','','g5_2_math_u3_review_a','unit_review','M5-2-u3-C4',4,'mc','auto','대칭축이 가장 많은 도형은 어느 것인가요?',ARRAY['M5-2-u3-X08']::text[],true,'{"seq":25,"concept":"M5-2-u3-C4","difficulty":4,"kind":"mc","stem":"대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정사각형","correct":true},{"t":"정삼각형","mis":"M5-2-u3-X08"},{"t":"직사각형","mis":"M5-2-u3-X08"},{"t":"이등변삼각형","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정사각형 4개, 정삼각형 3개, 직사각형 2개, 이등변삼각형 1개예요.","가장 많은 것은 정사각형이에요"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정육각형","correct":true},{"t":"마름모","mis":"M5-2-u3-X08"},{"t":"정오각형","mis":"M5-2-u3-X08"},{"t":"직사각형","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","마름모 2개, 정육각형 6개, 정오각형 5개, 직사각형 2개예요.","가장 많은 것은 정육각형이에요"]},{"stem":"이번에는 다른 보기예요. 대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정오각형","correct":true},{"t":"십자 모양","mis":"M5-2-u3-X08"},{"t":"정삼각형","mis":"M5-2-u3-X08"},{"t":"ㄱ자 모양","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정오각형 5개, 십자 모양 4개, 정삼각형 3개, ㄱ자 모양 1개예요.","가장 많은 것은 정오각형이에요"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#1','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C1',1,'sa','auto','가로 8 cm, 세로 5 cm인 직사각형을 왼쪽으로 뒤집었을 때, 움직인 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C1","difficulty":1,"kind":"sa","stem":"가로 8 cm, 세로 5 cm인 직사각형을 왼쪽으로 뒤집었을 때, 움직인 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["뒤집기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 5 cm예요."],"mis":"M5-2-u3-X01","variant_rule":{"alt":[{"stem":"한 변이 6 cm인 정사각형을 오른쪽으로 5칸 밀었을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["밀기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 6 cm예요."]},{"stem":"가로 7 cm, 세로 4 cm인 직사각형을 시계 방향으로 반 바퀴 돌렸을 때, 움직인 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["돌리기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#2','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C2',1,'sa','auto','한 변이 6 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C2","difficulty":1,"kind":"sa","stem":"한 변이 6 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 6 cm예요.","둘레는 6 × 4 = 24(cm)예요."],"mis":"M5-2-u3-X03","variant_rule":{"alt":[{"stem":"한 변이 8 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 8 cm예요.","둘레는 8 × 4 = 32(cm)예요."]},{"stem":"한 변이 3 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 3 cm예요.","둘레는 3 × 4 = 12(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#3','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C3',1,'sa','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄱ이 65°일 때 각 ㅁ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u3-C3","difficulty":1,"kind":"sa","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄱ이 65°일 때 각 ㅁ은 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["점 ㄱ의 대응점은 점 ㅁ이에요.","각 ㄱ과 각 ㅁ은 대응각이에요.","대응각의 크기는 같으므로 65°예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄹ이 90°일 때 각 ㅇ은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["점 ㄹ의 대응점은 점 ㅇ이에요.","각 ㄹ과 각 ㅇ은 대응각이에요.","대응각의 크기는 같으므로 90°예요."]},{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄷ이 55°일 때 각 ㅅ은 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["점 ㄷ의 대응점은 점 ㅅ이에요.","각 ㄷ과 각 ㅅ은 대응각이에요.","대응각의 크기는 같으므로 55°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#4','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C4',1,'sa','auto','정사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C4","difficulty":1,"kind":"sa","stem":"정사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","세로·가로·두 대각선으로 접으면 겹쳐요.","그래서 정사각형의 대칭축은 4개예요."],"mis":"M5-2-u3-X08","asset":{"type":"geo","items":[{"w":80,"h":80,"poly":[[[0,0],[80,0],[80,80],[0,80]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"마름모의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","두 대각선으로 접으면 겹쳐요 — 세로·가로가 아니라 대각선이에요.","그래서 마름모의 대칭축은 2개예요."],"asset":{"type":"geo","items":[{"w":100,"h":80,"poly":[[[50.0,0],[100,40],[50.0,80],[0,40]]]}],"tag":false}},{"stem":"정삼각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","각 꼭짓점에서 마주 보는 변의 가운데로 내린 선 3개로 접혀요.","그래서 정삼각형의 대칭축은 3개예요."],"asset":{"type":"geo","items":[{"w":80,"h":69.2,"poly":[[[0,69.2],[40,0],[80,69.2]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#5','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C5',1,'sa','auto','선대칭도형에서 대칭축에서 한 대응점까지의 거리가 6 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u3-C5","difficulty":1,"kind":"sa","stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 6 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 6 cm예요.","6 + 6 = 12(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 8 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 8 cm예요.","8 + 8 = 16(cm)예요."]},{"stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 9 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 9 cm예요.","9 + 9 = 18(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#6','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C6',1,'sa','auto','선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 5칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C6","difficulty":1,"kind":"sa","stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 5칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["대응점은 반대쪽으로 5칸 간 자리예요.","꼭짓점에서 대칭축까지 5칸, 대칭축에서 대응점까지 5칸이에요.","5 + 5 = 10(칸)이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 4칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대응점은 반대쪽으로 4칸 간 자리예요.","꼭짓점에서 대칭축까지 4칸, 대칭축에서 대응점까지 4칸이에요.","4 + 4 = 8(칸)이에요."]},{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 6칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["대응점은 반대쪽으로 6칸 간 자리예요.","꼭짓점에서 대칭축까지 6칸, 대칭축에서 대응점까지 6칸이에요.","6 + 6 = 12(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#7','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C7',1,'mc','auto','점대칭도형인 정사각형에서 대칭의 중심은 몇 개인가요?',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":7,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"점대칭도형인 정사각형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."],"variant_rule":{"alt":[{"stem":"점대칭도형인 마름모에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]},{"stem":"점대칭도형인 정육각형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#8','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C8',1,'sa','auto','점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 7 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C8","difficulty":1,"kind":"sa","stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 7 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 7 cm예요.","7 + 7 = 14(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 3 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 3 cm예요.","3 + 3 = 6(cm)예요."]},{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 8 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 8 cm예요.","8 + 8 = 16(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
