INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#10','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C3',2,'mc','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 점 ㄱ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X07']::text[],true,'{"seq":10,"concept":"M5-2-u3-C3","difficulty":2,"kind":"mc","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 점 ㄱ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅇ","correct":true},{"t":"점 ㅁ","mis":"M5-2-u3-X06"},{"t":"점 ㅂ","mis":"M5-2-u3-X07"},{"t":"점 ㅅ","mis":"M5-2-u3-X07"}],"explanation":["대응점은 두 도형을 포개었을 때 겹치는 점이에요.","그림에서 오른쪽 도형을 뒤집어 왼쪽 도형에 포개면 점 ㄱ과 점 ㅇ이 겹쳐요.","이름 차례(ㄱ ↔ ㅁ)로 짝짓지 않아요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[300,0,"ne"],"ㅅ":[240,0,"n"],"ㅂ":[180,80,"sw"],"ㅁ":[300,80,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅇ","ㅅ","ㅂ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 점 ㄷ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㅅ","mis":"M5-2-u3-X06"},{"t":"점 ㅂ","mis":"M5-2-u3-X07"},{"t":"점 ㅇ","mis":"M5-2-u3-X07"}],"explanation":["대응점은 두 도형을 포개었을 때 겹치는 점이에요.","그림에서 오른쪽 도형을 위아래로 뒤집어 왼쪽 도형에 포개면 점 ㄷ과 점 ㅁ이 겹쳐요.","이름 차례(ㄷ ↔ ㅅ)로 짝짓지 않아요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0,"n"],"ㄷ":[120,80,"se"],"ㄹ":[0,80,"sw"],"ㅅ":[180,80,"sw"],"ㅂ":[240,80,"s"],"ㅁ":[300,0,"ne"],"ㅇ":[180,0,"nw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"],["ㅅ","ㅂ","ㅁ","ㅇ"]]}],"tag":false}},{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이에요. 점 ㄹ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㅇ","mis":"M5-2-u3-X06"},{"t":"점 ㅂ","mis":"M5-2-u3-X07"},{"t":"점 ㅅ","mis":"M5-2-u3-X07"}],"explanation":["대응점은 두 도형을 포개었을 때 겹치는 점이에요.","그림에서 오른쪽 도형을 반 바퀴 돌려 왼쪽 도형에 포개면 점 ㄹ과 점 ㅁ이 겹쳐요.","이름 차례(ㄹ ↔ ㅇ)로 짝짓지 않아요."],"asset":{"type":"geo","items":[{"w":300,"h":80,"pts":{"ㄱ":[0,0,"nw"],"ㄴ":[60,0