INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#12','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C5',2,'sa','auto','육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㅂ이 5 cm일 때, 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M5-2-u3-C5","difficulty":2,"kind":"sa","stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄱㅂ이 5 cm일 때, 변 ㄴㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["점 ㄱ ↔ 점 ㄴ, 점 ㅂ ↔ 점 ㄷ이 대응점이에요.","그래서 변 ㄱㅂ과 변 ㄴㄷ은 대응변이에요.","대응변의 길이는 같으므로 5 cm예요."],"mis":"M5-2-u3-X07","asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄴㄷ이 3 cm일 때, 변 ㅂㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㄴ ↔ 점 ㅂ, 점 ㄷ ↔ 점 ㅁ이 대응점이에요.","그래서 변 ㄴㄷ과 변 ㅂㅁ은 대응변이에요.","대응변의 길이는 같으므로 3 cm예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]]]}],"tag":false}},{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 변 ㄷㄹ이 8 cm일 때, 변 ㅂㅁ은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["점 ㄷ ↔ 점 ㅂ, 점 ㄹ ↔ 점 ㅁ이 대응점이에요.","그래서 변 ㄷㄹ과 변 ㅂㅁ은 대응변이에요.","대응변의 길이는 같으므로 8 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code