INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#16','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C10',2,'sa','auto','모양과 크기가 같은 정사각형 15개가 붙어 있는 땅을 서로 합동인 도형 5개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M5-2-u3-C10","difficulty":2,"kind":"sa","stem":"모양과 크기가 같은 정사각형 15개가 붙어 있는 땅을 서로 합동인 도형 5개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","15개를 5조각에 똑같이 나누어요.","15 ÷ 5 = 3(개)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"모양과 크기가 같은 정사각형 18개가 붙어 있는 땅을 서로 합동인 도형 6개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","18개를 6조각에 똑같이 나누어요.","18 ÷ 6 = 3(개)예요."]},{"stem":"모양과 크기가 같은 정사각형 21개가 붙어 있는 땅을 서로 합동인 도형 7개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","21개를 7조각에 똑같이 나누어요.","21 ÷ 7 = 3(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#17','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C3',3,'sa','auto','삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 55°, 각 ㄴ이 65°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M5-2-u3-C3","difficulty":3,"kind":"sa","stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 55°, 각 ㄴ이 65°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 55 − 65 = 60(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 60°예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 75°, 각 ㄴ이 45°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 75 − 45 = 60(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 60°예요."]},{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 110°, 각 ㄴ이 25°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 110 − 25 = 45(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 45°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#18','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C4',3,'mc','auto','정사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?',ARRAY['M5-2-u3-X08','M5-2-u3-X09']::text[],true,'{"seq":18,"concept":"M5-2-u3-C4","difficulty":3,"kind":"mc","stem":"정사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?","options":[{"t":"직선 ㅁㅂ","correct":true},{"t":"직선 ㄱㄴ","mis":"M5-2-u3-X08"},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X08"},{"t":"모두 대칭축이에요","mis":"M5-2-u3-X09"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㅁㅂ은 한가운데를 지나지 않아 접으면 겹치지 않아요.","그래서 답은 직선 ㅁㅂ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄱ":[0,0,"n"],"ㄴ":[120,120,"s"],"ㄷ":[60,0,"n"],"ㄹ":[60,120,"s"],"ㅁ":[40,0,"n"],"ㅂ":[40,120,"s"]},"poly":[[[20,20],[100,20],[100,100],[20,100]]],"seg":[[[0,0],[120,120]],[[60,0],[60,120]],[[40,0],[40,120]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이등변삼각형에 직선 세 개를 그었어요. 대칭축인 직선은 어느 것인가요?","options":[{"t":"직선 ㄱㄴ","correct":true},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X09"},{"t":"직선 ㅁㅂ","mis":"M5-2-u3-X09"},{"t":"대칭축인 직선이 없어요","mis":"M5-2-u3-X08"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㄱㄴ만 꼭짓점에서 밑변 가운데로 내린 선이에요.","그래서 답은 직선 ㄱㄴ이에요."],"asset":{"type":"geo","items":[{"w":160,"h":140,"pts":{"ㄱ":[80,0,"n"],"ㄴ":[80,140,"s"],"ㄷ":[0,70.0,"w"],"ㄹ":[160,70.0,"e"],"ㅁ":[0,0,"n"],"ㅂ":[152.0,140,"s"]},"poly":[[[80,20],[140,120],[20,120]]],"seg":[[[80,0],[80,140]],[[0,70.0],[160,70.0]],[[0,0],[152.0,140]]]}],"tag":false}},{"stem":"평행사변형의 대각선에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓이를 반으로 나누지만 대칭축은 아니다","correct":true},{"t":"대칭축이다","mis":"M5-2-u3-X09"},{"t":"도형 밖에 있다","mis":"M5-2-u3-X17"},{"t":"길이가 한 변과 같다","mis":"M5-2-u3-X17"}],"explanation":["평행사변형을 대각선으로 자르면 넓이가 같은 두 삼각형이 돼요.","그런데 대각선으로 접으면 꼭짓점이 어긋나 겹치지 않아요.","넓이를 반으로 나누는 것과 접어서 겹치는 것은 다른 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#19','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C5',3,'sa','auto','육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄱㄴ과 대칭축이 만나는 점이에요. 선분 ㄱㅅ이 6 cm일 때 선분 ㄱㄴ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M5-2-u3-C5","difficulty":3,"kind":"sa","stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄱㄴ과 대칭축이 만나는 점이에요. 선분 ㄱㅅ이 6 cm일 때 선분 ㄱㄴ은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["점 ㄱ과 점 ㄴ은 대응점이에요.","대칭축은 선분 ㄱㄴ을 똑같이 둘로 나눠 선분 ㄴㅅ도 6 cm예요.","6 + 6 = 12(cm)예요."],"mis":"M5-2-u3-X10","asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"],"ㅅ":[60.0,24.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]],[[20,24.0],[100,24.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅇ은 선분 ㄱㅅ과 대칭축이 만나는 점이에요. 선분 ㄱㅇ이 7 cm일 때 선분 ㄱㅅ은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["점 ㄱ과 점 ㅅ은 대응점이에요.","대칭축은 선분 ㄱㅅ을 똑같이 둘로 나눠 선분 ㅅㅇ도 7 cm예요.","7 + 7 = 14(cm)예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"],"ㅇ":[24.0,60.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]],[[24.0,30.0],[24.0,90.0]]]}],"tag":false}},{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄷㅂ과 대칭축이 만나는 점이에요. 선분 ㄷㅅ이 8 cm일 때 선분 ㄷㅂ은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["점 ㄷ과 점 ㅂ은 대응점이에요.","대칭축은 선분 ㄷㅂ을 똑같이 둘로 나눠 선분 ㅂㅅ도 8 cm예요.","8 + 8 = 16(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"],"ㅅ":[60.0,64.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]],[[120,64.0],[0,64.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#20','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C6',3,'mc','auto','모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":20,"concept":"M5-2-u3-C6","difficulty":3,"kind":"mc","stem":"모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄹ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄴ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":180,"h":180,"pts":{"ㄱ":[60,100,"nw"],"ㄴ":[100,60,"se"],"ㄷ":[120,40,"se"],"ㄹ":[140,100,"se"]},"seg":[[[20,20],[160,160]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄷ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄹ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":200,"h":200,"pts":{"ㄱ":[40,100,"nw"],"ㄴ":[120,20,"se"],"ㄷ":[160,100,"se"],"ㄹ":[100,40,"se"]},"seg":[[[20,20],[180,180]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄷ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄴ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":220,"h":220,"pts":{"ㄱ":[60,120,"nw"],"ㄴ":[120,60,"se"],"ㄷ":[180,120,"se"],"ㄹ":[140,4