INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#21','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C9',3,'mc','auto','모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13']::text[],true,'{"seq":21,"concept":"M5-2-u3-C9","difficulty":3,"kind":"mc","stem":"모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 2칸, 위 3칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 2칸, 위 3칸) 대응점이에요.","그래서 점 ㄷ이에요 — 점 ㄴ·ㄹ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":120,"h":160,"pts":{"ㄱ":[20,140,"ne"],"ㅇ":[60,80,"ne"],"ㄴ":[100,140,"ne"],"ㄷ":[100,20,"ne"],"ㄹ":[20,20,"ne"]},"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 3칸, 아래 2칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 3칸, 아래 2칸) 대응점이에요.","그래서 점 ㄹ이에요 — 점 ㄷ·ㄴ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[140,20,"ne"],"ㅇ":[80,60,"ne"],"ㄴ":[140,100,"ne"],"ㄷ":[20,20,"ne"],"ㄹ":[20,100,"ne"]},"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 3칸, 아래 1칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 3칸, 아래 1칸) 대응점이에요.","그래서 점 ㄴ이에요 — 점 ㄷ·ㄹ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":160,"h":80,"pts":{"ㄱ":[20,20,"ne"],"ㅇ":[80,40,"ne"],"ㄴ":[140,60,"ne"],"ㄷ":[140,20,"ne"],"ㄹ":[20,60,"ne"]},"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#22','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C10',3,'mc','auto','사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X02']::text[],true,'{"seq":22,"concept":"M5-2-u3-C10","difficulty":3,"kind":"mc","stem":"사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 ㄱ자 조각 넷, ㉯는 일자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 1, 1, 1, 1, ㉯ 1, 1, 2, 0그루예요.","나무가 한 그루씩인 것은 ㉮예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[60.0,60.0,"ne"],"ㄷ":[100.0,20.0,"ne"],"ㄹ":[100.0,100.0,"ne"]},"poly":[[[0,0],[80,0],[80,40],[40,40],[40,80],[0,80]],[[80,0],[160,0],[160,80],[120,80],[120,40],[80,40]],[[40,40],[80,40],[80,120],[0,120],[0,80],[40,80]],[[80,40],[120,40],[120,80],[160,80],[160,120],[80,120]]],"grid":40},{"w":160,"h":120,"pts":{"ㅁ":[20.0,20.0,"ne"],"ㅂ":[60.0,60.0,"ne"],"ㅅ":[100.0,20.0,"ne"],"ㅇ":[100.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 일자 조각 넷, ㉯는 ㄱ자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 0, 2, 1, 1, ㉯ 1, 1, 1, 1그루예요.","나무가 한 그루씩인 것은 ㉯예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[60.0,20.0,"ne"],"ㄴ":[60.0,100.0,"ne"],"ㄷ":[140.0,60.0,"ne"],"ㄹ":[100.0,60.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40},{"w":160,"h":120,"pts":{"ㅁ":[60.0,20.0,"ne"],"ㅂ":[60.0,100.0,"ne"],"ㅅ":[140.0,60.0,"ne"],"ㅇ":[100.0,60.0,"ne"]},"poly":[[[0,0],[80,0],[80,40],[40,40],[40,80],[0,80]],[[80,0],[160,0],[160,80],[120,80],[120,40],[80,40]],[[40,40],[80,40],[80,120],[0,120],[0,80],[40,80]],[[80,40],[120,40],[120,80],[160,80],[160,120],[80,120]]],"grid":40}]}},{"stem":"이번에는 다른 보기예요. 사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 ㄱ자 조각 넷, ㉯는 일자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 1, 1, 1, 1, ㉯ 2, 0, 0, 2그루예요.","나무가 한 그루씩인 것은 ㉮예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[140.0,20.0,"ne"],"ㄷ":[20.0,100.0,"ne"],"ㄹ":[140.0,100.0,"ne"]},"poly":[[[0,0],[80,0],[80,40],[40,40],[40,80],[0,80]],[[80,0],[160,0],[160,80],[120,80],[120,40],[80,40]],[[40,40],[80,40],[80,120],[0,120],[0,80],[40,80]],[[80,40],[120,40],[120,80],[160,80],[160,120],[80,120]]],"grid":40},{"w":160,"h":120,"pts":{"ㅁ":[20.0,20.0,"ne"],"ㅂ":[140.0,20.0,"ne"],"ㅅ":[20.0,100.0,"ne"],"ㅇ":[140.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#23','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C7',4,'essay','teacher','정사각형 3개로 된 ㄱ자 모양은 선대칭도형인지, 점대칭도형인지 각각 판단하고 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u3-C7","difficulty":4,"kind":"essay","stem":"정사각형 3개로 된 ㄱ자 모양은 선대칭도형인지, 점대칭도형인지 각각 판단하고 까닭을 쓰세요.","answer_guide":{"answer":"예: ㄱ자 모양은 꺾인 모서리를 지나는 비스듬한 선으로 접으면 완전히 겹치므로 선대칭도형이다. 그런데 어느 점을 중심으로 반 바퀴 돌려도 꺾인 쪽의 방향이 반대로 되어 겹치지 않으므로 점대칭도형은 아니다. 한쪽만 되는 도형도 있다.","scoring_points":["비스듬한 선으로 접혀 선대칭도형이라고 썼는가","반 바퀴 돌리면 어긋나 점대칭도형이 아니라고 썼는가","한쪽만 되는 도형이 있다고 정리했는가"]},"explanation":["비스듬한 선으로 접으면 겹쳐요 — 선대칭도형이에요.","반 바퀴 돌리면 어긋나요.","점대칭도형은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#24','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C4',4,'essay','teacher','가로 6 cm, 세로 4 cm인 직사각형의 대칭축은 몇 개인지 쓰고, 대각선이 대칭축이 될 수 없는 까닭을 「넓이」와 「접기」라는 말을 넣어 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u3-C4","difficulty":4,"kind":"essay","stem":"가로 6 cm, 세로 4 cm인 직사각형의 대칭축은 몇 개인지 쓰고, 대각선이 대칭축이 될 수 없는 까닭을 「넓이」와 「접기」라는 말을 넣어 설명하세요.","answer_guide":{"answer":"예: 직사각형의 대칭축은 세로로 가운데를 지나는 선과 가로로 가운데를 지나는 선, 모두 2개이다. 대각선은 직사각형을 넓이가 같은 두 삼각형으로 나누지만, 대각선을 따라 접으면 꼭짓점이 어긋나 완전히 겹치지 않는다. 넓이를 반으로 나누는 것과 접어서 겹치는 것은 다르므로 대각선은 대칭축이 아니다.","scoring_points":["대칭축이 2개라고 썼는가","대각선이 넓이를 반으로 나눈다고 썼는가","대각선으로 접으면 겹치지 않아 대칭축이 아니라고 썼는가"]},"explanation":["대칭축은 세로·가로 가운데 선 2개예요.","대각선은 넓이를 반으로 나눠요.","그런데 접으면 겹치지 않아 대칭축이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_b#25','math',5,2,'u3','','g5_2_math_u3_review_b','unit_review','M5-2-u3-C4',4,'mc','auto','대칭축이 가장 많은 도형은 어느 것인가요?',ARRAY['M5-2-u3-X08']::text[],true,'{"seq":25,"concept":"M5-2-u3-C4","difficulty":4,"kind":"mc","stem":"대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정육각형","correct":true},{"t":"마름모","mis":"M5-2-u3-X08"},{"t":"정오각형","mis":"M5-2-u3-X08"},{"t":"직사각형","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","마름모 2개, 정육각형 6개, 정오각형 5개, 직사각형 2개예요.","가장 많은 것은 정육각형이에요"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정오각형","correct":true},{"t":"십자 모양","mis":"M5-2-u3-X08"},{"t":"정삼각형","mis":"M5-2-u3-X08"},{"t":"ㄱ자 모양","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정오각형 5개, 십자 모양 4개, 정삼각형 3개, ㄱ자 모양 1개예요.","가장 많은 것은 정오각형이에요"]},{"stem":"이번에는 다른 보기예요. 대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정삼각형","correct":true},{"t":"마름모","mis":"M5-2-u3-X08"},{"t":"이등변삼각형","mis":"M5-2-u3-X08"},{"t":"평행사변형","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정삼각형 3개, 마름모 2개, 이등변삼각형 1개, 평행사변형 0개예요.","가장 많은 것은 정삼각형이에요"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#1','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C1',1,'sa','auto','한 변이 6 cm인 정사각형을 오른쪽으로 5칸 밀었을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C1","difficulty":1,"kind":"sa","stem":"한 변이 6 cm인 정사각형을 오른쪽으로 5칸 밀었을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["밀기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 6 cm예요."],"mis":"M5-2-u3-X01","variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 4 cm인 직사각형을 시계 방향으로 반 바퀴 돌렸을 때, 움직인 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["돌리기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 4 cm예요."]},{"stem":"한 변이 9 cm인 정사각형을 시계 방향으로 반 바퀴 돌렸을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["돌리기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#2','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C2',1,'sa','auto','한 변이 8 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C2","difficulty":1,"kind":"sa","stem":"한 변이 8 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 8 cm예요.","둘레는 8 × 4 = 32(cm)예요."],"mis":"M5-2-u3-X03","variant_rule":{"alt":[{"stem":"한 변이 3 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 3 cm예요.","둘레는 3 × 4 = 12(cm)예요."]},{"stem":"한 변이 5 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 5 cm예요.","둘레는 5 × 4 = 20(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#3','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C3',1,'sa','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄹ이 90°일 때 각 ㅇ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u3-C3","difficulty":1,"kind":"sa","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄹ이 90°일 때 각 ㅇ은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["점 ㄹ의 대응점은 점 ㅇ이에요.","각 ㄹ과 각 ㅇ은 대응각이에요.","대응각의 크기는 같으므로 90°예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄷ이 55°일 때 각 ㅅ은 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["점 ㄷ의 대응점은 점 ㅅ이에요.","각 ㄷ과 각 ㅅ은 대응각이에요.","대응각의 크기는 같으므로 55°예요."]},{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄴ이 85°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["점 ㄴ의 대응점은 점 ㅂ이에요.","각 ㄴ과 각 ㅂ은 대응각이에요.","대응각의 크기는 같으므로 85°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#4','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C4',1,'sa','auto','마름모의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C4","difficulty":1,"kind":"sa","stem":"마름모의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","두 대각선으로 접으면 겹쳐요 — 세로·가로가 아니라 대각선이에요.","그래서 마름모의 대칭축은 2개예요."],"mis":"M5-2-u3-X08","asset":{"type":"geo","items":[{"w":100,"h":80,"poly":[[[50.0,0],[100,40],[50.0,80],[0,40]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정삼각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","각 꼭짓점에서 마주 보는 변의 가운데로 내린 선 3개로 접혀요.","그래서 정삼각형의 대칭축은 3개예요."],"asset":{"type":"geo","items":[{"w":80,"h":69.2,"poly":[[[0,69.2],[40,0],[80,69.2]]]}],"tag":false}},{"stem":"직사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","세로로, 가로로 접으면 겹쳐요 — 대각선으로는 겹치지 않아요.","그래서 직사각형의 대칭축은 2개예요."],"asset":{"type":"geo","items":[{"w":100,"h":60,"poly":[[[0,0],[100,0],[100,60],[0,60]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#5','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C5',1,'sa','auto','선대칭도형에서 대칭축에서 한 대응점까지의 거리가 8 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u3-C5","difficulty":1,"kind":"sa","stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 8 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 8 cm예요.","8 + 8 = 16(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 9 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 9 cm예요.","9 + 9 = 18(cm)예요."]},{"stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 4 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 4 cm예요.","4 + 4 = 8(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#6','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C6',1,'sa','auto','선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 4칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C6","difficulty":1,"kind":"sa","stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 4칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대응점은 반대쪽으로 4칸 간 자리예요.","꼭짓점에서 대칭축까지 4칸, 대칭축에서 대응점까지 4칸이에요.","4 + 4 = 8(칸)이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 6칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["대응점은 반대쪽으로 6칸 간 자리예요.","꼭짓점에서 대칭축까지 6칸, 대칭축에서 대응점까지 6칸이에요.","6 + 6 = 12(칸)이에요."]},{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 3칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대응점은 반대쪽으로 3칸 간 자리예요.","꼭짓점에서 대칭축까지 3칸, 대칭축에서 대응점까지 3칸이에요.","3 + 3 = 6(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#7','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C7',1,'mc','auto','점대칭도형인 마름모에서 대칭의 중심은 몇 개인가요?',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":7,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"점대칭도형인 마름모에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."],"variant_rule":{"alt":[{"stem":"점대칭도형인 정육각형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]},{"stem":"점대칭도형인 평행사변형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#8','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C8',1,'sa','auto','점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 3 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C8","difficulty":1,"kind":"sa","stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 3 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 3 cm예요.","3 + 3 = 6(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 8 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 8 cm예요.","8 + 8 = 16(cm)예요."]},{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 5 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 5 cm예요.","5 + 5 = 10(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
