INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#13','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C6',2,'mc','auto','모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":13,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 4칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 4칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄹ이에요."],"asset":{"type":"geo","items":[{"w":220,"h":160.0,"pts":{"ㄱ":[20,90.0,"w"],"ㄴ":[180,70.0,"e"],"ㄷ":[200,90.0,"e"],"ㄹ":[180,90.0,"e"]},"seg":[[[100,20.0],[100,140.0]],[[100,30.0],[20,90.0]],[[20,90.0],[60,50.0]],[[60,50.0],[100,130.0]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 1칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 1칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":140,"h":140.0,"pts":{"ㄱ":[60,90.0,"w"],"ㄴ":[100,90.0,"e"],"ㄷ":[120,90.0,"e"],"ㄹ":[100,70.0,"e"]},"seg":[[[80,20.0],[80,120.0]],[[80,30.0],[60,90.0]],[[60,90.0],[20,50.0]],[[20,50.0],[80,110.0]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 3칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 3칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":160.0,"pts":{"ㄱ":[20,70.0,"w"],"ㄴ":[160,70.0,"e"],"ㄷ":[140,70.0,"e"],"ㄹ":[140,50.0,"e"]},"seg":[[[80,20.0],[80,140.0]],[[80,30.0],[20,70.0]],[[20,70.0],[60,110.0]],[[60,110.0],[80,130.0]]],"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#14','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C7',2,'sa','auto','ㄱ자 모양, 십자 모양, 평행사변형, 정오각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M5-2-u3-C7","difficulty":2,"kind":"sa","stem":"ㄱ자 모양, 십자 모양, 평행사변형, 정오각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","ㄱ자 모양 ×, 십자 모양 ○, 평행사변형 ○, 정오각형 ×예요.","점대칭도형은 2개예요."],"mis":"M5-2-u3-X14","variant_rule":{"alt":[{"stem":"정삼각형, 정오각형, 직각사다리꼴, 평행사변형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","정삼각형 ×, 정오각형 ×, 직각사다리꼴 ×, 평행사변형 ○예요.","점대칭도형은 1개예요."]},{"stem":"평행사변형, 정삼각형, 직사각형, 직각사다리꼴 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","평행사변형 ○, 정삼각형 ×, 직사각형 ○, 직각사다리꼴 ×예요.","점대칭도형은 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#15','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C8',2,'mc','auto','평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 점 ㄹ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X13']::text[],true,'{"seq":15,"concept":"M5-2-u3-C8","difficulty":2,"kind":"mc","stem":"평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 점 ㄹ의 대응점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄱ","mis":"M5-2-u3-X06"},{"t":"점 ㄷ","mis":"M5-2-u3-X06"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["대응점은 반 바퀴 돌렸을 때 겹치는 점이에요.","점 ㄹ에서 점 ㅇ을 지나 같은 거리만큼 더 가면 점 ㄴ이에요.","그래서 점 ㄹ의 대응점은 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 점 ㅂ의 대응점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄱ","mis":"M5-2-u3-X06"},{"t":"점 ㅁ","mis":"M5-2-u3-X06"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["대응점은 반 바퀴 돌렸을 때 겹치는 점이에요.","점 ㅂ에서 점 ㅇ을 지나 같은 거리만큼 더 가면 점 ㄷ이에요.","그래서 점 ㅂ의 대응점은 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[20,0,"nw"],"ㄴ":[100,0,"ne"],"ㄷ":[140,40,"e"],"ㄹ":[120,80,"se"],"ㅁ":[40,80,"sw"],"ㅂ":[0,40,"w"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}},{"stem":"평행사변형 ㄱㄴㄷㄹ은 점 ㅇ을 대칭의 중심으로 하는 점대칭도형이에요. 점 ㄷ의 대응점은 어느 것인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X06"},{"t":"점 ㄹ","mis":"M5-2-u3-X06"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["대응점은 반 바퀴 돌렸을 때 겹치는 점이에요.","점 ㄷ에서 점 ㅇ을 지나 같은 거리만큼 더 가면 점 ㄱ이에요.","그래서 점 ㄷ의 대응점은 점 ㄱ이에요."],"asset":{"type":"geo","items":[{"w":140,"h":80,"pts":{"ㄱ":[40,0,"nw"],"ㄴ":[140,0,"ne"],"ㄷ":[100,80,"se"],"ㄹ":[0,80,"sw"],"ㅇ":[70.0,40,"n"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":