INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#16','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C10',2,'sa','auto','모양과 크기가 같은 정사각형 18개가 붙어 있는 땅을 서로 합동인 도형 6개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M5-2-u3-C10","difficulty":2,"kind":"sa","stem":"모양과 크기가 같은 정사각형 18개가 붙어 있는 땅을 서로 합동인 도형 6개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","18개를 6조각에 똑같이 나누어요.","18 ÷ 6 = 3(개)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"모양과 크기가 같은 정사각형 21개가 붙어 있는 땅을 서로 합동인 도형 7개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","21개를 7조각에 똑같이 나누어요.","21 ÷ 7 = 3(개)예요."]},{"stem":"모양과 크기가 같은 정사각형 12개가 붙어 있는 땅을 서로 합동인 도형 4개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","12개를 4조각에 똑같이 나누어요.","12 ÷ 4 = 3(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#17','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C3',3,'sa','auto','삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 75°, 각 ㄴ이 45°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M5-2-u3-C3","difficulty":3,"kind":"sa","stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 75°, 각 ㄴ이 45°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 75 − 45 = 60(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 60°예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 110°, 각 ㄴ이 25°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 110 − 25 = 45(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 45°예요."]},{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 90°, 각 ㄴ이 30°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 90 − 30 = 60(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 60°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#18','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C4',3,'mc','auto','이등변삼각형에 직선 세 개를 그었어요. 대칭축인 직선은 어느 것인가요?',ARRAY['M5-2-u3-X09','M5-2-u3-X08']::text[],true,'{"seq":18,"concept":"M5-2-u3-C4","difficulty":3,"kind":"mc","stem":"이등변삼각형에 직선 세 개를 그었어요. 대칭축인 직선은 어느 것인가요?","options":[{"t":"직선 ㄱㄴ","correct":true},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X09"},{"t":"직선 ㅁㅂ","mis":"M5-2-u3-X09"},{"t":"대칭축인 직선이 없어요","mis":"M5-2-u3-X08"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㄱㄴ만 꼭짓점에서 밑변 가운데로 내린 선이에요.","그래서 답은 직선 ㄱㄴ이에요."],"asset":{"type":"geo","items":[{"w":160,"h":140,"pts":{"ㄱ":[80,0,"n"],"ㄴ":[80,140,"s"],"ㄷ":[0,70.0,"w"],"ㄹ":[160,70.0,"e"],"ㅁ":[0,0,"n"],"ㅂ":[152.0,140,"s"]},"poly":[[[80,20],[140,120],[20,120]]],"seg":[[[80,0],[80,140]],[[0,70.0],[160,70.0]],[[0,0],[152.0,140]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"평행사변형의 대각선에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓이를 반으로 나누지만 대칭축은 아니다","correct":true},{"t":"대칭축이다","mis":"M5-2-u3-X09"},{"t":"도형 밖에 있다","mis":"M5-2-u3-X17"},{"t":"길이가 한 변과 같다","mis":"M5-2-u3-X17"}],"explanation":["평행사변형을 대각선으로 자르면 넓이가 같은 두 삼각형이 돼요.","그런데 대각선으로 접으면 꼭짓점이 어긋나 겹치지 않아요.","넓이를 반으로 나누는 것과 접어서 겹치는 것은 다른 일이에요."]},{"stem":"직사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?","options":[{"t":"직선 ㅁㅂ","correct":true},{"t":"직선 ㄱㄴ","mis":"M5-2-u3-X08"},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X08"},{"t":"모두 대칭축이에요","mis":"M5-2-u3-X09"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㅁㅂ은 대각선 — 넓이는 반으로 나누지만 접으면 겹치지 않아요.","그래서 답은 직선 ㅁㅂ이에요."],"asset":{"type":"geo","items":[{"w":180.0,"h":120,"pts":{"ㄱ":[90.0,0,"n"],"ㄴ":[90.0,120,"s"],"ㄷ":[10.0,60,"w"],"ㄹ":[170.0,60,"e"],"ㅁ":[0.0,0,"n"],"ㅂ":[180.0,120,"s"]},"poly":[[[30.0,20],[150.0,20],[150.0,100],[30.0,100]]],"seg":[[[90.0,0],[90.0,120]],[[10.0,60],[170.0,60]],[[0.0,0],[180.0,120]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#19','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C5',3,'sa','auto','칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅇ은 선분 ㄱㅅ과 대칭축이 만나는 점이에요. 선분 ㄱㅇ이 7 cm일 때 선분 ㄱㅅ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M5-2-u3-C5","difficulty":3,"kind":"sa","stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅇ은 선분 ㄱㅅ과 대칭축이 만나는 점이에요. 선분 ㄱㅇ이 7 cm일 때 선분 ㄱㅅ은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["점 ㄱ과 점 ㅅ은 대응점이에요.","대칭축은 선분 ㄱㅅ을 똑같이 둘로 나눠 선분 ㅅㅇ도 7 cm예요.","7 + 7 = 14(cm)예요."],"mis":"M5-2-u3-X10","asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ":[24.0,30.0,"nw"],"ㄴ":[84.0,30.0,"n"],"ㄷ":[84.0,0,"n"],"ㄹ":[144.0,60,"e"],"ㅁ":[84.0,120,"s"],"ㅂ":[84.0,90.0,"s"],"ㅅ":[24.0,90.0,"sw"],"ㅇ":[24.0,60.0,"se"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ"]],"seg":[[[0.0,60],[168.0,60]],[[24.0,30.0],[24.0,90.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄷㅂ과 대칭축이 만나는 점이에요. 선분 ㄷㅅ이 8 cm일 때 선분 ㄷㅂ은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["점 ㄷ과 점 ㅂ은 대응점이에요.","대칭축은 선분 ㄷㅂ을 똑같이 둘로 나눠 선분 ㅂㅅ도 8 cm예요.","8 + 8 = 16(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"],"ㅅ":[60.0,64.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]],[[120,64.0],[0,64.0]]]}],"tag":false}},{"stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅂ은 선분 ㄱㄷ과 대칭축이 만나는 점이에요. 선분 ㄱㅂ이 4 cm일 때 선분 ㄱㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["점 ㄱ과 점 ㄷ은 대응점이에요.","대칭축은 선분 ㄱㄷ을 똑같이 둘로 나눠 선분 ㄷㅂ도 4 cm예요.","4 + 4 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"],"ㅂ":[60.0,64.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]],[[0,64.0],[120,64.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#20','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C6',3,'mc','auto','모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":20,"concept":"M5-2-u3-C6","difficulty":3,"kind":"mc","stem":"모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄷ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄹ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":200,"h":200,"pts":{"ㄱ":[40,100,"nw"],"ㄴ":[120,20,"se"],"ㄷ":[160,100,"se"],"ㄹ":[100,40,"se"]},"seg":[[[20,20],[180,180]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄷ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄴ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":220,"h":220,"pts":{"ㄱ":[60,120,"nw"],"ㄴ":[120,60,"se"],"ㄷ":[180,120,"se"],"ㄹ":[140,40,"se"]},"seg":[[[20,20],[200,200]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄴ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄷ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":160,"h":160,"pts":{"ㄱ":[40,80,"nw"],"ㄴ":[120,80,"se"],"ㄷ":[80,40,"se"],"ㄹ":[100,20,"se"]},"seg":[[[20,20],[140,140]]],"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#21','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C9',3,'mc','auto','모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13']::text[],true,'{"seq":21,"concept":"M5-2-u3-C9","difficulty":3,"kind":"mc","stem":"모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 3칸, 아래 2칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 3칸, 아래 2칸) 대응점이에요.","그래서 점 ㄹ이에요 — 점 ㄷ·ㄴ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[140,20,"ne"],"ㅇ":[80,60,"ne"],"ㄴ":[140,100,"ne"],"ㄷ":[20,20,"ne"],"ㄹ":[20,100,"ne"]},"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 3칸, 아래 1칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 3칸, 아래 1칸) 대응점이에요.","그래서 점 ㄴ이에요 — 점 ㄷ·ㄹ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":160,"h":80,"pts":{"ㄱ":[20,20,"ne"],"ㅇ":[80,40,"ne"],"ㄴ":[140,60,"ne"],"ㄷ":[140,20,"ne"],"ㄹ":[20,60,"ne"]},"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 2칸, 위 1칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 2칸, 위 1칸) 대응점이에요.","그래서 점 ㄴ이에요 — 점 ㄹ·ㄷ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":120,"h":80,"pts":{"ㄱ":[100,60,"ne"],"ㅇ":[60,40,"ne"],"ㄴ":[20,20,"ne"],"ㄷ":[100,20,"ne"],"ㄹ":[20,60,"ne"]},"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#22','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C10',3,'mc','auto','사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?',ARRAY['M5-2-u3-X16','M5-2-u3-X02']::text[],true,'{"seq":22,"concept":"M5-2-u3-C10","difficulty":3,"kind":"mc","stem":"사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 일자 조각 넷, ㉯는 ㄱ자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 0, 2, 1, 1, ㉯ 1, 1, 1, 1그루예요.","나무가 한 그루씩인 것은 ㉯예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[60.0,20.0,"ne"],"ㄴ":[60.0,100.0,"ne"],"ㄷ":[140.0,60.0,"ne"],"ㄹ":[100.0,60.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40},{"w":160,"h":120,"pts":{"ㅁ":[60.0,20.0,"ne"],"ㅂ":[60.0,100.0,"ne"],"ㅅ":[140.0,60.0,"ne"],"ㅇ":[100.0,60.0,"ne"]},"poly":[[[0,0],[80,0],[80,40],[40,40],[40,80],[0,80]],[[80,0],[160,0],[160,80],[120,80],[120,40],[80,40]],[[40,40],[80,40],[80,120],[0,120],[0,80],[40,80]],[[80,40],[120,40],[120,80],[160,80],[160,120],[80,120]]],"grid":40}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 ㄱ자 조각 넷, ㉯는 일자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 1, 1, 1, 1, ㉯ 2, 0, 0, 2그루예요.","나무가 한 그루씩인 것은 ㉮예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[140.0,20.0,"ne"],"ㄷ":[20.0,100.0,"ne"],"ㄹ":[140.0,100.0,"ne"]},"poly":[[[0,0],[80,0],[80,40],[40,40],[40,80],[0,80]],[[80,0],[160,0],[160,80],[120,80],[120,40],[80,40]],[[40,40],[80,40],[80,120],[0,120],[0,80],[40,80]],[[80,40],[120,40],[120,80],[160,80],[160,120],[80,120]]],"grid":40},{"w":160,"h":120,"pts":{"ㅁ":[20.0,20.0,"ne"],"ㅂ":[140.0,20.0,"ne"],"ㅅ":[20.0,100.0,"ne"],"ㅇ":[140.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40}]}},{"stem":"이번에는 다른 보기예요. 사과나무가 있는 땅(점이 나무 자리)을 두 가지로 나누었어요. 조건(합동인 도형 4개, 나무 한 그루씩)에 맞게 나눈 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-2-u3-X16"},{"t":"둘 다 맞아요","mis":"M5-2-u3-X16"},{"t":"둘 다 틀려요","mis":"M5-2-u3-X02"}],"explanation":["㉮는 일자 조각 넷, ㉯는 ㄱ자 조각 넷 — 둘 다 조각끼리는 합동이에요.","조각마다 나무 수는 ㉮ 2, 0, 0, 2, ㉯ 1, 1, 1, 1그루예요.","나무가 한 그루씩인 것은 ㉯예요."],"asset":{"type":"geo","items":[{"w":160,"h":120,"pts":{"ㄱ":[20.0,20.0,"ne"],"ㄴ":[140.0,20.0,"ne"],"ㄷ":[20.0,100.0,"ne"],"ㄹ":[140.0,100.0,"ne"]},"poly":[[[0,0],[40,0],[40,120],[0,120]],[[40,0],[80,0],[80,120],[40,120]],[[80,0],[120,0],[120,120],[80,120]],[[120,0],[160,0],[160,120],[120,120]]],"grid":40},{"w":160,"h":120,"pts":{"ㅁ":[20.0,20.0,"ne"],"ㅂ":[140.0,20.0,"ne"],"ㅅ":[20.0,100.0,"ne"],"ㅇ":[140.0,100.0,"ne"]},"poly":[[[0,0],[80,0],[80,40],[40,40],[40,80],[0,80]],[[80,0],[160,0],[160,80],[120,80],[120,40],[80,40]],[[40,40],[80,40],[80,120],[0,120],[0,80],[40,80]],[[80,40],[120,40],[120,80],[160,80],[160,120],[80,120]]],"grid":40}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#23','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C7',4,'essay','teacher','평행사변형과 이등변삼각형을 각각 접어 보고 돌려 보았어요. 두 도형이 선대칭도형인지, 점대칭도형인지 각각 쓰고, 도형을 가를 때 접어도 보고 돌려도 보아야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u3-C7","difficulty":4,"kind":"essay","stem":"평행사변형과 이등변삼각형을 각각 접어 보고 돌려 보았어요. 두 도형이 선대칭도형인지, 점대칭도형인지 각각 쓰고, 도형을 가를 때 접어도 보고 돌려도 보아야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 평행사변형은 어느 직선으로 접어도 겹치지 않아 선대칭도형이 아니지만, 대각선이 만나는 점을 중심으로 반 바퀴 돌리면 겹쳐 점대칭도형이다. 이등변삼각형은 꼭짓점에서 밑변 가운데로 내린 선으로 접으면 겹쳐 선대칭도형이지만, 반 바퀴 돌리면 거꾸로 서 점대칭도형이 아니다. 접어 보기만 하면 평행사변형을 놓치고, 돌려 보기만 하면 이등변삼각형을 놓치므로 두 가지를 모두 해 보아야 한다.","scoring_points":["평행사변형 — 점대칭(선대칭 아님)이라고 썼는가","이등변삼각형 — 선대칭(점대칭 아님)이라고 썼는가","한 가지만 하면 놓치는 도형이 있다고 썼는가"]},"explanation":["평행사변형은 점대칭도형만이에요.","이등변삼각형은 선대칭도형만이에요.","접기·돌리기를 모두 해야 놓치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#24','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C9',4,'essay','teacher','점대칭도형을 그리려고 해요. 꼭짓점 ㄱ에서 대칭의 중심까지 오른쪽으로 2칸, 아래로 1칸을 갔어요. 점 ㄱ의 대응점을 대칭의 중심에서 어디에 찍어야 하는지 쓰고, 대응점을 중심까지만 가서 찍으면 어떻게 되는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u3-C9","difficulty":4,"kind":"essay","stem":"점대칭도형을 그리려고 해요. 꼭짓점 ㄱ에서 대칭의 중심까지 오른쪽으로 2칸, 아래로 1칸을 갔어요. 점 ㄱ의 대응점을 대칭의 중심에서 어디에 찍어야 하는지 쓰고, 대응점을 중심까지만 가서 찍으면 어떻게 되는지 쓰세요.","answer_guide":{"answer":"예: 대응점은 대칭의 중심을 지나 같은 만큼 더 간 자리이므로, 중심에서 오른쪽으로 2칸, 아래로 1칸 간 자리에 찍는다. 그러면 점 ㄱ과 대응점 사이는 오른쪽으로 4칸, 아래로 2칸이 되고 중심이 그 선분을 이등분한다. 중심까지만 가서 찍으면 대응점이 도형 안쪽에 찍혀 원래보다 작은 도형이 되므로 반 바퀴 돌려도 겹치지 않는다.","scoring_points":["중심에서 오른쪽 2칸, 아래 1칸이라고 썼는가","중심을 지나 같은 만큼 더 간다는 까닭을 썼는가","중심에서 멈추면 작아져 겹치지 않는다고 썼는가"]},"explanation":["중심을 지나 같은 만큼 한 번 더 가요.","중심에서 오른쪽 2칸, 아래 1칸이에요.","중심에서 멈추면 작아져 겹치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_c#25','math',5,2,'u3','','g5_2_math_u3_review_c','unit_review','M5-2-u3-C4',4,'mc','auto','대칭축이 가장 많은 도형은 어느 것인가요?',ARRAY['M5-2-u3-X08']::text[],true,'{"seq":25,"concept":"M5-2-u3-C4","difficulty":4,"kind":"mc","stem":"대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정오각형","correct":true},{"t":"십자 모양","mis":"M5-2-u3-X08"},{"t":"정삼각형","mis":"M5-2-u3-X08"},{"t":"ㄱ자 모양","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정오각형 5개, 십자 모양 4개, 정삼각형 3개, ㄱ자 모양 1개예요.","가장 많은 것은 정오각형이에요"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정삼각형","correct":true},{"t":"마름모","mis":"M5-2-u3-X08"},{"t":"이등변삼각형","mis":"M5-2-u3-X08"},{"t":"평행사변형","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정삼각형 3개, 마름모 2개, 이등변삼각형 1개, 평행사변형 0개예요.","가장 많은 것은 정삼각형이에요"]},{"stem":"이번에는 다른 보기예요. 대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정사각형","correct":true},{"t":"정삼각형","mis":"M5-2-u3-X08"},{"t":"직사각형","mis":"M5-2-u3-X08"},{"t":"이등변삼각형","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정사각형 4개, 정삼각형 3개, 직사각형 2개, 이등변삼각형 1개예요.","가장 많은 것은 정사각형이에요"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#1','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C1',1,'sa','auto','가로 7 cm, 세로 4 cm인 직사각형을 시계 방향으로 반 바퀴 돌렸을 때, 움직인 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u3-C1","difficulty":1,"kind":"sa","stem":"가로 7 cm, 세로 4 cm인 직사각형을 시계 방향으로 반 바퀴 돌렸을 때, 움직인 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["돌리기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 4 cm예요."],"mis":"M5-2-u3-X01","variant_rule":{"alt":[{"stem":"한 변이 9 cm인 정사각형을 시계 방향으로 반 바퀴 돌렸을 때, 움직인 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["돌리기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 9 cm예요."]},{"stem":"가로 8 cm, 세로 5 cm인 직사각형을 왼쪽으로 뒤집었을 때, 움직인 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["뒤집기를 해도 도형의 모양과 크기는 달라지지 않아요.","자리나 방향만 바뀌고 변의 길이는 그대로예요.","그래서 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#2','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C2',1,'sa','auto','한 변이 3 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u3-C2","difficulty":1,"kind":"sa","stem":"한 변이 3 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 3 cm예요.","둘레는 3 × 4 = 12(cm)예요."],"mis":"M5-2-u3-X03","variant_rule":{"alt":[{"stem":"한 변이 5 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 5 cm예요.","둘레는 5 × 4 = 20(cm)예요."]},{"stem":"한 변이 6 cm인 정사각형과 서로 합동인 정사각형이 있어요. 그 정사각형의 둘레는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["합동인 정사각형은 모양과 크기가 같아요.","그래서 한 변도 6 cm예요.","둘레는 6 × 4 = 24(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#3','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C3',1,'sa','auto','사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄷ이 55°일 때 각 ㅅ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u3-C3","difficulty":1,"kind":"sa","stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄷ이 55°일 때 각 ㅅ은 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["점 ㄷ의 대응점은 점 ㅅ이에요.","각 ㄷ과 각 ㅅ은 대응각이에요.","대응각의 크기는 같으므로 55°예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄴ이 85°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["점 ㄴ의 대응점은 점 ㅂ이에요.","각 ㄴ과 각 ㅂ은 대응각이에요.","대응각의 크기는 같으므로 85°예요."]},{"stem":"사각형 ㄱㄴㄷㄹ과 사각형 ㅁㅂㅅㅇ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ·ㄹ의 대응점은 차례대로 점 ㅁ·ㅂ·ㅅ·ㅇ이에요. 각 ㄱ이 65°일 때 각 ㅁ은 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["점 ㄱ의 대응점은 점 ㅁ이에요.","각 ㄱ과 각 ㅁ은 대응각이에요.","대응각의 크기는 같으므로 65°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#4','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C4',1,'sa','auto','정삼각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u3-C4","difficulty":1,"kind":"sa","stem":"정삼각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","각 꼭짓점에서 마주 보는 변의 가운데로 내린 선 3개로 접혀요.","그래서 정삼각형의 대칭축은 3개예요."],"mis":"M5-2-u3-X08","asset":{"type":"geo","items":[{"w":80,"h":69.2,"poly":[[[0,69.2],[40,0],[80,69.2]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","세로로, 가로로 접으면 겹쳐요 — 대각선으로는 겹치지 않아요.","그래서 직사각형의 대칭축은 2개예요."],"asset":{"type":"geo","items":[{"w":100,"h":60,"poly":[[[0,0],[100,0],[100,60],[0,60]]]}],"tag":false}},{"stem":"정사각형의 대칭축은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["대칭축은 접어서 완전히 겹치게 하는 직선이에요.","세로·가로·두 대각선으로 접으면 겹쳐요.","그래서 정사각형의 대칭축은 4개예요."],"asset":{"type":"geo","items":[{"w":80,"h":80,"poly":[[[0,0],[80,0],[80,80],[0,80]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#5','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C5',1,'sa','auto','선대칭도형에서 대칭축에서 한 대응점까지의 거리가 9 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u3-C5","difficulty":1,"kind":"sa","stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 9 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 9 cm예요.","9 + 9 = 18(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 4 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 4 cm예요.","4 + 4 = 8(cm)예요."]},{"stem":"선대칭도형에서 대칭축에서 한 대응점까지의 거리가 6 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["대칭축은 대응점을 이은 선분을 똑같이 둘로 나눠요.","대칭축에서 다른 대응점까지도 6 cm예요.","6 + 6 = 12(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#6','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C6',1,'sa','auto','선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 6칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u3-C6","difficulty":1,"kind":"sa","stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 6칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["대응점은 반대쪽으로 6칸 간 자리예요.","꼭짓점에서 대칭축까지 6칸, 대칭축에서 대응점까지 6칸이에요.","6 + 6 = 12(칸)이에요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 3칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["대응점은 반대쪽으로 3칸 간 자리예요.","꼭짓점에서 대칭축까지 3칸, 대칭축에서 대응점까지 3칸이에요.","3 + 3 = 6(칸)이에요."]},{"stem":"선대칭도형을 그리려고 해요. 한 꼭짓점이 대칭축에서 5칸 떨어져 있다면, 그 꼭짓점과 대응점 사이는 몇 칸인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["대응점은 반대쪽으로 5칸 간 자리예요.","꼭짓점에서 대칭축까지 5칸, 대칭축에서 대응점까지 5칸이에요.","5 + 5 = 10(칸)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#7','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C7',1,'mc','auto','점대칭도형인 정육각형에서 대칭의 중심은 몇 개인가요?',ARRAY['M5-2-u3-X15']::text[],true,'{"seq":7,"concept":"M5-2-u3-C7","difficulty":1,"kind":"mc","stem":"점대칭도형인 정육각형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."],"variant_rule":{"alt":[{"stem":"점대칭도형인 평행사변형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]},{"stem":"점대칭도형인 정사각형에서 대칭의 중심은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u3-X15"},{"t":"4개","mis":"M5-2-u3-X15"},{"t":"도형마다 여러 개","mis":"M5-2-u3-X15"}],"explanation":["대칭의 중심은 반 바퀴 돌릴 때 붙잡는 한 점이에요.","그 점을 옮기면 돌린 도형이 다른 자리로 가서 겹치지 않아요.","그래서 대칭의 중심은 언제나 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#8','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C8',1,'sa','auto','점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 8 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u3-C8","difficulty":1,"kind":"sa","stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 8 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 8 cm예요.","8 + 8 = 16(cm)예요."],"mis":"M5-2-u3-X10","variant_rule":{"alt":[{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 5 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 5 cm예요.","5 + 5 = 10(cm)예요."]},{"stem":"점대칭도형에서 대칭의 중심에서 한 대응점까지의 거리가 7 cm예요. 두 대응점 사이의 거리는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["대칭의 중심은 대응점을 이은 선분을 이등분해요.","다른 대응점까지도 7 cm예요.","7 + 7 = 14(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
