INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#13','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C6',2,'mc','auto','모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":13,"concept":"M5-2-u3-C6","difficulty":2,"kind":"mc","stem":"모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 1칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 1칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":140,"h":140.0,"pts":{"ㄱ":[60,90.0,"w"],"ㄴ":[100,90.0,"e"],"ㄷ":[120,90.0,"e"],"ㄹ":[100,70.0,"e"]},"seg":[[[80,20.0],[80,120.0]],[[80,30.0],[60,90.0]],[[60,90.0],[20,50.0]],[[20,50.0],[80,110.0]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 3칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 3칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":160.0,"pts":{"ㄱ":[20,70.0,"w"],"ㄴ":[160,70.0,"e"],"ㄷ":[140,70.0,"e"],"ㄹ":[140,50.0,"e"]},"seg":[[[80,20.0],[80,140.0]],[[80,30.0],[20,70.0]],[[20,70.0],[60,110.0]],[[60,110.0],[80,130.0]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 세로 직선이 대칭축이에요. 선대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["점 ㄱ은 대칭축에서 왼쪽으로 2칸 떨어져 있어요.","대응점은 대칭축과 수직으로(가로로) 반대쪽 2칸 간 자리 — 높이는 그대로예요.","그래서 점 ㄴ이에요."],"asset":{"type":"g