INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#14','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C7',2,'sa','auto','정삼각형, 정오각형, 직각사다리꼴, 평행사변형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M5-2-u3-C7","difficulty":2,"kind":"sa","stem":"정삼각형, 정오각형, 직각사다리꼴, 평행사변형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","정삼각형 ×, 정오각형 ×, 직각사다리꼴 ×, 평행사변형 ○예요.","점대칭도형은 1개예요."],"mis":"M5-2-u3-X14","variant_rule":{"alt":[{"stem":"평행사변형, 정삼각형, 직사각형, 직각사다리꼴 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","평행사변형 ○, 정삼각형 ×, 직사각형 ○, 직각사다리꼴 ×예요.","점대칭도형은 2개예요."]},{"stem":"마름모, 이등변삼각형, 정사각형, 정육각형 가운데 점대칭도형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["반 바퀴 돌려 완전히 겹치는 도형을 찾아요.","마름모 ○, 이등변삼각형 ×, 정사각형 ○, 정육각형 ○예요.","점대칭도형은 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
