INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#16','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C10',2,'sa','auto','모양과 크기가 같은 정사각형 21개가 붙어 있는 땅을 서로 합동인 도형 7개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M5-2-u3-C10","difficulty":2,"kind":"sa","stem":"모양과 크기가 같은 정사각형 21개가 붙어 있는 땅을 서로 합동인 도형 7개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","21개를 7조각에 똑같이 나누어요.","21 ÷ 7 = 3(개)예요."],"mis":"M5-2-u3-X16","variant_rule":{"alt":[{"stem":"모양과 크기가 같은 정사각형 12개가 붙어 있는 땅을 서로 합동인 도형 4개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","12개를 4조각에 똑같이 나누어요.","12 ÷ 4 = 3(개)예요."]},{"stem":"모양과 크기가 같은 정사각형 15개가 붙어 있는 땅을 서로 합동인 도형 5개로 나누려고 해요. 한 도형은 정사각형 몇 개가 붙은 모양인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["합동인 조각들은 크기가 같아 정사각형의 개수도 같아요.","15개를 5조각에 똑같이 나누어요.","15 ÷ 5 = 3(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#17','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C3',3,'sa','auto','삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 110°, 각 ㄴ이 25°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M5-2-u3-C3","difficulty":3,"kind":"sa","stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 110°, 각 ㄴ이 25°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 110 − 25 = 45(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 45°예요."],"mis":"M5-2-u3-X07","variant_rule":{"alt":[{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 90°, 각 ㄴ이 30°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 90 − 30 = 60(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 60°예요."]},{"stem":"삼각형 ㄱㄴㄷ과 삼각형 ㄹㅁㅂ은 서로 합동이고, 점 ㄱ·ㄴ·ㄷ의 대응점은 차례대로 점 ㄹ·ㅁ·ㅂ이에요. 각 ㄱ이 55°, 각 ㄴ이 65°일 때 각 ㅂ은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["삼각형의 세 각의 크기의 합은 180°예요.","각 ㄷ = 180 − 55 − 65 = 60(°)예요.","각 ㅂ은 각 ㄷ의 대응각이라 60°예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#18','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C4',3,'mc','auto','평행사변형의 대각선에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u3-X09','M5-2-u3-X17']::text[],true,'{"seq":18,"concept":"M5-2-u3-C4","difficulty":3,"kind":"mc","stem":"평행사변형의 대각선에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓이를 반으로 나누지만 대칭축은 아니다","correct":true},{"t":"대칭축이다","mis":"M5-2-u3-X09"},{"t":"도형 밖에 있다","mis":"M5-2-u3-X17"},{"t":"길이가 한 변과 같다","mis":"M5-2-u3-X17"}],"explanation":["평행사변형을 대각선으로 자르면 넓이가 같은 두 삼각형이 돼요.","그런데 대각선으로 접으면 꼭짓점이 어긋나 겹치지 않아요.","넓이를 반으로 나누는 것과 접어서 겹치는 것은 다른 일이에요."],"variant_rule":{"alt":[{"stem":"직사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?","options":[{"t":"직선 ㅁㅂ","correct":true},{"t":"직선 ㄱㄴ","mis":"M5-2-u3-X08"},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X08"},{"t":"모두 대칭축이에요","mis":"M5-2-u3-X09"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㅁㅂ은 대각선 — 넓이는 반으로 나누지만 접으면 겹치지 않아요.","그래서 답은 직선 ㅁㅂ이에요."],"asset":{"type":"geo","items":[{"w":180.0,"h":120,"pts":{"ㄱ":[90.0,0,"n"],"ㄴ":[90.0,120,"s"],"ㄷ":[10.0,60,"w"],"ㄹ":[170.0,60,"e"],"ㅁ":[0.0,0,"n"],"ㅂ":[180.0,120,"s"]},"poly":[[[30.0,20],[150.0,20],[150.0,100],[30.0,100]]],"seg":[[[90.0,0],[90.0,120]],[[10.0,60],[170.0,60]],[[0.0,0],[180.0,120]]]}],"tag":false}},{"stem":"정사각형에 직선 세 개를 그었어요. 대칭축이 아닌 직선은 어느 것인가요?","options":[{"t":"직선 ㅁㅂ","correct":true},{"t":"직선 ㄱㄴ","mis":"M5-2-u3-X08"},{"t":"직선 ㄷㄹ","mis":"M5-2-u3-X08"},{"t":"모두 대칭축이에요","mis":"M5-2-u3-X09"}],"explanation":["대칭축은 접었을 때 완전히 겹치게 하는 직선이에요.","직선 ㅁㅂ은 한가운데를 지나지 않아 접으면 겹치지 않아요.","그래서 답은 직선 ㅁㅂ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄱ":[0,0,"n"],"ㄴ":[120,120,"s"],"ㄷ":[60,0,"n"],"ㄹ":[60,120,"s"],"ㅁ":[40,0,"n"],"ㅂ":[40,120,"s"]},"poly":[[[20,20],[100,20],[100,100],[20,100]]],"seg":[[[0,0],[120,120]],[[60,0],[60,120]],[[40,0],[40,120]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#19','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C5',3,'sa','auto','육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄷㅂ과 대칭축이 만나는 점이에요. 선분 ㄷㅅ이 8 cm일 때 선분 ㄷㅂ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M5-2-u3-C5","difficulty":3,"kind":"sa","stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄷㅂ과 대칭축이 만나는 점이에요. 선분 ㄷㅅ이 8 cm일 때 선분 ㄷㅂ은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["점 ㄷ과 점 ㅂ은 대응점이에요.","대칭축은 선분 ㄷㅂ을 똑같이 둘로 나눠 선분 ㅂㅅ도 8 cm예요.","8 + 8 = 16(cm)예요."],"mis":"M5-2-u3-X10","asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"],"ㅅ":[60.0,64.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]],[[120,64.0],[0,64.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅂ은 선분 ㄱㄷ과 대칭축이 만나는 점이에요. 선분 ㄱㅂ이 4 cm일 때 선분 ㄱㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["점 ㄱ과 점 ㄷ은 대응점이에요.","대칭축은 선분 ㄱㄷ을 똑같이 둘로 나눠 선분 ㄷㅂ도 4 cm예요.","4 + 4 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"],"ㅂ":[60.0,64.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]],[[0,64.0],[120,64.0]]]}],"tag":false}},{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이고, 점 ㅅ은 선분 ㄱㄴ과 대칭축이 만나는 점이에요. 선분 ㄱㅅ이 6 cm일 때 선분 ㄱㄴ은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["점 ㄱ과 점 ㄴ은 대응점이에요.","대칭축은 선분 ㄱㄴ을 똑같이 둘로 나눠 선분 ㄴㅅ도 6 cm예요.","6 + 6 = 12(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"],"ㅅ":[60.0,24.0,"ne"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]],[[20,24.0],[100,24.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#20','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C6',3,'mc','auto','모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X12']::text[],true,'{"seq":20,"concept":"M5-2-u3-C6","difficulty":3,"kind":"mc","stem":"모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄷ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄴ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":220,"h":220,"pts":{"ㄱ":[60,120,"nw"],"ㄴ":[120,60,"se"],"ㄷ":[180,120,"se"],"ㄹ":[140,40,"se"]},"seg":[[[20,20],[200,200]]],"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X12"},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄴ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄷ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":160,"h":160,"pts":{"ㄱ":[40,80,"nw"],"ㄴ":[120,80,"se"],"ㄷ":[80,40,"se"],"ㄹ":[100,20,"se"]},"seg":[[[20,20],[140,140]]],"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이에 그린 비스듬한 직선이 대칭축이에요. 선대칭도형을 그릴 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X12"},{"t":"점 ㄷ","mis":"M5-2-u3-X12"},{"t":"점 ㄱ","mis":"M5-2-u3-X12"}],"explanation":["대칭축이 비스듬해도 대칭축과 수직인 방향으로 같은 거리만큼 가요.","가로 칸만 세면(점 ㄹ) 수직이 아니라 자리가 어긋나요.","점 ㄱ과 대칭축을 사이에 두고 마주 보는 점 ㄴ이 대응점이에요."],"asset":{"type":"geo","items":[{"w":180,"h":180,"pts":{"ㄱ":[60,100,"nw"],"ㄴ":[100,60,"se"],"ㄷ":[120,40,"se"],"ㄹ":[140,100,"se"]},"seg":[[[20,20],[160,160]]],"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#21','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C9',3,'mc','auto','모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?',ARRAY['M5-2-u3-X15','M5-2-u3-X13']::text[],true,'{"seq":21,"concept":"M5-2-u3-C9","difficulty":3,"kind":"mc","stem":"모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 3칸, 아래 1칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 3칸, 아래 1칸) 대응점이에요.","그래서 점 ㄴ이에요 — 점 ㄷ·ㄹ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":160,"h":80,"pts":{"ㄱ":[20,20,"ne"],"ㅇ":[80,40,"ne"],"ㄴ":[140,60,"ne"],"ㄷ":[140,20,"ne"],"ㄹ":[20,60,"ne"]},"grid":20}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㄷ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 왼쪽 2칸, 위 1칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(왼쪽 2칸, 위 1칸) 대응점이에요.","그래서 점 ㄴ이에요 — 점 ㄹ·ㄷ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":120,"h":80,"pts":{"ㄱ":[100,60,"ne"],"ㅇ":[60,40,"ne"],"ㄴ":[20,20,"ne"],"ㄷ":[100,20,"ne"],"ㄹ":[20,60,"ne"]},"grid":20}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈종이의 점 ㅇ이 대칭의 중심이에요. 점대칭도형을 완성하려고 할 때 점 ㄱ의 대응점이 될 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X15"},{"t":"점 ㄹ","mis":"M5-2-u3-X15"},{"t":"점 ㅇ","mis":"M5-2-u3-X13"}],"explanation":["점 ㄱ에서 점 ㅇ까지 오른쪽 2칸, 위 3칸을 가요.","중심을 지나 같은 만큼 한 번 더 가면(오른쪽 2칸, 위 3칸) 대응점이에요.","그래서 점 ㄷ이에요 — 점 ㄴ·ㄹ은 가로나 세로 한쪽만 거꾸로 간, 접었을 때의 자리예요."],"asset":{"type":"geo","items":[{"w":120,"h":160,"pts":{"ㄱ":[20,140,"ne"],"ㅇ":[60,80,"ne"],"ㄴ":[100,140,"ne"],"ㄷ":[100,20,"ne"],"ㄹ":[20,20,"ne"]},"grid":20}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
