INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#23','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C8',4,'essay','teacher','현주는 점대칭도형에서 「대칭의 중심은 대응점을 이은 선분과 수직으로 만나고, 대칭축은 선분을 이등분만 해」라고 정리했어요. 잘못된 부분을 찾아 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u3-C8","difficulty":4,"kind":"essay","stem":"현주는 점대칭도형에서 「대칭의 중심은 대응점을 이은 선분과 수직으로 만나고, 대칭축은 선분을 이등분만 해」라고 정리했어요. 잘못된 부분을 찾아 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 현주는 두 성질을 바꾸어 말했다. 대응점을 이은 선분과 수직으로 만나 똑같이 둘로 나누는(수직이등분하는) 것은 선대칭도형의 대칭축이고, 대칭의 중심은 선분을 똑같이 둘로 나누기만(이등분) 하고 수직으로 만나지는 않는다.","scoring_points":["두 성질이 뒤바뀌었다고 찾았는가","대칭축은 수직이등분한다고 고쳤는가","대칭의 중심은 이등분만 한다고 고쳤는가"]},"explanation":["두 성질이 뒤바뀌었어요.","대칭축 — 수직이등분이에요.","대칭의 중심 — 이등분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#24','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C10',4,'essay','teacher','사과나무 4그루가 있는, 정사각형 12개가 붙은 땅을 학생들에게 똑같이 나누어 주려고 해요(조건: 합동인 도형 4개, 조각마다 사과나무 한 그루). 한 조각이 정사각형 몇 개인지 구하는 방법을 쓰고, 일자 모양 조각과 ㄱ자 모양 조각을 섞어 나누면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u3-C10","difficulty":4,"kind":"essay","stem":"사과나무 4그루가 있는, 정사각형 12개가 붙은 땅을 학생들에게 똑같이 나누어 주려고 해요(조건: 합동인 도형 4개, 조각마다 사과나무 한 그루). 한 조각이 정사각형 몇 개인지 구하는 방법을 쓰고, 일자 모양 조각과 ㄱ자 모양 조각을 섞어 나누면 안 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 합동인 조각은 크기가 같으므로 12 ÷ 4 = 3, 한 조각은 정사각형 3개이다. 정사각형 3개로 된 모양은 일자 모양과 ㄱ자 모양 두 가지인데, 두 모양은 넓이는 같아도 포개면 겹치지 않아 합동이 아니다. 조각들이 서로 합동이어야 똑같이 나눈 것이므로 한 가지 모양으로만 나누어야 하고, 마지막에 조각마다 나무가 한 그루씩인지 확인한다.","scoring_points":["12 ÷ 4 = 3(개)을 구했는가","일자·ㄱ자는 넓이가 같아도 합동이 아니라고 썼는가","한 가지 모양으로 나누고 나무 조건을 확인한다고 썼는가"]},"explanation":["12 ÷ 4 = 3(개)이에요.","일자와 ㄱ자는 합동이 아니에요.","한 가지 모양으로 나누고 나무를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_review_d#25','math',5,2,'u3','','g5_2_math_u3_review_d','unit_review','M5-2-u3-C4',4,'mc','auto','대칭축이 가장 많은 도형은 어느 것인가요?',ARRAY['M5-2-u3-X08']::text[],true,'{"seq":25,"concept":"M5-2-u3-C4","difficulty":4,"kind":"mc","stem":"대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정삼각형","correct":true},{"t":"마름모","mis":"M5-2-u3-X08"},{"t":"이등변삼각형","mis":"M5-2-u3-X08"},{"t":"평행사변형","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정삼각형 3개, 마름모 2개, 이등변삼각형 1개, 평행사변형 0개예요.","가장 많은 것은 정삼각형이에요"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정사각형","correct":true},{"t":"정삼각형","mis":"M5-2-u3-X08"},{"t":"직사각형","mis":"M5-2-u3-X08"},{"t":"이등변삼각형","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","정사각형 4개, 정삼각형 3개, 직사각형 2개, 이등변삼각형 1개예요.","가장 많은 것은 정사각형이에요"]},{"stem":"이번에는 다른 보기예요. 대칭축이 가장 많은 도형은 어느 것인가요?","options":[{"t":"정육각형","correct":true},{"t":"마름모","mis":"M5-2-u3-X08"},{"t":"정오각형","mis":"M5-2-u3-X08"},{"t":"직사각형","mis":"M5-2-u3-X08"}],"explanation":["도형마다 접어서 겹치는 직선을 모두 찾아요.","마름모 2개, 정육각형 6개, 정오각형 5개, 직사각형 2개예요.","가장 많은 것은 정육각형이에요"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
